import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;
import java.text.ParseException;
import java.util.Map;

class TestTimeDifferenceCalculator {

    @Test
    void testBasicTimeDifference() throws ParseException {
        Map<String, Object> result = TimeDifferenceCalculator.calculateDetailedTimeDifference(
                "2023-01-01 10:00:00", "2023-01-01 10:01:30");

        assertEquals(90L, result.get("seconds"));
        assertEquals(1L, result.get("minutes"));
        assertEquals(0L, result.get("hours"));
        assertEquals(0L, result.get("days"));
        assertEquals(0L, result.get("weeks"));
        assertTrue(result.get("humanReadable") instanceof String);
        String humanReadable = (String) result.get("humanReadable");
        assertFalse(humanReadable.isEmpty());
    }

    @Test
    void testMultipleDaysTimeDifference() throws ParseException {
        Map<String, Object> result = TimeDifferenceCalculator.calculateDetailedTimeDifference(
                "2023-01-01 00:00:00", "2023-01-08 12:30:45");

        assertEquals(649845L, result.get("seconds"));
        assertEquals(10830L, result.get("minutes"));
        assertEquals(180L, result.get("hours"));
        assertEquals(7L, result.get("days"));
        assertEquals(1L, result.get("weeks"));
        String humanReadable = (String) result.get("humanReadable");
        assertFalse(humanReadable.isEmpty());
    }

    @Test
    void testSameDateTimeDifference() throws ParseException {
        Map<String, Object> result = TimeDifferenceCalculator.calculateDetailedTimeDifference(
                "2023-01-01 10:00:00", "2023-01-01 10:00:00");

        assertEquals(0L, result.get("seconds"));
        assertEquals(0L, result.get("minutes"));
        assertEquals(0L, result.get("hours"));
        assertEquals(0L, result.get("days"));
        assertEquals(0L, result.get("weeks"));
        String humanReadable = (String) result.get("humanReadable");
        assertFalse(humanReadable.isEmpty());
    }

    @Test
    void testInvalidDateFormatThrowsException() {
        assertThrows(ParseException.class, () -> {
            TimeDifferenceCalculator.calculateDetailedTimeDifference(
                    "invalid-date", "2023-01-01 10:00:00");
        });
    }
}

