import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;
import java.util.*;

class TestPianoOctaveManager {

    @Test
    public void testAddListener() {
        PianoOctaveManager manager = new PianoOctaveManager(4, 0, 8);
        TestListener listener = new TestListener();

        manager.addListener(listener);
        manager.incrementOctave();

        assertEquals(1, listener.callCount);
        assertEquals(4, listener.lastOldOctave);
        assertEquals(5, listener.lastNewOctave);
    }

    @Test
    public void testRemoveListener() {
        PianoOctaveManager manager = new PianoOctaveManager(4, 0, 8);
        TestListener listener = new TestListener();

        manager.addListener(listener);
        manager.incrementOctave();
        assertEquals(1, listener.callCount);

        manager.removeListener(listener);
        manager.incrementOctave();
        assertEquals(1, listener.callCount); // Should not increase
    }

    @Test
    public void testMultipleListeners() {
        PianoOctaveManager manager = new PianoOctaveManager(4, 0, 8);
        TestListener listener1 = new TestListener();
        TestListener listener2 = new TestListener();

        manager.addListener(listener1);
        manager.addListener(listener2);
        manager.decrementOctave();

        assertEquals(1, listener1.callCount);
        assertEquals(1, listener2.callCount);
        assertEquals(4, listener1.lastOldOctave);
        assertEquals(3, listener1.lastNewOctave);
        assertEquals(4, listener2.lastOldOctave);
        assertEquals(3, listener2.lastNewOctave);
    }

    @Test
    public void testListenerNotNotifiedWhenOctaveDoesNotChange() {
        PianoOctaveManager manager = new PianoOctaveManager(8, 0, 8);
        TestListener listener = new TestListener();

        manager.addListener(listener);
        manager.incrementOctave(); // Should not change octave (already at max)

        assertEquals(0, listener.callCount);
    }

    private static class TestListener implements PianoOctaveManager.PianoOctaveChangeListener {
        int callCount = 0;
        int lastOldOctave = -1;
        int lastNewOctave = -1;

        @Override
        public void onOctaveChanged(int oldOctave, int newOctave) {
            callCount++;
            lastOldOctave = oldOctave;
            lastNewOctave = newOctave;
        }
    }
}

