import java.util.ArrayList;
import java.util.List;

class SubsetGenerator {
    public List<List<Integer>> generateSubsets(int[] nums) {
        List<List<Integer>> result = new ArrayList<>();
        result.add(new ArrayList<>());

        for (int i = 0; i < nums.length; i++) {
            int num = nums[i];
            List<Integer> singleElementSubset = new ArrayList<>();
            singleElementSubset.add(num);
            result.add(singleElementSubset);

            for (int j = 0; j < i; j++) {
                List<Integer> twoElementSubset = new ArrayList<>();
                twoElementSubset.add(nums[j]);
                twoElementSubset.add(num);
                result.add(twoElementSubset);
            }
        }

        return result;
    }
}

