class TestCases {
    @Test
    public void testRemoveCategoryExists() throws Exception {
        CategoryManager cm = new CategoryManager();
        cm.addCategory("工作");

        // Add some notes to the category using reflection to access the helper method
        Method addNoteMethod = CategoryManager.class.getDeclaredMethod("addNoteHelper", String.class, String.class, String.class);
        addNoteMethod.setAccessible(true);
        addNoteMethod.invoke(cm, "工作", "Meeting", "Discuss project");
        addNoteMethod.invoke(cm, "工作", "Report", "Write monthly report");

        // Remove the category
        Method removeCategoryMethod = CategoryManager.class.getDeclaredMethod("removeCategory", String.class);
        removeCategoryMethod.setAccessible(true);
        List<CategoryManager.Note> notes = (List<CategoryManager.Note>) removeCategoryMethod.invoke(cm, "工作");

        assertNotNull(notes);
        assertEquals(2, notes.size());
    }

    @Test
    public void testRemoveCategoryNotExists() throws Exception {
        CategoryManager cm = new CategoryManager();

        Method removeCategoryMethod = CategoryManager.class.getDeclaredMethod("removeCategory", String.class);
        removeCategoryMethod.setAccessible(true);
        List<CategoryManager.Note> notes = (List<CategoryManager.Note>) removeCategoryMethod.invoke(cm, "不存在");

        assertNull(notes);
    }

