class TestCases extends junit.framework.TestCase {
    @Test
    public void testAddNoteToCategorySuccess() {
        CategoryManager cm = new CategoryManager();
        cm.addCategory("工作");
        CategoryManager.Note note = new CategoryManager.Note("会议", "项目讨论");
        assertTrue(cm.addNoteToCategory("工作", note));

        List<CategoryManager.Note> notes = cm.getNotesByCategory("工作");
        assertNotNull(notes);
        assertEquals(1, notes.size());
        assertEquals("会议", notes.get(0).getTitle());
    }

    @Test
    public void testAddNoteToCategoryInvalidCategory() {
        CategoryManager cm = new CategoryManager();
        CategoryManager.Note note = new CategoryManager.Note("标题", "内容");
        assertFalse(cm.addNoteToCategory("不存在的分类", note));
    }

    @Test
    public void testAddNoteToCategoryNullCategory() {
        CategoryManager cm = new CategoryManager();
        CategoryManager.Note note = new CategoryManager.Note("标题", "内容");
        assertFalse(cm.addNoteToCategory(null, note));
    }

    @Test
    public void testAddNoteToCategoryNullNote() {
        CategoryManager cm = new CategoryManager();
        cm.addCategory("工作");
        assertFalse(cm.addNoteToCategory("工作", null));
    }

    @Test
    public void testGetNotesByCategorySuccess() {
        CategoryManager cm = new CategoryManager();
        cm.addCategory("学习");
        cm.addNoteHelper("学习", "Java", "学习Java基础");
        cm.addNoteHelper("学习", "Python", "学习Python进阶");

        List<CategoryManager.Note> notes = cm.getNotesByCategory("学习");
        assertNotNull(notes);
        assertEquals(2, notes.size());

        // Verify it's a copy by modifying the returned list
        notes.add(new CategoryManager.Note("临时", "临时笔记"));
        // Original should not be affected
        assertEquals(2, cm.getNotesByCategory("学习").size());
    }

    @Test
    public void testGetNotesByCategoryInvalidCategory() {
        CategoryManager cm = new CategoryManager();
        assertNull(cm.getNotesByCategory("不存在的分类"));
    }

    @Test
    public void testGetNotesByCategoryNullCategory() {
        CategoryManager cm = new CategoryManager();
        assertNull(cm.getNotesByCategory(null));
    }
}

