import java.util.*;
import java.util.function.Supplier;
import java.util.function.Consumer;
import java.util.function.Function;
import java.util.function.Predicate;

class EnhancedTestUtils {
    public static <T, R> List<R> createEnhancedList(int count, Supplier<T> supplier) {
        return createEnhancedList(count, supplier, null, null);
    }

    public static <T, R> List<R> createEnhancedList(int count, Supplier<T> supplier, Consumer<T> validator) {
        return createEnhancedList(count, supplier, validator, null);
    }

    @SuppressWarnings("unchecked")
    public static <T, R> List<R> createEnhancedList(int count, Supplier<T> supplier, Consumer<T> validator, Function<T, R> transformer) {
        if (count < 0) {
            throw new IllegalArgumentException("Count must be non-negative");
        }
        if (supplier == null) {
            throw new IllegalArgumentException("Supplier cannot be null");
        }

        List<R> result = new ArrayList<>();
        for (int i = 0; i < count; i++) {
            T element = supplier.get();
            if (validator != null) {
                try {
                    validator.accept(element);
                } catch (RuntimeException e) {
                    throw new RuntimeException("Validation failed for element: " + element, e);
                }
            }

            R finalElement;
            if (transformer != null) {
                finalElement = transformer.apply(element);
            } else {
                // When transformer is null, assume T and R are the same type
                // Use identity function behavior
                finalElement = ((Function<T, R>) Function.<T>identity()).apply(element);
            }
            result.add(finalElement);
        }
        return result;
    }

    public static <T, E extends Exception> Consumer<T> enhancedExceptionExpectation(Class<E> expectedExceptionClass, Predicate<E> validator, Consumer<T> operation) {
        return (T input) -> {
            Exception thrownException = null;
            try {
                operation.accept(input);
            } catch (Exception e) {
                thrownException = e;
            }

            if (thrownException == null) {
                throw new AssertionError("Expected exception of type " + expectedExceptionClass.getSimpleName() + " but no exception was thrown.");
            }

            if (!expectedExceptionClass.isInstance(thrownException)) {
                throw new AssertionError("Expected exception of type " + expectedExceptionClass.getSimpleName() + " but got " + thrownException.getClass().getSimpleName() + " instead.");
            }

            @SuppressWarnings("unchecked")
            E castedException = (E) thrownException;

            if (validator != null && !validator.test(castedException)) {
                throw new AssertionError("Thrown exception of type " + expectedExceptionClass.getSimpleName() + " failed validation.");
            }
        };
    }
}

