import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Arrays;
import java.util.List;
import static org.junit.jupiter.api.Assertions.*;

class TestCases {
    @TempDir
    Path tempDir;

    @Test
    void testAppendFalseOverwritesFile() throws IOException {
        Path testFile = tempDir.resolve("test.txt");
        FileOperationsManager manager = new FileOperationsManager();

        List<String> firstLines = Arrays.asList("First line");
        List<String> secondLines = Arrays.asList("Second line");

        assertTrue(manager.writeToFile(testFile.toString(), firstLines, false));
        assertTrue(manager.writeToFile(testFile.toString(), secondLines, false));

        List<String> content = Files.readAllLines(testFile);
        assertEquals(1, content.size());
        assertEquals("Second line", content.get(0));
    }

    @Test
    void testAppendTrueAppendsToFile() throws IOException {
        Path testFile = tempDir.resolve("test.txt");
        FileOperationsManager manager = new FileOperationsManager();

        List<String> firstLines = Arrays.asList("First line");
        List<String> secondLines = Arrays.asList("Second line");

        assertTrue(manager.writeToFile(testFile.toString(), firstLines, true));
        assertTrue(manager.writeToFile(testFile.toString(), secondLines, true));

        List<String> content = Files.readAllLines(testFile);
        assertEquals(2, content.size());
        assertEquals("First line", content.get(0));
        assertEquals("Second line", content.get(1));
    }

    @Test
    void testCreatesParentDirectories() {
        Path nestedDir = tempDir.resolve("nested").resolve("subdir");
        Path testFile = nestedDir.resolve("test.txt");
        FileOperationsManager manager = new FileOperationsManager();

        List<String> lines = Arrays.asList("Test content");

        assertTrue(manager.writeToFile(testFile.toString(), lines, false));
        assertTrue(Files.exists(nestedDir));
        assertTrue(Files.exists(testFile));
    }
}

