        List<String> content = Arrays.asList("Line 1", "Line 2", "Line 3");
        Files.write(testFile, content, java.nio.charset.StandardCharsets.UTF_8);

        List<String> result = manager.readFromFile(testFile.toString());
        assertEquals(content, result);
