import org.json.JSONObject;
import java.util.List;
import static org.junit.jupiter.api.Assertions.*;

class TestCases {
    @org.junit.jupiter.api.Test
    void testLobbyMemberCreation() {
        LobbyMember member = new LobbyMember("1", "Alice", 3, true);
        assertEquals("1", member.getId());
        assertEquals("Alice", member.getName());
        assertEquals(3, member.getColorIndex());
        assertTrue(member.isReady());
    }

    @org.junit.jupiter.api.Test
    void testAddMemberWithLobbyMemberObject() {
        JSONObject lobbyJson = new JSONObject();
        lobbyJson.put("ownerId", "owner1");

        EnhancedLobbyManager manager = new EnhancedLobbyManager(lobbyJson, "lobby1");

        JSONObject memberJson = new JSONObject();
        memberJson.put("id", "member1");
        memberJson.put("name", "Bob");
        memberJson.put("colorIndex", 2);
        memberJson.put("isReady", false);

        assertTrue(manager.addMember(memberJson));

        List<LobbyMember> members = manager.getMembers();
        assertEquals(1, members.size());

        LobbyMember member = members.get(0);
        assertEquals("member1", member.getId());
        assertEquals("Bob", member.getName());
        assertEquals(2, member.getColorIndex());
        assertFalse(member.isReady());
    }

    @org.junit.jupiter.api.Test
    void testAddDuplicateMember() {
        JSONObject lobbyJson = new JSONObject();
        lobbyJson.put("ownerId", "owner1");

        EnhancedLobbyManager manager = new EnhancedLobbyManager(lobbyJson, "lobby1");

        JSONObject memberJson1 = new JSONObject();
        memberJson1.put("id", "member1");
        memberJson1.put("name", "Bob");
        memberJson1.put("colorIndex", 2);
        memberJson1.put("isReady", false);

        JSONObject memberJson2 = new JSONObject();
        memberJson2.put("id", "member1");
        memberJson2.put("name", "Bobby");
        memberJson2.put("colorIndex", 3);
        memberJson2.put("isReady", true);

        assertTrue(manager.addMember(memberJson1));
        assertFalse(manager.addMember(memberJson2)); // Should fail as member already exists

        List<LobbyMember> members = manager.getMembers();
        assertEquals(1, members.size());

        LobbyMember member = members.get(0);
        assertEquals("member1", member.getId());
        assertEquals("Bob", member.getName());
        assertEquals(2, member.getColorIndex());
        assertFalse(member.isReady());
    }
}

