    void testSetMessageHandlerOnlyRegistersWhenConnectionIsActive() {
        EnhancedWebSocketClient client = new EnhancedWebSocketClient("ws://test");
        AtomicReference<String> receivedMessage = new AtomicReference<>();

        // Set handler before connection
        client.setMessageHandler(receivedMessage::set);

        // Connect and verify handler works
        client.connectAsync().join();

        // Simulate receiving a ByteBuffer message
        ByteBuffer buffer = StandardCharsets.UTF_8.encode("test message");
        client.connection.simulateMessage(buffer);

        assertEquals("test message", receivedMessage.get());
    }

