    void testSetMessageHandlerDoesNotRegisterWhenConnectionIsClosed() {
        EnhancedWebSocketClient client = new EnhancedWebSocketClient("ws://test");
        AtomicReference<String> receivedMessage = new AtomicReference<>();

        // Connect first
        client.connectAsync().join();

        // Close connection
        client.closeAsync().join();

        // Try to set handler after connection is closed
        client.setMessageHandler(receivedMessage::set);

