import java.util.concurrent.CompletableFuture;
import java.util.function.Consumer;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;

public class EnhancedWebSocketClient {
    WebSocketConnection connection; // Made package-private for testing
    private Consumer<String> messageHandler;

    public EnhancedWebSocketClient(String uri) {
        // Constructor implementation - store URI if needed later
    }

    public CompletableFuture<Void> connectAsync() {
        return WebSocketConnection.createAsync().thenAccept(conn -> {
            this.connection = conn;
            if (this.messageHandler != null) {
                this.connection.setMessageHandler(this.messageHandler);
            }
        });
    }

    public CompletableFuture<Void> sendMessageAsync(String message) {
        if (connection == null || !connection.isConnected()) {
            return CompletableFuture.failedFuture(new IllegalStateException("Connection is not established or is closed"));
        }
        return connection.writeAsync(message);
    }

    public void setMessageHandler(Consumer<String> handler) {
        this.messageHandler = handler;
        if (connection != null && connection.isConnected()) {
            connection.setMessageHandler(handler);
        }
    }

    public CompletableFuture<Void> closeAsync() {
        if (connection == null || !connection.isConnected()) {
            return CompletableFuture.completedFuture(null);
        }
        connection.close();
        return CompletableFuture.completedFuture(null);
    }

    public static class WebSocketConnection {
        private Consumer<ByteBuffer> messageHandler;
        private boolean connected = true;
        private boolean closeCalled = false; // Track if close() was called

        public static CompletableFuture<WebSocketConnection> createAsync() {
            return CompletableFuture.completedFuture(new WebSocketConnection());
        }

        public CompletableFuture<Void> writeAsync(String message) {
            return CompletableFuture.completedFuture(null);
        }

        public void setMessageHandler(Consumer<String> handler) {
            this.messageHandler = buffer -> {
                String message = StandardCharsets.UTF_8.decode(buffer).toString();
                handler.accept(message);
            };
        }

        public boolean isConnected() {
            return connected;
        }

        public void close() {
            this.closeCalled = true;
            this.connected = false;
        }

        public boolean wasCloseCalled() {
            return closeCalled;
        }

        // Method to simulate receiving a ByteBuffer message for testing
        public void simulateMessage(ByteBuffer buffer) {
            if (messageHandler != null) {
                messageHandler.accept(buffer);
            }
        }
    }
}

