import java.util.List;
import java.util.Map;
import java.util.HashMap;
import java.util.ArrayList;

class DataProcessor {

    public Map<String, Object> processPoolData(List<Pool> pools) {
        Map<String, Object> result = new HashMap<>();
        result.put("count", pools.size());

        List<Pool> activePools = new ArrayList<>();
        List<Pool> specialPools = new ArrayList<>();

        for (Pool pool : pools) {
            if ("287".equals(pool.getSearch_id())) {
                specialPools.add(pool);
            } else {
                activePools.add(pool);
            }
        }

        result.put("active_pools", activePools);
        result.put("special_pools", specialPools);

        Map<String, Integer> nameLengthStats = new HashMap<>();
        if (!pools.isEmpty()) {
            int maxLength = 0;
            int minLength = Integer.MAX_VALUE;
            for (Pool pool : pools) {
                int length = pool.getName().length();
                if (length > maxLength) maxLength = length;
                if (length < minLength) minLength = length;
            }
            nameLengthStats.put("max", maxLength);
            nameLengthStats.put("min", minLength);
        }
        result.put("name_length_stats", nameLengthStats);

        return result;
    }

    public static class Pool {
        private String name;
        private String search_id;
        private String image;

        public Pool(String name, String search_id, String image) {
            this.name = name;
            this.search_id = search_id;
            this.image = image;
        }

        public String getName() { return name; }
        public String getSearch_id() { return search_id; }
        public String getImage() { return image; }
    }
}

