            this.lineCount = lineCount;
            this.wordCount = wordCount;
            this.characterCount = characterCount;
            this.averageWordsPerLine = averageWordsPerLine;
        }

        @Override
        public String toString() {
            return String.format("FileStats{lineCount=%d, wordCount=%d, characterCount=%d, averageWordsPerLine=%.2f}", 
                               lineCount, wordCount, characterCount, averageWordsPerLine);
        }
    }

    public static FileStats analyzeFileContent(File file) {
        return new FileStats(0, 0, 0, 0.0);
    }
}

