    void testWordCountCalculation() throws IOException {
        // Test file with multiple words per line
        String content = "Hello world\nThis is a test\nSingle";
        Files.write(tempFile.toPath(), content.getBytes());

        EnhancedFileOperations.FileStats stats = EnhancedFileOperations.analyzeFileContent(tempFile);

        assertEquals(3, stats.lineCount);
        assertEquals(7, stats.wordCount); // "Hello world" (2) + "This is a test" (4) + "Single" (1) = 7
        assertEquals(2.33, stats.averageWordsPerLine, 0.01); // 7 words / 3 lines = 2.33
    }

    @Test
    void testWordCountWithMultipleSpaces() throws IOException {
        // Test file with multiple spaces between words
        String content = "Hello    world\nThis   is    a   test";
        Files.write(tempFile.toPath(), content.getBytes());

        EnhancedFileOperations.FileStats stats = EnhancedFileOperations.analyzeFileContent(tempFile);

        assertEquals(2, stats.lineCount);
        assertEquals(6, stats.wordCount); // Should handle multiple spaces correctly
        assertEquals(3.0, stats.averageWordsPerLine, 0.01); // 6 words / 2 lines
    }

    @Test
    void testEmptyFileWordCount() throws IOException {
        // Test empty file
        Files.write(tempFile.toPath(), "".getBytes());

        EnhancedFileOperations.FileStats stats = EnhancedFileOperations.analyzeFileContent(tempFile);

        assertEquals(0, stats.lineCount);
        assertEquals(0, stats.wordCount);
        assertEquals(0.0, stats.averageWordsPerLine, 0.01); // Should handle division by zero
    }

    @Test
    void testEmptyLinesWordCount() throws IOException {
        // Test file with empty lines
        String content = "Hello\n\nworld";
        Files.write(tempFile.toPath(), content.getBytes());

        EnhancedFileOperations.FileStats stats = EnhancedFileOperations.analyzeFileContent(tempFile);

        assertEquals(3, stats.lineCount);
        assertEquals(2, stats.wordCount); // Only "Hello" and "world", empty line contributes 0 words
        assertEquals(0.67, stats.averageWordsPerLine, 0.01); // 2 words / 3 lines
    }
}

