        Field schedulerField = ThreadResourceManager.class.getDeclaredField("scheduler");
        schedulerField.setAccessible(true);
        ScheduledExecutorService scheduler = (ScheduledExecutorService) schedulerField.get(manager);

        assertNotNull(scheduler, "Scheduler should be initialized in constructor");
    }

    @Test
    void testAutomaticThreadCleanup() throws InterruptedException {
        ThreadResourceManager manager = new ThreadResourceManager();

        // Create a short-lived thread that will die quickly
        Runnable shortTask = () -> {
            try {
                Thread.sleep(100); // Sleep for 100ms then die
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        };

        manager.createDaemonThread("shortThread", shortTask);

        // Initially the thread should be tracked
        assertEquals(1, manager.getActiveThreadCount(), "Thread should be tracked initially");

        // Wait for the thread to complete and the cleanup task to run
        Thread.sleep(1500); // Wait more than 1 second for cleanup

        // The dead thread should be automatically removed
        assertEquals(0, manager.getActiveThreadCount(), "Dead thread should be automatically removed");
    }
}

