import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;

class TestPollingQueue {

    @Test
    public void testResetPollingCount() {
        PollingQueue<String> queue = new PollingQueue<>(5);

        // Perform some polling operations to increment the count
        queue.poll();
        queue.poll();
        queue.poll();

        // Verify count is greater than 0
        assertTrue(queue.getPollingCount() > 0);

        // Reset the polling count
        queue.resetPollingCount();

        // Verify count is now 0
        assertEquals(0, queue.getPollingCount());
    }

    @Test
    public void testGetPollingCount() {
        PollingQueue<String> queue = new PollingQueue<>(10);

        // Initially, polling count should be 0
        assertEquals(0, queue.getPollingCount());

        // After one poll, count should be 1
        queue.poll();
        assertEquals(1, queue.getPollingCount());

        // After another poll, count should be 2
        queue.poll();
        assertEquals(2, queue.getPollingCount());
    }

    @Test
    public void testPollingCountAfterReset() {
        PollingQueue<String> queue = new PollingQueue<>(3);

        // Poll twice to increment count
        queue.poll();
        queue.poll();
        assertEquals(2, queue.getPollingCount());

        // Reset and verify
        queue.resetPollingCount();
        assertEquals(0, queue.getPollingCount());

        // Poll again after reset - should start from 1
        queue.poll();
        assertEquals(1, queue.getPollingCount());
    }

    @Test
    public void testResetAllowsMorePolling() {
        PollingQueue<String> queue = new PollingQueue<>(2);

        // Poll up to the limit
        queue.poll();
        queue.poll();
        assertEquals(2, queue.getPollingCount());

        // Next poll should throw exception
        assertThrows(IllegalStateException.class, () -> queue.poll());

        // Reset the count
        queue.resetPollingCount();
        assertEquals(0, queue.getPollingCount());

        // Should be able to poll again without exception
        assertDoesNotThrow(() -> queue.poll());
        assertEquals(1, queue.getPollingCount());
    }
}

