        PollingQueue<String> queue2 = new PollingQueue<>(10);

        queue1.enqueue("item1");
        queue2.enqueue("item1");

        assertFalse(queue1.equals(queue2));
    }

    @Test
    public void testNotEqualsWithDifferentPollingCount() {
        PollingQueue<String> queue1 = new PollingQueue<>(5);
        PollingQueue<String> queue2 = new PollingQueue<>(5);

        queue1.enqueue("item1");
        queue2.enqueue("item1");

        // Make polling counts different
        queue1.poll();

        assertFalse(queue1.equals(queue2));
    }

    @Test
    public void testNotEqualsWithDifferentQueueContents() {
        PollingQueue<String> queue1 = new PollingQueue<>(5);
        PollingQueue<String> queue2 = new PollingQueue<>(5);

        queue1.enqueue("item1");
        queue2.enqueue("item2");

        assertFalse(queue1.equals(queue2));
    }

    @Test
    public void testEqualsWithSamePollingCount() {
        PollingQueue<String> queue1 = new PollingQueue<>(5);
        PollingQueue<String> queue2 = new PollingQueue<>(5);

        queue1.enqueue("item1");
        queue1.enqueue("item2");
        queue2.enqueue("item1");
        queue2.enqueue("item2");

        // Both poll once to have same polling count
        queue1.poll();
        queue2.poll();

        assertTrue(queue1.equals(queue2));
        assertEquals(queue1.hashCode(), queue2.hashCode());
    }

    @Test
    public void testEqualsWithNull() {
