        assertTrue(output.contains("3,456,789 ns"), "Binary Search time should be formatted with commas");
    }

    @Test
    public void testEggDropResultFormatsSmallNumbers() {
        // Test with small numbers that don't need commas
        EggDropSolver.Result result = new EggDropSolver.Result(2, 2, 2, 123L, 456L, 789L);
        EggDropSolver.EggDropResult eggDropResult = new EggDropSolver.EggDropResult(result);

