        assertTrue(output.contains("456 ns"), "Small Math time should be formatted without commas");
        assertTrue(output.contains("789 ns"), "Small Binary Search time should be formatted without commas");
    }

    @Test
    public void testEggDropResultFormatConsistentAcrossLocales() {
        // Save current locale
        Locale originalLocale = Locale.getDefault();

        try {
            // Test with different locales to ensure consistent comma formatting
            Locale[] testLocales = {Locale.US, Locale.GERMANY, Locale.FRANCE};

            for (Locale locale : testLocales) {
                Locale.setDefault(locale);

                EggDropSolver.Result result = new EggDropSolver.Result(3, 3, 3, 1000000L, 2000000L, 3000000L);
                EggDropSolver.EggDropResult eggDropResult = new EggDropSolver.EggDropResult(result);

                String output = eggDropResult.formatOutput();

                // Verify comma formatting is consistent regardless of locale
                assertTrue(output.contains("1,000,000 ns"), "Should use comma separator in " + locale);
                assertTrue(output.contains("2,000,000 ns"), "Should use comma separator in " + locale);
                assertTrue(output.contains("3,000,000 ns"), "Should use comma separator in " + locale);

                // Ensure it doesn't use locale-specific separators like periods
                assertFalse(output.contains("1.000.000 ns"), "Should not use period separator in " + locale);
                assertFalse(output.contains("1 000 000 ns"), "Should not use space separator in " + locale);
            }
        } finally {
            // Restore original locale
            Locale.setDefault(originalLocale);
        }
    }

    @Test
    public void testEggDropResultOutputFormat() {
        // Test the exact format of the output string
        EggDropSolver.Result result = new EggDropSolver.Result(5, 5, 5, 12345L, 67890L, 54321L);
        EggDropSolver.EggDropResult eggDropResult = new EggDropSolver.EggDropResult(result);

