        assertTrue(lines[0].endsWith(" ns)"), "First line should end with ns)");

        assertTrue(lines[1].startsWith("Math Solution: 5 (Time: "), "Second line should start with Math Solution");
        assertTrue(lines[1].endsWith(" ns)"), "Second line should end with ns)");

        assertTrue(lines[2].startsWith("Binary Search Solution: 5 (Time: "), "Third line should start with Binary Search Solution");
        assertTrue(lines[2].endsWith(" ns)"), "Third line should end with ns)");
    }
}

