                // This regex checks for numbers with exactly 2 decimal places
                assertTrue(step.matches(".*\\d+\\.\\d{2}.*") || !step.matches(".*\\d+\\.\\d+.*"), 
                          "All floating point numbers should be formatted to exactly 2 decimal places: " + step);
            }
        }

        // Specifically check the color line
