        parameterMappings.put("h", "h");
        parameterMappings.put("i", "i");
        parameterMappings.put("j", "j");
        parameterMappings.put("k", "k");
    }

    public Map<String, String> processParameter(String paramName, int strategy) {
        Map<String, String> result = new HashMap<>();
