        switch (strategy) {
            case 1:
                result.put("processedValue", directProcessing(paramName));
                break;
            case 2:
                result.put("processedValue", mappedProcessing(paramName));
                break;
            case 3:
                result.put("processedValue", chainedProcessing(paramName));
                break;
            case 4:
                result.put("processedValue", mixedProcessing(paramName));
                break;
            default:
                result.put("processedValue", "invalid_strategy");
                break;
        }

        result.put("strategyUsed", String.valueOf(strategy));
        result.put("mappingUsed", parameterMappings.getOrDefault(paramName, "default"));
        return result;
    }

    private String directProcessing(String paramName) {
        return "direct_value_for_" + paramName;
    }

    private String mappedProcessing(String paramName) {
        String mappedName = parameterMappings.getOrDefault(paramName, paramName);
        return "mapped_" + mappedName + "_value_for_" + paramName;
    }

    private String chainedProcessing(String paramName) {
        String step1 = "step1_" + paramName;
        return "step2_" + step1;
    }

    private String mixedProcessing(String paramName) {
        String directResult = directProcessing(paramName);
        String mappedResult = mappedProcessing(paramName);
