import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;
import java.util.List;

class TestTicTacToeGame {

    @Test
    public void testBoardInitialization() {
        TicTacToeGame game = new TicTacToeGame(3);
        List<String> board = game.getBoardState();
        assertEquals(3, board.size());
        for (String row : board) {
            assertEquals("---", row);
        }
    }

    @Test
    public void testInitialPlayer() {
        TicTacToeGame game = new TicTacToeGame(3);
        assertEquals('X', game.getCurrentPlayer());
    }

    @Test
    public void testMakeValidMove() {
        TicTacToeGame game = new TicTacToeGame(3);
        assertTrue(game.makeMove(0, 0));
        List<String> board = game.getBoardState();
        assertEquals("X--", board.get(0));
        assertEquals('O', game.getCurrentPlayer());
    }

    @Test
    public void testMakeInvalidMove() {
        TicTacToeGame game = new TicTacToeGame(3);
        game.makeMove(0, 0);
        assertFalse(game.makeMove(0, 0));
        assertEquals('O', game.getCurrentPlayer());
    }

    @Test
    public void testPlayerAlternation() {
        TicTacToeGame game = new TicTacToeGame(3);
        game.makeMove(0, 0); // X
        game.makeMove(0, 1); // O
        game.makeMove(0, 2); // X
        List<String> board = game.getBoardState();
        assertEquals("XOX", board.get(0));
        assertEquals('O', game.getCurrentPlayer());
    }

    @Test
    public void testDifferentBoardSizes() {
        TicTacToeGame game2x2 = new TicTacToeGame(2);
        List<String> board2x2 = game2x2.getBoardState();
        assertEquals(2, board2x2.size());
        assertEquals("--", board2x2.get(0));

        TicTacToeGame game4x4 = new TicTacToeGame(4);
        List<String> board4x4 = game4x4.getBoardState();
        assertEquals(4, board4x4.size());
        assertEquals("----", board4x4.get(0));
    }
}

