class TestMinesweeperSolver {

    @org.junit.jupiter.api.Test
    public void testAdjacentMineCountsCalculated() {
        MinesweeperSolver solver = new MinesweeperSolver();
        List<String> mines = Arrays.asList("2,2");

        solver.solveMinesweeper(3, mines);

        // Verify mine is placed correctly
        assertEquals('*', solver.getCellValue(2, 2));

        // Verify adjacent cells have correct mine counts
        assertEquals('1', solver.getCellValue(1, 1)); // diagonal neighbor
        assertEquals('1', solver.getCellValue(1, 2)); // top neighbor
        assertEquals('1', solver.getCellValue(1, 3)); // diagonal neighbor
        assertEquals('1', solver.getCellValue(2, 1)); // left neighbor
        assertEquals('1', solver.getCellValue(2, 3)); // right neighbor
        assertEquals('1', solver.getCellValue(3, 1)); // diagonal neighbor
        assertEquals('1', solver.getCellValue(3, 2)); // bottom neighbor
        assertEquals('1', solver.getCellValue(3, 3)); // diagonal neighbor
    }

    @org.junit.jupiter.api.Test
    public void testMultipleMinesAdjacentCounts() {
        MinesweeperSolver solver = new MinesweeperSolver();
        List<String> mines = Arrays.asList("1,1", "1,3");

        solver.solveMinesweeper(3, mines);

        // Verify mines are placed
        assertEquals('*', solver.getCellValue(1, 1));
        assertEquals('*', solver.getCellValue(1, 3));

        // Cell (1,2) should have count of 2 (adjacent to both mines)
        assertEquals('2', solver.getCellValue(1, 2));

        // Cell (2,2) should have count of 2 (diagonal to both mines)
        assertEquals('2', solver.getCellValue(2, 2));

        // Corner cells should have count of 1
        assertEquals('1', solver.getCellValue(2, 1));
        assertEquals('1', solver.getCellValue(2, 3));
    }

    @org.junit.jupiter.api.Test
    public void testZeroMineCount() {
        MinesweeperSolver solver = new MinesweeperSolver();
        List<String> mines = Arrays.asList("1,1");

        solver.solveMinesweeper(3, mines);

        // Cell (3,3) should have count of 0 (no adjacent mines)
        assertEquals('0', solver.getCellValue(3, 3));
    }
}

