import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import org.junit.jupiter.api.Test;

class TestMinesweeperSolver {

    @Test
    public void testDfsRevealSingle0Cell() {
        MinesweeperSolver solver = new MinesweeperSolver();
        List<String> mines = Arrays.asList("1,1");
        solver.solveMinesweeper(4, mines);

        // Click on cell (3,3) which should be '0'
        assertEquals('0', solver.getCellValue(3, 3));
        solver.dfsReveal(3, 3);

        // The 0-cell should be visited
        assertTrue(solver.isVisited(3, 3));

        // All adjacent numbered cells should also be visited
        assertTrue(solver.isVisited(2, 2)); // Should be '1'
        assertTrue(solver.isVisited(2, 3)); // Should be '1' 
        assertTrue(solver.isVisited(3, 2)); // Should be '1'
        assertTrue(solver.isVisited(3, 4)); // Should be '0'
        assertTrue(solver.isVisited(4, 3)); // Should be '0'
        assertTrue(solver.isVisited(4, 4)); // Should be '0'

        // Mine cell should not be visited
        assertFalse(solver.isVisited(1, 1)); // Mine
    }

    @Test
    public void testDfsRevealConnected0Cells() {
        MinesweeperSolver solver = new MinesweeperSolver();
        List<String> mines = Arrays.asList("1,1");
        solver.solveMinesweeper(4, mines);

        // Click on cell (4,4) which should be '0'
        assertEquals('0', solver.getCellValue(4, 4));
        solver.dfsReveal(4, 4);

        // Multiple connected 0-cells should be revealed
        assertTrue(solver.isVisited(4, 4)); // 0-cell
        assertTrue(solver.isVisited(3, 3)); // 0-cell
        assertTrue(solver.isVisited(3, 4)); // 0-cell
        assertTrue(solver.isVisited(4, 3)); // 0-cell

        // Adjacent numbered cells should also be visited
        assertTrue(solver.isVisited(2, 2)); // Should be '1'
        assertTrue(solver.isVisited(2, 3)); // Should be '1'
        assertTrue(solver.isVisited(3, 2)); // Should be '1'
    }

    @Test
    public void testDfsRevealNumberedCellDoesNotPropagate() {
        MinesweeperSolver solver = new MinesweeperSolver();
        List<String> mines = Arrays.asList("1,1");
        solver.solveMinesweeper(3, mines);

        // Click on cell (2,2) which should be '1' (numbered cell)
        assertEquals('1', solver.getCellValue(2, 2));
        solver.dfsReveal(2, 2);

        // Only the clicked numbered cell should be visited
        assertTrue(solver.isVisited(2, 2));

        // Adjacent cells should NOT be automatically visited
        assertFalse(solver.isVisited(2, 3));
        assertFalse(solver.isVisited(3, 2));
        assertFalse(solver.isVisited(3, 3));
    }
}

