    void testSingleNodeTree() {
        ScenarioAnalyzer analyzer = new ScenarioAnalyzer();
        ScenarioAnalyzer.TreeNode root = new ScenarioAnalyzer.TreeNode("root");

        Map<String, Object> result = analyzer.analyzeScenario(root);
        Map<String, Integer> nodeIndices = (Map<String, Integer>) result.get("nodeIndices");

        assertEquals(1, nodeIndices.size());
        assertEquals(0, nodeIndices.get("root"));
    }

    @Test
    void testBreadthFirstIndexing() {
        ScenarioAnalyzer analyzer = new ScenarioAnalyzer();
        ScenarioAnalyzer.TreeNode root = new ScenarioAnalyzer.TreeNode("A");
        ScenarioAnalyzer.TreeNode b = new ScenarioAnalyzer.TreeNode("B");
        ScenarioAnalyzer.TreeNode c = new ScenarioAnalyzer.TreeNode("C");
        ScenarioAnalyzer.TreeNode d = new ScenarioAnalyzer.TreeNode("D");
        ScenarioAnalyzer.TreeNode e = new ScenarioAnalyzer.TreeNode("E");

        root.addChild(b);
        root.addChild(c);
        b.addChild(d);
        b.addChild(e);

        Map<String, Object> result = analyzer.analyzeScenario(root);
        Map<String, Integer> nodeIndices = (Map<String, Integer>) result.get("nodeIndices");

        assertEquals(0, nodeIndices.get("A")); // root
        assertEquals(1, nodeIndices.get("B")); // level 1
        assertEquals(2, nodeIndices.get("C")); // level 1
        assertEquals(3, nodeIndices.get("D")); // level 2
        assertEquals(4, nodeIndices.get("E")); // level 2
    }

    @Test
