class TestScenarioAnalyzer {

    @org.junit.jupiter.api.Test
    void testSyncPairsDetection() {
        ScenarioAnalyzer analyzer = new ScenarioAnalyzer();

        // Create a tree with sync request-response pair
        ScenarioAnalyzer.TreeNode root = new ScenarioAnalyzer.TreeNode("root", false, "serverA");
        ScenarioAnalyzer.TreeNode request = new ScenarioAnalyzer.TreeNode("request", true, null);
        ScenarioAnalyzer.TreeNode response = new ScenarioAnalyzer.TreeNode("response", false, "serverA");

        root.addChild(request);
        request.addChild(response);

        Map<String, Object> result = analyzer.analyzeScenario(root);

        // Verify syncPairs key exists
        assertTrue(result.containsKey("syncPairs"));

        @SuppressWarnings("unchecked")
        Map<Integer, Integer> syncPairs = (Map<Integer, Integer>) result.get("syncPairs");

        // Should detect the sync pair: request (index 1) -> response (index 2)
        assertEquals(1, syncPairs.size());
        assertTrue(syncPairs.containsKey(1)); // request index
        assertEquals(Integer.valueOf(2), syncPairs.get(1)); // response index
    }

    @org.junit.jupiter.api.Test
    void testNoSyncPairsWhenNoMatch() {
        ScenarioAnalyzer analyzer = new ScenarioAnalyzer();

        // Create a tree with sync node but no matching serverName
        ScenarioAnalyzer.TreeNode root = new ScenarioAnalyzer.TreeNode("root", false, "serverA");
        ScenarioAnalyzer.TreeNode request = new ScenarioAnalyzer.TreeNode("request", true, null);
        ScenarioAnalyzer.TreeNode response = new ScenarioAnalyzer.TreeNode("response", false, "serverB");

        root.addChild(request);
        request.addChild(response);

        Map<String, Object> result = analyzer.analyzeScenario(root);

        @SuppressWarnings("unchecked")
        Map<Integer, Integer> syncPairs = (Map<Integer, Integer>) result.get("syncPairs");

        // Should not detect any sync pairs
        assertEquals(0, syncPairs.size());
    }

    @org.junit.jupiter.api.Test
    void testEmptyTreeSyncPairs() {
        ScenarioAnalyzer analyzer = new ScenarioAnalyzer();

        Map<String, Object> result = analyzer.analyzeScenario(null);

        assertTrue(result.containsKey("syncPairs"));
        @SuppressWarnings("unchecked")
        Map<Integer, Integer> syncPairs = (Map<Integer, Integer>) result.get("syncPairs");
        assertEquals(0, syncPairs.size());
    }
}

