        ScenarioAnalyzer.TreeNode syncRequest = new ScenarioAnalyzer.TreeNode("request1", true, null);
        ScenarioAnalyzer.TreeNode response1 = new ScenarioAnalyzer.TreeNode("response1", false, "serverA");
        ScenarioAnalyzer.TreeNode response2 = new ScenarioAnalyzer.TreeNode("response2", false, "serverA");

        root.addChild(syncRequest);
        syncRequest.addChild(response1);
        syncRequest.addChild(response2);

        Map<String, Object> result = analyzer.analyzeScenario(root);
        Map<Integer, List<Integer>> syncPairs = (Map<Integer, List<Integer>>) result.get("syncPairs");

        // The sync request should map to a list containing both response indices
        assertTrue(syncPairs.containsKey(1)); // request1 index
        List<Integer> responses = syncPairs.get(1);
        assertEquals(2, responses.size());
        assertTrue(responses.contains(2)); // response1 index
        assertTrue(responses.contains(3)); // response2 index
    }

    @org.junit.jupiter.api.Test
    void testSyncPairsIsListType() {
        ScenarioAnalyzer analyzer = new ScenarioAnalyzer();

        // Create a simple scenario with one sync pair
        ScenarioAnalyzer.TreeNode root = new ScenarioAnalyzer.TreeNode("root", false, "serverA");
        ScenarioAnalyzer.TreeNode syncRequest = new ScenarioAnalyzer.TreeNode("request1", true, null);
        ScenarioAnalyzer.TreeNode response = new ScenarioAnalyzer.TreeNode("response1", false, "serverA");

        root.addChild(syncRequest);
        syncRequest.addChild(response);

        Map<String, Object> result = analyzer.analyzeScenario(root);
        Map<Integer, List<Integer>> syncPairs = (Map<Integer, List<Integer>>) result.get("syncPairs");

        // Verify that syncPairs values are Lists, not single integers
        assertTrue(syncPairs.containsKey(1));
        Object value = syncPairs.get(1);
        assertTrue(value instanceof List);
        List<Integer> responseList = (List<Integer>) value;
        assertEquals(1, responseList.size());
        assertEquals(Integer.valueOf(2), responseList.get(0));
    }
}

