import static org.junit.jupiter.api.Assertions.*;
import java.util.*;

class TestScenarioAnalyzer {

    @org.junit.jupiter.api.Test
    void testWarningForSyncRequestWithoutResponse() {
        ScenarioAnalyzer analyzer = new ScenarioAnalyzer();

        // Create a sync request without corresponding response
        ScenarioAnalyzer.TreeNode root = new ScenarioAnalyzer.TreeNode("root", false, "ServerA");
        ScenarioAnalyzer.TreeNode syncRequest = new ScenarioAnalyzer.TreeNode("request1", true, "ServerB");
        ScenarioAnalyzer.TreeNode nonMatchingChild = new ScenarioAnalyzer.TreeNode("response1", false, "ServerC");

        root.addChild(syncRequest);
        syncRequest.addChild(nonMatchingChild);

        Map<String, Object> result = analyzer.analyzeScenario(root);

        @SuppressWarnings("unchecked")
        List<String> warnings = (List<String>) result.get("warnings");

        assertNotNull(warnings);
        assertEquals(1, warnings.size());
        assertEquals("Warning: There is no corresponding response to server \"ServerA\" from server \"ServerB\"", warnings.get(0));
    }

    @org.junit.jupiter.api.Test
    void testNoWarningForSyncRequestWithResponse() {
        ScenarioAnalyzer analyzer = new ScenarioAnalyzer();

        // Create a sync request with corresponding response
        ScenarioAnalyzer.TreeNode root = new ScenarioAnalyzer.TreeNode("root", false, "ServerA");
        ScenarioAnalyzer.TreeNode syncRequest = new ScenarioAnalyzer.TreeNode("request1", true, "ServerB");
        ScenarioAnalyzer.TreeNode matchingResponse = new ScenarioAnalyzer.TreeNode("response1", false, "ServerA");

        root.addChild(syncRequest);
        syncRequest.addChild(matchingResponse);

        Map<String, Object> result = analyzer.analyzeScenario(root);

        @SuppressWarnings("unchecked")
        List<String> warnings = (List<String>) result.get("warnings");

        assertNotNull(warnings);
        assertEquals(0, warnings.size());
    }

    @org.junit.jupiter.api.Test
    void testMultipleWarningsForMultipleSyncRequestsWithoutResponse() {
        ScenarioAnalyzer analyzer = new ScenarioAnalyzer();

        ScenarioAnalyzer.TreeNode root = new ScenarioAnalyzer.TreeNode("root", false, "ServerA");
        ScenarioAnalyzer.TreeNode syncRequest1 = new ScenarioAnalyzer.TreeNode("request1", true, "ServerB");
        ScenarioAnalyzer.TreeNode syncRequest2 = new ScenarioAnalyzer.TreeNode("request2", true, "ServerC");

        root.addChild(syncRequest1);
        root.addChild(syncRequest2);

        Map<String, Object> result = analyzer.analyzeScenario(root);

        @SuppressWarnings("unchecked")
        List<String> warnings = (List<String>) result.get("warnings");

        assertNotNull(warnings);
        assertEquals(2, warnings.size());
        assertTrue(warnings.contains("Warning: There is no corresponding response to server \"ServerA\" from server \"ServerB\""));
        assertTrue(warnings.contains("Warning: There is no corresponding response to server \"ServerA\" from server \"ServerC\""));
    }

    @org.junit.jupiter.api.Test
    void testEmptyWarningsListForNullRoot() {
        ScenarioAnalyzer analyzer = new ScenarioAnalyzer();

        Map<String, Object> result = analyzer.analyzeScenario(null);

        @SuppressWarnings("unchecked")
        List<String> warnings = (List<String>) result.get("warnings");

        assertNotNull(warnings);
        assertEquals(0, warnings.size());
    }
}

