        graph.addNode("A");
        graph.addNode("B");

        // Use reflection to access private field for testing
        Field adjacencyListField = GraphAnalyzer.class.getDeclaredField("adjacencyList");
        adjacencyListField.setAccessible(true);
        Map<String, List<GraphAnalyzer.Edge>> adjacencyList = 
            (Map<String, List<GraphAnalyzer.Edge>>) adjacencyListField.get(graph);

        assertTrue(adjacencyList.containsKey("A"));
        assertTrue(adjacencyList.containsKey("B"));
        assertEquals(2, adjacencyList.size());
    }

