    public void testAddEdgeInDirectedGraph() throws Exception {
        GraphAnalyzer graph = new GraphAnalyzer(true, true);
        graph.addEdge("A", "B", 5);

        Field adjacencyListField = GraphAnalyzer.class.getDeclaredField("adjacencyList");
        adjacencyListField.setAccessible(true);
        Map<String, List<GraphAnalyzer.Edge>> adjacencyList = 
            (Map<String, List<GraphAnalyzer.Edge>>) adjacencyListField.get(graph);

        assertTrue(adjacencyList.containsKey("A"));
        assertTrue(adjacencyList.containsKey("B"));

        List<GraphAnalyzer.Edge> edgesFromA = adjacencyList.get("A");
        assertEquals(1, edgesFromA.size());
        assertEquals("B", edgesFromA.get(0).destination);
        assertEquals(5, edgesFromA.get(0).weight);

        // In directed graph, B should have no outgoing edges
        List<GraphAnalyzer.Edge> edgesFromB = adjacencyList.get("B");
        assertEquals(0, edgesFromB.size());
    }

