        graph.addNode("A");
        graph.addNode("B");
        graph.addNode("C");
        graph.addEdge("A", "B", 1);
        graph.addEdge("B", "C", 2);

        assertEquals(1, graph.getNodeDegree("A"));
        assertEquals(2, graph.getNodeDegree("B"));
        assertEquals(1, graph.getNodeDegree("C"));

        // Test with directed graph
        GraphAnalyzer directedGraph = new GraphAnalyzer(true, false);
        directedGraph.addNode("X");
        directedGraph.addNode("Y");
        directedGraph.addNode("Z");
        directedGraph.addEdge("X", "Y", 1);
        directedGraph.addEdge("Y", "Z", 2);

        // For directed graph, this should return out-degree
        assertEquals(1, directedGraph.getNodeDegree("X"));
        assertEquals(1, directedGraph.getNodeDegree("Y"));
        assertEquals(0, directedGraph.getNodeDegree("Z"));
    }

    @Test
    public void testGetNodeDegreeThrowsException() {
        GraphAnalyzer graph = new GraphAnalyzer(false, false);
        graph.addNode("A");

        // Should throw exception for non-existent node
        assertThrows(IllegalArgumentException.class, () -> {
            graph.getNodeDegree("NonExistent");
        });

        // Should work for existing node
        assertEquals(0, graph.getNodeDegree("A"));
    }
}

