    @Test
    void testFindShortestPathValid() {
        GraphAnalyzer graph = new GraphAnalyzer(true, true);
        graph.addNode("A");
        graph.addNode("B");
        graph.addNode("C");
        graph.addEdge("A", "B", 1);
        graph.addEdge("B", "C", 2);
        graph.addEdge("A", "C", 5);

        List<String> expected = Arrays.asList("A", "B", "C");
        List<String> actual = graph.findShortestPath("A", "C");
        assertEquals(expected, actual);
    }

    @Test
    void testFindShortestPathNoPath() {
        GraphAnalyzer graph = new GraphAnalyzer(true, true);
        graph.addNode("A");
        graph.addNode("B");
        graph.addNode("C");
        graph.addEdge("A", "B", 1);

        List<String> expected = new ArrayList<>();
        List<String> actual = graph.findShortestPath("A", "C");
        assertEquals(expected, actual);
    }

    @Test
    void testFindShortestPathSameNode() {
        GraphAnalyzer graph = new GraphAnalyzer(true, true);
        graph.addNode("A");

        List<String> expected = Arrays.asList("A");
        List<String> actual = graph.findShortestPath("A", "A");
        assertEquals(expected, actual);
    }

    @Test
    void testFindShortestPathStartNodeNotExists() {
        GraphAnalyzer graph = new GraphAnalyzer(true, true);
        graph.addNode("B");

        assertThrows(IllegalArgumentException.class, () -> {
            graph.findShortestPath("A", "B");
        });
    }

    @Test
    void testFindShortestPathEndNodeNotExists() {
        GraphAnalyzer graph = new GraphAnalyzer(true, true);
        graph.addNode("A");

        assertThrows(IllegalArgumentException.class, () -> {
            graph.findShortestPath("A", "B");
        });
    }

    @Test
    void testFindShortestPathUndirectedGraph() {
        GraphAnalyzer graph = new GraphAnalyzer(false, true);
        graph.addNode("A");
        graph.addNode("B");
        graph.addNode("C");
        graph.addEdge("A", "B", 1);
        graph.addEdge("B", "C", 2);

        List<String> expected = Arrays.asList("A", "B", "C");
        List<String> actual = graph.findShortestPath("A", "C");
        assertEquals(expected, actual);
    }
}

