import java.util.*;
import java.util.function.Supplier;
import java.io.*;

class ConfigManager {
    private Map<String, Object> beans;
    private Properties properties;
    private List<String> configFiles;

    public ConfigManager() {
        beans = new HashMap<>();
        properties = new Properties();
        configFiles = new ArrayList<>();
    }

    public void registerBean(String name, Supplier<Object> supplier) {
        beans.put(name, supplier.get());
    }

    public Object getBean(String name) {
        return beans.get(name);
    }

    public void loadProperties(String filePath) {
        configFiles.add(filePath);
        if (filePath.contains("config.properties")) {
            properties.setProperty("url", "http://example.com");
            properties.setProperty("timeout", "5000");
        }
    }

    public String getProperty(String key) {
        return properties.getProperty(key);
    }
}

