import static org.junit.jupiter.api.Assertions.*;
import java.util.List;
import java.util.ArrayList;
import java.lang.reflect.Field;
class TestConfigManager {
    @org.junit.jupiter.api.Test
    void testGetConfigFilesReturnsUnmodifiableView() {
        ConfigManager cm = new ConfigManager();

        // Add some config files
        cm.loadProperties("app.config.properties");
        cm.importXmlConfig("beans.xml");

        // Get the config files list
        List<String> configFiles = cm.getConfigFiles();

        // Verify it contains the expected files
        assertEquals(2, configFiles.size());
        assertTrue(configFiles.contains("app.config.properties"));
        assertTrue(configFiles.contains("beans.xml"));

        // Try to modify the returned list - should throw UnsupportedOperationException
        assertThrows(UnsupportedOperationException.class, () -> {
            configFiles.add("another.xml");
        });

        // Try other modification operations
        assertThrows(UnsupportedOperationException.class, () -> {
            configFiles.remove(0);
        });

        assertThrows(UnsupportedOperationException.class, () -> {
            configFiles.clear();
        });
    }
}

