import org.json.JSONObject;

class AdvancedNotificationHandler {

    public static JSONObject generateSecureNotification(String title, String body, String encryptedData, boolean useBiometric, String signature, String registrationKey, String priority, long ttl, String collapseKey) {
        JSONObject payload = new JSONObject();

        // Set 'to' field with registrationKey
        payload.put("to", registrationKey);

        // Create 'data' object with title and body
        JSONObject data = new JSONObject();
        data.put("title", title);
        data.put("body", body);
        payload.put("data", data);

        // Create 'notification' object with title and body
        JSONObject notification = new JSONObject();
        notification.put("title", title);
        notification.put("body", body);
        payload.put("notification", notification);

        // Create 'android' object with config containing ttl and priority
        JSONObject android = new JSONObject();
        JSONObject config = new JSONObject();
        config.put("ttl", ttl + "s");
        config.put("priority", priority);
        android.put("config", config);
        payload.put("android", android);

        return payload;
    }
}

