class RedditFeedItem {
    private String title;
    private String url;
    private String subreddit;
    private String domain;
    private String id;
    private String author;
    private int score;
    private String thumbnail;
    private String permalink;
    private long created;
    private int numComments;

    public RedditFeedItem(String title, String url, String subreddit, String domain, String id, String author, int score, String thumbnail, String permalink, long created, int numComments) {
        this.title = title;
        this.url = url;
        this.subreddit = subreddit;
        this.domain = domain;
        this.id = id;
        this.author = author;
        this.score = score;
        this.thumbnail = thumbnail;
        this.permalink = permalink;
        this.created = created;
        this.numComments = numComments;
    }

    public String getTitle() {
        return title;
    }

    public String getUrl() {
        return url;
    }

    public String getSubreddit() {
        return subreddit;
    }

    public String getDomain() {
        return domain;
    }

    public String getId() {
        return id;
    }

    public String getAuthor() {
        return author;
    }

    public int getScore() {
        return score;
    }

    public String getThumbnail() {
        return thumbnail;
    }

    public String getPermalink() {
        return permalink;
    }

    public long getCreated() {
        return created;
    }

    public int getNumComments() {
        return numComments;
    }
}

class RedditFeedAnalyzer {
    public String analyzeAndFormatFeed(List<RedditFeedItem> feedItems, int minScore) {
        if (feedItems == null || feedItems.isEmpty()) {
            return "No feed items to analyze";
        }

        List<RedditFeedItem> filteredItems = new ArrayList<>();
        long totalScore = 0;
        long totalComments = 0;

        for (RedditFeedItem item : feedItems) {
            if (item.getScore() >= minScore) {
                filteredItems.add(item);
                totalScore += item.getScore();
                totalComments += item.getNumComments();
            }
        }

        int count = filteredItems.size();
        double averageScore = count > 0 ? (double) totalScore / count : 0.0;
        double averageComments = count > 0 ? (double) totalComments / count : 0.0;

        String summary = "Feed Analysis Summary: Total items: " + count;
        summary += "\nAverage score: " + String.format("%.2f", averageScore);
        summary += "\nAverage comments: " + String.format("%.2f", averageComments);

        // Sort filtered items by score in descending order
        filteredItems.sort((a, b) -> Integer.compare(b.getScore(), a.getScore()));

        // Add top 3 items section
        summary += "\nTop 3 items by score:";
        int itemsToShow = Math.min(3, filteredItems.size());
        for (int i = 0; i < itemsToShow; i++) {
            RedditFeedItem item = filteredItems.get(i);
            summary += "\n" + (i + 1) + ". " + item.getTitle() + " (Score: " + item.getScore() + ", Comments: " + item.getNumComments() + ")";
        }

        return summary;
    }
}

