import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;
import java.util.*;

class TestRedditFeedAnalyzer {

    @Test
    public void testAnalyzeAndFormatFeedWithTopItems() {
        List<RedditFeedItem> items = Arrays.asList(
            new RedditFeedItem("Item A", "url1", "sub1", "domain1", "id1", "author1", 100, "thumb1", "link1", 1000, 10),
            new RedditFeedItem("Item B", "url2", "sub2", "domain2", "id2", "author2", 200, "thumb2", "link2", 2000, 20),
            new RedditFeedItem("Item C", "url3", "sub3", "domain3", "id3", "author3", 150, "thumb3", "link3", 3000, 15),
            new RedditFeedItem("Item D", "url4", "sub4", "domain4", "id4", "author4", 50, "thumb4", "link4", 4000, 5)
        );

        RedditFeedAnalyzer analyzer = new RedditFeedAnalyzer();
        String result = analyzer.analyzeAndFormatFeed(items, 100);

        // Check that the summary includes the top 3 items section
        assertTrue(result.contains("Top 3 items by score:"));

        // Check that items are properly sorted and formatted
        assertTrue(result.contains("1. Item B (Score: 200, Comments: 20)"));
        assertTrue(result.contains("2. Item C (Score: 150, Comments: 15)"));
        assertTrue(result.contains("3. Item A (Score: 100, Comments: 10)"));

        // Item D should not appear as its score is below minScore
        assertFalse(result.contains("Item D"));
    }

    @Test
    public void testAnalyzeAndFormatFeedWithFewerThanThreeItems() {
        List<RedditFeedItem> items = Arrays.asList(
            new RedditFeedItem("Item A", "url1", "sub1", "domain1", "id1", "author1", 100, "thumb1", "link1", 1000, 10),
            new RedditFeedItem("Item B", "url2", "sub2", "domain2", "id2", "author2", 50, "thumb2", "link2", 2000, 20)
        );

        RedditFeedAnalyzer analyzer = new RedditFeedAnalyzer();
        String result = analyzer.analyzeAndFormatFeed(items, 60);

        // Only Item A should be included
        assertTrue(result.contains("Top 3 items by score:"));
        assertTrue(result.contains("1. Item A (Score: 100, Comments: 10)"));

        // Item B should not appear as its score is below minScore
        assertFalse(result.contains("Item B"));

        // Should not contain entries for non-existent items
        assertFalse(result.contains("2. "));
        assertFalse(result.contains("3. "));
    }

    @Test
    public void testAnalyzeAndFormatFeedWithNoItemsMeetingCriteria() {
        List<RedditFeedItem> items = Arrays.asList(
            new RedditFeedItem("Item A", "url1", "sub1", "domain1", "id1", "author1", 100, "thumb1", "link1", 1000, 10),
            new RedditFeedItem("Item B", "url2", "sub2", "domain2", "id2", "author2", 200, "thumb2", "link2", 2000, 20)
        );

        RedditFeedAnalyzer analyzer = new RedditFeedAnalyzer();
        String result = analyzer.analyzeAndFormatFeed(items, 300);

        // No items should meet the criteria
        assertTrue(result.contains("Top 3 items by score:"));

        // Should not contain any item listings
        assertFalse(result.contains("1. "));
        assertFalse(result.contains("2. "));
        assertFalse(result.contains("3. "));
    }
}

