        assertTrue(solver.getReverseGraph().containsKey(2));
        assertTrue(solver.getReverseGraph().get(2).contains(-1));
        assertTrue(solver.getReverseGraph().containsKey(1));
        assertTrue(solver.getReverseGraph().get(1).contains(-2));
    }

    @Test
