        TwoSatSolver solver = new TwoSatSolver();
        solver.addClause(1, 2);
        solver.addClause(-1, 3);

        boolean result = solver.isSatisfiable();

        // Verify finishing times are computed for all nodes
        assertTrue(solver.getFinishingTimes().size() > 0);

        // Verify all nodes in reverse graph have finishing times
        Set<Integer> allNodes = new HashSet<>();
        allNodes.addAll(solver.getReverseGraph().keySet());
        for (List<Integer> edges : solver.getReverseGraph().values()) {
            allNodes.addAll(edges);
        }

