        // Manually trigger the algorithm
        solver.isSatisfiable();

        Map<Integer, Integer> leaders = solver.getLeaders();

        // Verify leaders are assigned
        assertNotNull(leaders);
        assertFalse(leaders.isEmpty());

        // Get all nodes
        Set<Integer> allNodes = new HashSet<>();
        allNodes.addAll(solver.getReverseGraph().keySet());
        for (List<Integer> edges : solver.getReverseGraph().values()) {
            allNodes.addAll(edges);
        }

        // All nodes should have a leader
        assertEquals(allNodes.size(), leaders.size());

        // Nodes from different clauses should potentially have different leaders
        // (depending on the graph structure and finishing times)
        Set<Integer> distinctLeaders = new HashSet<>(leaders.values());
        assertTrue(distinctLeaders.size() >= 1);
    }

    @Test
    void testSecondPassOrdering() {
        TwoSatSolver solver = new TwoSatSolver();
        solver.addClause(1, 2);

        // Manually trigger the algorithm
        solver.isSatisfiable();

        Map<Integer, Integer> finishingTimes = solver.getFinishingTimes();
        Map<Integer, Integer> leaders = solver.getLeaders();

        // Verify that the second pass processed nodes in decreasing order of finishing times
        // This is an indirect test - we can verify that leaders are properly assigned
        // and the algorithm completed without errors
        assertNotNull(leaders);
        assertFalse(leaders.isEmpty());

        // The leader assignment should be consistent with SCC structure
        // (we can't test the exact order without knowing internal details)
        Set<Integer> allNodes = new HashSet<>();
        allNodes.addAll(solver.getReverseGraph().keySet());
        for (List<Integer> edges : solver.getReverseGraph().values()) {
            allNodes.addAll(edges);
        }

        // All nodes should be processed and have leaders
        assertEquals(allNodes.size(), leaders.size());
    }
}

