        leaders = new HashMap<>();

        // Sort nodes by finishing time in descending order
        List<Integer> nodesByFinishingTime = new ArrayList<>(allNodes);
        nodesByFinishingTime.sort((a, b) -> Integer.compare(finishingTimes.get(b), finishingTimes.get(a)));

        // Perform DFS on original graph
        for (Integer node : nodesByFinishingTime) {
            if (!visited.contains(node)) {
                currentLeader = node;
                dfsOriginal(node);
            }
        }

        // Check for contradictions: if any variable and its negation are in the same SCC
        for (Integer variable : variables) {
            int posNode = variable;
            int negNode = -variable;

            if (leaders.containsKey(posNode) && leaders.containsKey(negNode) && 
                leaders.get(posNode).equals(leaders.get(negNode))) {
                return false;
            }
        }

        return true;
    }

    private void dfsReverse(int node) {
        visited.add(node);

        if (reverseGraph.containsKey(node)) {
            for (int neighbor : reverseGraph.get(node)) {
                if (!visited.contains(neighbor)) {
                    dfsReverse(neighbor);
                }
            }
        }

        finishingTimes.put(node, time++);
    }

    private void dfsOriginal(int node) {
        visited.add(node);
        leaders.put(node, currentLeader);

        if (graph.containsKey(node)) {
            for (int neighbor : graph.get(node)) {
                if (!visited.contains(neighbor)) {
                    dfsOriginal(neighbor);
                }
            }
        }
    }

    // Getter methods for testing
    public Map<Integer, List<Integer>> getReverseGraph() {
        return reverseGraph;
    }

    public Map<Integer, Integer> getFinishingTimes() {
        return finishingTimes;
    }

    public Map<Integer, Integer> getLeaders() {
        return leaders;
    }
}

