import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;

class TestMessageSystem {

    private static class TestHandler implements MessageHandler {
        private Message lastMessage;
        private boolean shouldProcess = true;

        @Override
        public boolean process(Message message) {
            this.lastMessage = message;
            return shouldProcess;
        }

        public Message getLastMessage() {
            return lastMessage;
        }

        public void setShouldProcess(boolean shouldProcess) {
            this.shouldProcess = shouldProcess;
        }
    }

    @Test
    void testRegisterService() {
        MessageSystemSimulator simulator = new MessageSystemSimulator();
        TestHandler handler = new TestHandler();

        String address = simulator.registerService("testService", handler);

        assertNotNull(address);
        assertNotEquals("", address);
    }

    @Test
    void testSendMessageSuccess() {
        MessageSystemSimulator simulator = new MessageSystemSimulator();
        TestHandler senderHandler = new TestHandler();
        TestHandler receiverHandler = new TestHandler();

        String senderAddress = simulator.registerService("sender", senderHandler);
        String receiverAddress = simulator.registerService("receiver", receiverHandler);

        boolean result = simulator.sendMessage(senderAddress, "receiver", "Hello World");

        assertTrue(result);
        Message receivedMessage = receiverHandler.getLastMessage();
        assertNotNull(receivedMessage);
        assertEquals(senderAddress, receivedMessage.getFrom());
        assertEquals(receiverAddress, receivedMessage.getTo());
        assertEquals("Hello World", receivedMessage.getContent());
    }

    @Test
    void testSendMessageFailureInvalidSender() {
        MessageSystemSimulator simulator = new MessageSystemSimulator();
        TestHandler receiverHandler = new TestHandler();

        simulator.registerService("receiver", receiverHandler);

        boolean result = simulator.sendMessage("invalidAddress", "receiver", "Hello World");

        assertFalse(result);
    }

    @Test
    void testSendMessageFailureInvalidReceiver() {
        MessageSystemSimulator simulator = new MessageSystemSimulator();
        TestHandler senderHandler = new TestHandler();

        String senderAddress = simulator.registerService("sender", senderHandler);

        boolean result = simulator.sendMessage(senderAddress, "nonexistent", "Hello World");

        assertFalse(result);
    }

    @Test
    void testHandlerReturnsFalse() {
        MessageSystemSimulator simulator = new MessageSystemSimulator();
        TestHandler senderHandler = new TestHandler();
        TestHandler receiverHandler = new TestHandler();
        receiverHandler.setShouldProcess(false);

        String senderAddress = simulator.registerService("sender", senderHandler);
        simulator.registerService("receiver", receiverHandler);

        boolean result = simulator.sendMessage(senderAddress, "receiver", "Hello World");

        assertFalse(result);
    }
}

