import java.util.*;
import java.lang.reflect.Field;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class TestMessageHandler implements MessageHandler {
    private boolean returnValue;
    private Message lastMessage;

    public TestMessageHandler(boolean returnValue) {
        this.returnValue = returnValue;
    }

    @Override
    public boolean process(Message message) {
        this.lastMessage = message;
        return returnValue;
    }

    public Message getLastMessage() {
        return lastMessage;
    }
}

class TestCases {

    @Test
    public void testMessageCountIncrement() throws Exception {
        TestMessageHandler handler = new TestMessageHandler(true);
        ServiceNode node = new ServiceNode("test-address", handler);

        // Check initial count
        assertEquals(0, node.getMessageCount(), "Initial message count should be 0");

        Message message = new Message("from", "test-address", "content");

        // Handle first message
        node.handleMessage(message);
        assertEquals(1, node.getMessageCount(), "Message count should be 1 after first message");

        // Handle second message
        node.handleMessage(message);
        assertEquals(2, node.getMessageCount(), "Message count should be 2 after second message");
    }

    @Test
    public void testHandleMessageReturnsHandlerResult() {
        TestMessageHandler handlerTrue = new TestMessageHandler(true);
        ServiceNode nodeTrue = new ServiceNode("test-address-1", handlerTrue);

        TestMessageHandler handlerFalse = new TestMessageHandler(false);
        ServiceNode nodeFalse = new ServiceNode("test-address-2", handlerFalse);

        Message message = new Message("from", "test-address", "content");

        assertTrue(nodeTrue.handleMessage(message), "handleMessage should return true when handler returns true");
        assertFalse(nodeFalse.handleMessage(message), "handleMessage should return false when handler returns false");
    }

    @Test
    public void testHandleMessageDelegatesToHandler() {
        TestMessageHandler handler = new TestMessageHandler(true);
        ServiceNode node = new ServiceNode("test-address", handler);

        Message message = new Message("from", "test-address", "content");
        node.handleMessage(message);

        assertEquals(message, handler.getLastMessage(), "handleMessage should delegate to handler's process method");
    }
}

