import java.util.*;
import java.util.concurrent.atomic.AtomicReference;
import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;

class TestMessageSystemSimulator {

    @Test
    public void testSendMessageToExistingService() {
        MessageSystemSimulator simulator = new MessageSystemSimulator();
        AtomicReference<Message> receivedMessage = new AtomicReference<>();

        MessageHandler handler = message -> {
            receivedMessage.set(message);
            return true;
        };

        String serviceAddress = simulator.registerService("EmailService", handler);
        boolean result = simulator.sendMessage("sender-123", "EmailService", "Hello World");

        assertTrue(result);
        assertNotNull(receivedMessage.get());
        assertEquals("sender-123", receivedMessage.get().getFrom());
        assertEquals(serviceAddress, receivedMessage.get().getTo());
        assertEquals("Hello World", receivedMessage.get().getContent());
    }

    @Test
    public void testSendMessageToNonExistentService() {
        MessageSystemSimulator simulator = new MessageSystemSimulator();

        // Register a service to ensure the system works
        MessageHandler handler = message -> true;
        simulator.registerService("EmailService", handler);

        // Try to send to a non-existent service
        boolean result = simulator.sendMessage("sender-123", "SMSService", "Hello World");

        assertFalse(result);
    }

    @Test
    public void testSendMessageFromNonExistentAddress() {
        MessageSystemSimulator simulator = new MessageSystemSimulator();

        MessageHandler handler = message -> true;
        String serviceAddress = simulator.registerService("EmailService", handler);

        // Send from a non-existent address - this should still work
        boolean result = simulator.sendMessage("non-existent-sender", "EmailService", "Hello World");

        assertTrue(result); // Should succeed because the recipient exists
    }

    @Test
    public void testMessageDeliveryIncrementsCounter() {
        MessageSystemSimulator simulator = new MessageSystemSimulator();

        final int[] callCount = {0};
        MessageHandler countingHandler = message -> {
            callCount[0]++;
            return true;
        };

        String newServiceAddress = simulator.registerService("CountingService", countingHandler);
        boolean result = simulator.sendMessage("sender-456", "CountingService", "Another Message");

        assertTrue(result);
        assertEquals(1, callCount[0]);
    }
}

