import java.util.*;

class MessageSystemSimulator {
    private final Map<String, ServiceNode> nodes;
    private final Map<String, String> addressMap;

    public MessageSystemSimulator() {
        nodes = new HashMap<>();
        addressMap = new HashMap<>();
    }

    public String registerService(String serviceType, MessageHandler handler) {
        if (serviceType == null || serviceType.isEmpty()) {
            throw new IllegalArgumentException("Service type cannot be null or empty");
        }
        String address = generateAddress(serviceType);
        ServiceNode node = new ServiceNode(address, handler);
        nodes.put(address, node);
        addressMap.put(serviceType, address);
        return address;
    }

    private String generateAddress(String serviceType) {
        String uuidSuffix = UUID.randomUUID().toString().substring(0, 8);
        return serviceType + "-" + uuidSuffix;
    }

    public boolean sendMessage(String fromAddress, String toServiceType, String messageContent) {
        // Find the target address using the service type
        String toAddress = addressMap.get(toServiceType);
        if (toAddress == null) {
            return false;
        }

        // Get the recipient service node
        ServiceNode recipient = nodes.get(toAddress);
        if (recipient == null) {
            return false;
        }

        // Create and deliver the message
        Message message = new Message(fromAddress, toAddress, messageContent);
        return recipient.handleMessage(message);
    }

    public Map<String, String> getSystemStatus() {
        Map<String, String> statusMap = new HashMap<>();
        for (Map.Entry<String, ServiceNode> entry : nodes.entrySet()) {
            String address = entry.getKey();
            ServiceNode node = entry.getValue();
            statusMap.put(address, node.getStatus());
        }
        return statusMap;
    }
}

class ServiceNode {
    private final String address;
    private final MessageHandler handler;
    private int messageCount;

    public ServiceNode(String address, MessageHandler handler) {
        this.address = address;
        this.handler = handler;
        this.messageCount = 0;
    }

    public String getAddress() {
        return address;
    }

    public MessageHandler getHandler() {
        return handler;
    }

    public int getMessageCount() {
        return messageCount;
    }

    public boolean handleMessage(Message message) {
        messageCount++;
        return handler.process(message);
    }

    public String getStatus() {
        return "Active (" + messageCount + " messages processed)";
    }
}

interface MessageHandler {
    boolean process(Message message);
}

class Message {
    private final String from;
    private final String to;
    private final String content;

    public Message(String from, String to, String content) {
        this.from = from;
        this.to = to;
        this.content = content;
    }

    public String getFrom() {
        return from;
    }

    public String getTo() {
        return to;
    }

    public String getContent() {
        return content;
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null || getClass() != obj.getClass()) return false;
        Message message = (Message) obj;
        return Objects.equals(from, message.from) &&
               Objects.equals(to, message.to) &&
               Objects.equals(content, message.content);
    }

    @Override
    public int hashCode() {
        return Objects.hash(from, to, content);
    }
}

