import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;

class TestMessageHandler implements MessageHandler {
    private final AtomicInteger processedCount = new AtomicInteger(0);
    private final boolean returnValue;

    public TestMessageHandler(boolean returnValue) {
        this.returnValue = returnValue;
    }

    @Override
    public boolean process(Message message) {
        processedCount.incrementAndGet();
        return returnValue;
    }

    public int getProcessedCount() {
        return processedCount.get();
    }
}

class TestCases {

    @Test
    public void testGetSystemStatus() {
        MessageSystemSimulator simulator = new MessageSystemSimulator();

        // Register services
        TestMessageHandler handler1 = new TestMessageHandler(true);
        TestMessageHandler handler2 = new TestMessageHandler(true);

        String address1 = simulator.registerService("EmailService", handler1);
        String address2 = simulator.registerService("SMSService", handler2);

        // Send some messages to increment message counts
        simulator.sendMessage("test-source-1", "EmailService", "Hello Email");
        simulator.sendMessage("test-source-2", "EmailService", "Another Email");
        simulator.sendMessage("test-source-3", "SMSService", "Hello SMS");

        // Get system status
        Map<String, String> status = simulator.getSystemStatus();

        // Verify the map contains correct entries
        assertEquals(2, status.size(), "Status map should contain 2 entries");
        assertTrue(status.containsKey(address1), "Status map should contain EmailService address");
        assertTrue(status.containsKey(address2), "Status map should contain SMSService address");

        // Verify status strings
        assertEquals("Active (2 messages processed)", status.get(address1), "EmailService should have processed 2 messages");
        assertEquals("Active (1 messages processed)", status.get(address2), "SMSService should have processed 1 message");
    }

    @Test
    public void testGetSystemStatusEmpty() {
        MessageSystemSimulator simulator = new MessageSystemSimulator();
        Map<String, String> status = simulator.getSystemStatus();
        assertTrue(status.isEmpty(), "Status map should be empty for new simulator");
    }

