import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.math.RoundingMode;

class TestCurrencyConverter {

    @Test
    public void testConvertCurrencySameCurrency() {
        BigDecimal amount = new BigDecimal("100.00");
        BigDecimal result = CurrencyConverter.convertCurrency(amount, "USD", "USD");
        assertEquals(amount, result);
    }

    @Test
    public void testConvertCurrencyFromUSD() {
        BigDecimal amount = new BigDecimal("100.00");
        BigDecimal result = CurrencyConverter.convertCurrency(amount, "USD", "CNY");
        // 100 USD * 6.5 = 650 CNY
        assertEquals(0, new BigDecimal("650.00").compareTo(result));
    }

    @Test
    public void testConvertCurrencyToUSD() {
        BigDecimal amount = new BigDecimal("650.00");
        BigDecimal result = CurrencyConverter.convertCurrency(amount, "CNY", "USD");
        // 650 CNY / 6.5 = 100 USD (with scale 10 for intermediate division)
        assertEquals(0, new BigDecimal("100.0000000000").compareTo(result));
    }

    @Test
    public void testConvertCurrencyBetweenNonUSDCurrencies() {
        BigDecimal amount = new BigDecimal("100.00");
        BigDecimal result = CurrencyConverter.convertCurrency(amount, "CNY", "EUR");
        // 100 CNY / 6.5 = 15.3846153846 USD (scale 10)
        // 15.3846153846 USD * 0.85 = 13.076923076910 EUR
        BigDecimal expected = new BigDecimal("100.00")
            .divide(new BigDecimal("6.5"), 10, RoundingMode.HALF_UP)
            .multiply(new BigDecimal("0.85"));
        assertEquals(0, expected.compareTo(result));
    }

    @Test
    public void testConvertCurrencyPrecisionWithScale10() {
        BigDecimal amount = new BigDecimal("1.00");
        BigDecimal result = CurrencyConverter.convertCurrency(amount, "CNY", "USD");
        // 1 CNY / 6.5 should use scale 10 for division
        BigDecimal expected = new BigDecimal("1.00")
            .divide(new BigDecimal("6.5"), 10, RoundingMode.HALF_UP);
        assertEquals(0, expected.compareTo(result));
    }

    @Test
    public void testConvertCurrencyRoundingModeHalfUp() {
        // Test a case where HALF_UP rounding matters
        BigDecimal amount = new BigDecimal("3.00");
        BigDecimal result = CurrencyConverter.convertCurrency(amount, "CNY", "USD");
        // 3 / 6.5 = 0.4615384615... should round to 0.4615384615 with HALF_UP at scale 10
        BigDecimal expected = new BigDecimal("3.00")
            .divide(new BigDecimal("6.5"), 10, RoundingMode.HALF_UP);
        assertEquals(0, expected.compareTo(result));
    }
}

