import java.util.*;

class UnitTestRunner {
    private List<UnitTest> tests;

    public UnitTestRunner() {
        tests = new ArrayList<>();
    }

    public void addTest(UnitTest test) {
        tests.add(test);
    }

    public int runTests() {
        for (UnitTest test : tests) {
            try {
                test.runTest();
            } catch (Exception e) {
                // Exception is caught but not handled further as per requirements
            }
        }
        return tests.size();
    }
}

interface UnitTest {
    void runTest() throws Exception;
    String getTestName();
}

