import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;
import java.util.concurrent.atomic.AtomicInteger;

class TestUnitTestRunner {
    @Test
    void testRunTestsReturnsCorrectCount() throws Exception {
        UnitTestRunner runner = new UnitTestRunner();
        AtomicInteger callCount = new AtomicInteger(0);

        UnitTest test1 = new UnitTest() {
            @Override
            public void runTest() throws Exception {
                callCount.incrementAndGet();
            }

            @Override
            public String getTestName() {
                return "Test1";
            }
        };

        UnitTest test2 = new UnitTest() {
            @Override
            public void runTest() throws Exception {
                callCount.incrementAndGet();
            }

            @Override
            public String getTestName() {
                return "Test2";
            }
        };

        runner.addTest(test1);
        runner.addTest(test2);

        int result = runner.runTests();

        assertEquals(2, result);
        assertEquals(2, callCount.get());
    }

    @Test
    void testRunTestsWithNoTests() throws Exception {
        UnitTestRunner runner = new UnitTestRunner();
        int result = runner.runTests();
        assertEquals(0, result);
    }

    @Test
    void testRunTestsWithExceptionInTest() throws Exception {
        UnitTestRunner runner = new UnitTestRunner();
        AtomicInteger callCount = new AtomicInteger(0);

        UnitTest test = new UnitTest() {
            @Override
            public void runTest() throws Exception {
                callCount.incrementAndGet();
                throw new Exception("Test exception");
            }

            @Override
            public String getTestName() {
                return "FailingTest";
            }
        };

        runner.addTest(test);

        // Should not throw exception and should return count of 1
        int result = runner.runTests();

        assertEquals(1, result);
        assertEquals(1, callCount.get());
    }
}

