import java.util.*;

class UnitTestRunner {
    private List<UnitTest> tests;

    public UnitTestRunner() {
        tests = new ArrayList<>();
    }

    public void addTest(UnitTest test) {
        tests.add(test);
    }

    public TestResult runAllTests() {
        int passed = 0;
        int failed = 0;

        for (UnitTest test : tests) {
            try {
                test.runTest();
                passed++;
            } catch (Exception e) {
                failed++;
            }
        }

        return new TestResult(passed, failed);
    }

    public static class TestResult {
        public final int passed;
        public final int failed;

        public TestResult(int passed, int failed) {
            this.passed = passed;
            this.failed = failed;
        }
    }
}

interface UnitTest {
    void runTest() throws Exception;
    String getTestName();
}

