import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;

class TestCases {

    @Test
    public void testStateCreation() {
        State s1 = new State("q0", false);
        State s2 = new State("q1", true);

        assertEquals("q0", s1.getName());
        assertFalse(s1.isFinal());
        assertEquals("q1", s2.getName());
        assertTrue(s2.isFinal());
    }

    @Test
    public void testStateTransitions() {
        State s1 = new State("q0", false);
        State s2 = new State("q1", true);

        s1.addTransition('a', s2);
        assertEquals(s2, s1.getNextState('a'));
        assertNull(s1.getNextState('b'));
    }

    @Test
    public void testDFAStateAddition() {
        DFA dfa = new DFA();
        State s1 = new State("q0", true);  // Changed to final state
        State s2 = new State("q1", false);

        dfa.addState(s1);
        dfa.addState(s2);

        // First added state should be initial state and accepts empty string if final
        assertTrue(dfa.accepts(""));
    }

    @Test
    public void testDFAAcceptsSimpleString() {
        DFA dfa = new DFA();
        State s1 = new State("q0", false);
        State s2 = new State("q1", true);

        s1.addTransition('a', s2);

        dfa.addState(s1);
        dfa.addState(s2);

        assertTrue(dfa.accepts("a"));
        assertFalse(dfa.accepts("b"));
        assertFalse(dfa.accepts("aa"));
    }

    @Test
    public void testDFARejectsOnMissingTransition() {
        DFA dfa = new DFA();
        State s1 = new State("q0", false);
        State s2 = new State("q1", true);

        s1.addTransition('a', s2);

        dfa.addState(s1);
        dfa.addState(s2);

        assertFalse(dfa.accepts("ab"));
    }

    @Test
    public void testEmptyDFARejectsAll() {
        DFA dfa = new DFA();
        assertFalse(dfa.accepts(""));
        assertFalse(dfa.accepts("a"));
    }
}

