class TestDFA {

    @Test
    public void testAlphabetBuildsAutomatically() {
        DFA dfa = new DFA();
        State q0 = new State("q0", false);
        State q1 = new State("q1", true);

        dfa.addState(q0);
        dfa.addState(q1);

        // Initially alphabet should be empty
        assertTrue(dfa.getAlphabet().isEmpty());

        // Add transitions and verify alphabet is built
        dfa.addTransition(q0, 'a', q1);
        assertEquals(Set.of('a'), dfa.getAlphabet());

        dfa.addTransition(q1, 'b', q0);
        assertEquals(Set.of('a', 'b'), dfa.getAlphabet());
    }

    @Test
    public void testAlphabetWithMultipleSymbols() {
        DFA dfa = new DFA();
        State q0 = new State("q0", false);
        State q1 = new State("q1", false);
        State q2 = new State("q2", true);

        dfa.addState(q0);
        dfa.addState(q1);
