        dfa.addTransition(q0, '0', q1);
        dfa.addTransition(q0, '1', q2);
        dfa.addTransition(q1, '0', q0);
        dfa.addTransition(q1, '1', q2);

        Set<Character> expectedAlphabet = Set.of('0', '1');
        assertEquals(expectedAlphabet, dfa.getAlphabet());
    }

