    public void testAlphabetImmutable() {
        DFA dfa = new DFA();
        State q0 = new State("q0", true);
        dfa.addState(q0);
        dfa.addTransition(q0, 'x', q0);

        Set<Character> alphabet = dfa.getAlphabet();
        alphabet.add('y'); // This should not affect the DFA's internal alphabet

        assertEquals(Set.of('x'), dfa.getAlphabet());
    }
}

