        assertEquals(1, capturedMessages2.size(), "Second listener should be notified");
        assertEquals("Error message", capturedMessages1.get(0), "First listener should receive correct message");
        assertEquals("Error message", capturedMessages2.get(0), "Second listener should receive correct message");
