        assertNotNull(user);
        assertEquals(1, user.getId());
        assertEquals("test@example.com", user.getEmail());
        assertEquals("Test User", user.getName());
        assertTrue(user.isActive());

        // Check that the user is stored
        assertSame(user, manager.findUserByEmail("test@example.com"));

        // Add another user to check ID increment
        UserManager.User user2 = manager.addUser("test2@example.com", "Test User 2");
        assertEquals(2, user2.getId());
    }

    @Test
    void testFindUserByEmail() {
        UserManager manager = new UserManager();
        UserManager.User user = manager.addUser("test@example.com", "Test User");

        UserManager.User foundUser = manager.findUserByEmail("test@example.com");
        assertSame(user, foundUser);

        assertNull(manager.findUserByEmail("nonexistent@example.com"));
    }

    @Test
    void testGetActiveUsers() {
        UserManager manager = new UserManager();
        UserManager.User user1 = manager.addUser("user1@example.com", "User 1");
        UserManager.User user2 = manager.addUser("user2@example.com", "User 2");

        List<UserManager.User> activeUsers = manager.getActiveUsers();
        assertEquals(2, activeUsers.size());
        assertTrue(activeUsers.contains(user1));
        assertTrue(activeUsers.contains(user2));

        // Make one user inactive
        user1.setActive(false);
        List<UserManager.User> activeUsersAfter = manager.getActiveUsers();
        assertEquals(1, activeUsersAfter.size());
        assertFalse(activeUsersAfter.contains(user1));
        assertTrue(activeUsersAfter.contains(user2));
