        private final String format;
        private final TransformerType type;

        public TransformerDescriptor(String format, TransformerType type) {
            this.format = format;
            this.type = type;
        }

        public String getFormat() {
            return format;
        }

        public TransformerType getType() {
            return type;
        }
    }

    static class TransformerMetadata {
        private final String name;
        private final String version;
        private final String description;

        public TransformerMetadata(String name, String version, String description) {
            this.name = name;
            this.version = version;
            this.description = description;
        }

        public String getName() {
            return name;
        }

        public String getVersion() {
            return version;
        }

        public String getDescription() {
            return description;
        }
    }

    public EnhancedOTGTransformerFactory() {
        initializeDefaultTransformers();
    }

    private void initializeDefaultTransformers() {
        registerTransformer("contactreportToXml",
                new TransformerDescriptor("contactreport", TransformerType.TXT2XML),
                new TransformerMetadata("ContactReportToXml", "1.0", "Transforms contact reports from TXT to XML format"));

        registerTransformer("opnoteToXml",
                new TransformerDescriptor("opnote", TransformerType.TXT2XML),
                new TransformerMetadata("OpNoteToXml", "1.0", "Transforms operational notes from TXT to XML format"));

        registerTransformer("fourwhiskyToXml",
                new TransformerDescriptor("fourwhisky", TransformerType.TXT2XML),
                new TransformerMetadata("FourWhiskyToXml", "1.0", "Transforms fourwhisky data from TXT to XML format"));

        registerTransformer("contactreportToTxt",
                new TransformerDescriptor("contactreport", TransformerType.XML2TXT),
                new TransformerMetadata("ContactReportToTxt", "1.0", "Transforms contact reports from XML to TXT format"));

        registerTransformer("opnoteToTxt",
                new TransformerDescriptor("opnote", TransformerType.XML2TXT),
                new TransformerMetadata("OpNoteToTxt", "1.0", "Transforms operational notes from XML to TXT format"));

        registerTransformer("fourwhiskyToTxt",
                new TransformerDescriptor("fourwhisky", TransformerType.XML2TXT),
                new TransformerMetadata("FourWhiskyToTxt", "1.0", "Transforms fourwhisky data from XML to TXT format"));
