        version.setIdVersaoOrcamento(new VersaoOrcamentoId());
        version.setDescricaoMensagem("Test message");
        version.setIdtStatus("A");
        version.setDataVigencia(new Timestamp(System.currentTimeMillis()));

        List<String> errors = manager.validateBudgetVersion(version);
        assertFalse(errors.contains("Effective date is required"));
    }

