    void testFilterVersionsWithNullList() {
        List<VersaoOrcamento> result = manager.filterVersions(null, null, null, null);
        assertNotNull(result);
        assertTrue(result.isEmpty());
    }

    @org.junit.jupiter.api.Test
    void testFilterVersionsByStatus() {
        VersaoOrcamento versionA = new VersaoOrcamento();
        versionA.setIdtStatus("A");
        versionA.setDataVigencia(new Timestamp(System.currentTimeMillis()));

        VersaoOrcamento versionR = new VersaoOrcamento();
        versionR.setIdtStatus("R");
        versionR.setDataVigencia(new Timestamp(System.currentTimeMillis()));

