        assertEquals("A", result.get(0).getIdtStatus());
    }

    @org.junit.jupiter.api.Test
    void testFilterVersionsByDateRange() {
        long now = System.currentTimeMillis();
        Timestamp date1 = new Timestamp(now - 86400000); // 1 day ago
        Timestamp date2 = new Timestamp(now); // today
        Timestamp date3 = new Timestamp(now + 86400000); // 1 day in future

        VersaoOrcamento version1 = new VersaoOrcamento();
        version1.setIdtStatus("A");
