        version3.setIdtStatus("A");
        version3.setDataVigencia(date3);

        List<VersaoOrcamento> versions = Arrays.asList(version1, version2, version3);

        // Filter inclusive from date2 to date3
        List<VersaoOrcamento> result = manager.filterVersions(versions, null, date2, date3);
        assertEquals(2, result.size());
        assertTrue(result.contains(version2));
        assertTrue(result.contains(version3));
    }
