import java.util.List;
import java.util.ArrayList;

class PatternGenerator {
    public static List<String> generateSandClock(int size, boolean reverse, boolean useLetters) {
        if (size <= 0) {
            throw new IllegalArgumentException("Size must be positive");
        }

        List<String> result = new ArrayList<>();

        // Generate upper triangular half
        for (int i = 0; i < size; i++) {
            StringBuilder line = new StringBuilder();

            // Add leading spaces (2 spaces per level)
            for (int j = 0; j < i; j++) {
                line.append("  ");
            }

            // Add numbers for this line
            for (int j = 1; j <= size - i; j++) {
                if (j > 1) {
                    line.append("---");
                }
                line.append(j);
            }

            result.add(line.toString());
        }

        // Generate lower triangular half (mirror of upper half, excluding the middle line)
        for (int i = size - 2; i >= 0; i--) {
            StringBuilder line = new StringBuilder();

            // Add leading spaces (2 spaces per level)
            for (int j = 0; j < i; j++) {
                line.append("  ");
            }

            // Add numbers for this line
            for (int j = 1; j <= size - i; j++) {
                if (j > 1) {
                    line.append("---");
                }
                line.append(j);
            }

            result.add(line.toString());
        }

        return result;
    }
}

