class TestThreadExecutor {

    @Test
    public void testTimeoutExceptionWithSpecificMessage() throws Exception {
        Callable<String> longRunningTask = () -> {
            Thread.sleep(2000); // 2 seconds
            return "Should not complete";
        };

        TimeoutException exception = assertThrows(TimeoutException.class, () -> {
            ThreadExecutor.executeTaskWithTimeout(longRunningTask, 500); // 500ms timeout
        });

        assertEquals("The task does not complete within the specified timeout period.", exception.getMessage());
    }

    @Test
    public void testThreadInterruptionOnTimeout() throws Exception {
        final boolean[] wasInterrupted = {false};

        Callable<String> interruptibleTask = () -> {
            try {
                Thread.sleep(2000); // 2 seconds
                return "Should not complete";
            } catch (InterruptedException e) {
                wasInterrupted[0] = true;
                throw e;
            }
        };

        assertThrows(TimeoutException.class, () -> {
            ThreadExecutor.executeTaskWithTimeout(interruptibleTask, 500); // 500ms timeout
        });

        // Give some time for the interrupt to be processed
        Thread.sleep(100);
        assertTrue(wasInterrupted[0], "Worker thread should have been interrupted");
    }

