import java.util.List;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;

class BinaryTree<T extends Comparable<T>> {
    private Node<T> root;

    private static class Node<T> {
        T data;
        Node<T> left, right;

        Node(T data) {
            this.data = data;
        }
    }

    public void insert(T data) {
        root = insertRec(root, data);
    }

    private Node<T> insertRec(Node<T> node, T data) {
        if (node == null) {
            return new Node<>(data);
        }

        if (data.compareTo(node.data) < 0) {
            node.left = insertRec(node.left, data);
        } else if (data.compareTo(node.data) > 0) {
            node.right = insertRec(node.right, data);
        }

        return node;
    }

    public List<T> inOrderTraversal() {
        List<T> result = new ArrayList<>();
        inOrderRec(root, result);
        return result;
    }

    private void inOrderRec(Node<T> node, List<T> result) {
        if (node != null) {
            inOrderRec(node.left, result);
            result.add(node.data);
            inOrderRec(node.right, result);
        }
    }
}

class AdvancedTreeLoader {
    public static <T extends Comparable<T>> void load(BinaryTree<T> tree, List<T> data, boolean shouldSort, boolean allowDuplicates) {
        if (data == null || data.isEmpty()) {
            return;
        }

        if (!allowDuplicates) {
            Set<T> seen = new HashSet<>();
            for (T item : data) {
                if (!seen.add(item)) {
                    throw new IllegalArgumentException("Duplicate elements found: " + item);
                }
            }
        }

        List<T> workingData = new ArrayList<>(data);

        if (shouldSort) {
            Collections.sort(workingData);
            loadBalanced(tree, workingData, 0, workingData.size() - 1);
        } else {
            for (T item : workingData) {
                tree.insert(item);
            }
        }
    }

    private static <T extends Comparable<T>> void loadBalanced(BinaryTree<T> tree, List<T> sortedData, int start, int end) {
        if (start > end) {
            return;
        }

        int mid = start + (end - start) / 2;
        tree.insert(sortedData.get(mid));

        loadBalanced(tree, sortedData, start, mid - 1);
        loadBalanced(tree, sortedData, mid + 1, end);
    }
}

