import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;
import java.util.*;

class TestAdvancedTreeLoader {

    @Test
    public void testUnsortedInsertionMaintainsBSTProperties() {
        BinaryTree<Integer> tree = new BinaryTree<>();
        List<Integer> data = Arrays.asList(5, 3, 8, 1, 9, 2, 7);

        AdvancedTreeLoader.load(tree, data, false, true);

        List<Integer> inOrder = tree.inOrderTraversal();
        List<Integer> sortedExpected = new ArrayList<>(data);
        Collections.sort(sortedExpected);

        assertEquals(sortedExpected, inOrder, "In-order traversal should be sorted even with unsorted insertion");
    }

    @Test
    public void testUnsortedInsertionPreservesOriginalOrder() {
        BinaryTree<Integer> tree = new BinaryTree<>();
        List<Integer> data = Arrays.asList(10, 5, 15, 3, 7, 12, 18);

        AdvancedTreeLoader.load(tree, data, false, true);

        // Verify that the tree structure reflects insertion order
        // Root should be 10 (first element)
        List<Integer> inOrder = tree.inOrderTraversal();
        assertEquals(Arrays.asList(3, 5, 7, 10, 12, 15, 18), inOrder);
    }

    @Test
    public void testEmptyListResultsInEmptyTree() {
        BinaryTree<Integer> tree = new BinaryTree<>();
        List<Integer> emptyData = new ArrayList<>();

        AdvancedTreeLoader.load(tree, emptyData, false, true);

        assertTrue(tree.isEmpty(), "Tree should be empty after loading empty list");
        assertTrue(tree.inOrderTraversal().isEmpty(), "In-order traversal should be empty");
    }

    @Test
    public void testNullListResultsInEmptyTree() {
        BinaryTree<Integer> tree = new BinaryTree<>();

        AdvancedTreeLoader.load(tree, null, false, true);

        assertTrue(tree.isEmpty(), "Tree should be empty after loading null list");
        assertTrue(tree.inOrderTraversal().isEmpty(), "In-order traversal should be empty");
    }

    @Test
    public void testUnsortedVsSortedInsertion() {
        BinaryTree<Integer> unsortedTree = new BinaryTree<>();
        BinaryTree<Integer> sortedTree = new BinaryTree<>();
        List<Integer> data = Arrays.asList(8, 3, 10, 1, 6, 14, 4, 7, 13);

        AdvancedTreeLoader.load(unsortedTree, data, false, true);
        AdvancedTreeLoader.load(sortedTree, data, true, true);

        // Both should have same in-order traversal (sorted)
        List<Integer> unsortedResult = unsortedTree.inOrderTraversal();
        List<Integer> sortedResult = sortedTree.inOrderTraversal();

        assertEquals(sortedResult, unsortedResult, "Both trees should have same sorted in-order traversal");

        // But the tree structures should be different due to insertion order
        // This is implicitly tested by the fact that we're testing different insertion methods
    }
}

