        long startTime = System.currentTimeMillis();
        boolean result = synchronizer.waitWithDeadline(1);
        long endTime = System.currentTimeMillis();

        assertTrue(result);
        assertTrue(endTime - startTime >= 1000); // Should wait at least 1 second
    }

    @Test
    public void testNotifyAllThreadsDoesNotThrow() {
        ThreadSynchronizer synchronizer = new ThreadSynchronizer();

        assertDoesNotThrow(() -> {
            synchronizer.notifyAllThreads();
        });
    }

    @Test
    public void testMultipleThreadsCanWait() throws InterruptedException {
        ThreadSynchronizer synchronizer = new ThreadSynchronizer();
        CountDownLatch latch = new CountDownLatch(2);

        Thread thread1 = new Thread(() -> {
            synchronizer.waitWithDeadline(1);
            latch.countDown();
        });

        Thread thread2 = new Thread(() -> {
            synchronizer.waitWithDeadline(1);
            latch.countDown();
        });

        thread1.start();
        thread2.start();

        assertTrue(latch.await(3, TimeUnit.SECONDS));
    }

    @Test
    public void testNotifyAllCanBeCalledWithoutWaitingThreads() {
        ThreadSynchronizer synchronizer = new ThreadSynchronizer();

        assertDoesNotThrow(() -> {
            synchronizer.notifyAllThreads();
            synchronizer.notifyAllThreads();
        });
    }
}

