    @Timeout(value = 3, unit = TimeUnit.SECONDS)
    public void testWaitWithDeadlineReturnsTrueWhenNotified() throws InterruptedException {
        ThreadSynchronizer synchronizer = new ThreadSynchronizer();

        Thread waiterThread = new Thread(() -> {
            boolean result = synchronizer.waitWithDeadline(5);
            assertTrue(result, "waitWithDeadline should return true when notified before timeout");
        });

        waiterThread.start();
        Thread.sleep(500); // Let the waiter thread start waiting
        synchronizer.notifyAllThreads(); // Notify before timeout
        waiterThread.join();
    }
}

