import org.junit.jupiter.api.Test;
import java.awt.*;
import java.util.*;
import java.util.List;

class TestEnhancedLayoutManager {

    @Test
    public void testFixedSizeComponentsPlacement() {
        // Create mock components
        Component comp1 = new Component() {};
        Component comp2 = new Component() {};
        Component comp3 = new Component() {};

        List<Component> components = Arrays.asList(comp1, comp2, comp3);

        // Create constraints - mix of fixed and non-fixed
        List<EnhancedLayoutManager.LayoutConstraint> constraints = Arrays.asList(
            new EnhancedLayoutManager.LayoutConstraint(10, 20, 100, 50, 1.0, true),  // fixed
            new EnhancedLayoutManager.LayoutConstraint(0, 0, 200, 100, 2.0, false), // not fixed
            new EnhancedLayoutManager.LayoutConstraint(30, 40, 80, 60, 1.5, true)   // fixed
        );

        EnhancedLayoutManager manager = new EnhancedLayoutManager(components, constraints, false, 1.0);
        Map<Component, Rectangle> result = manager.calculateLayout(500, 400);

        // Only fixed-size components should be in the result
        assertEquals(2, result.size());

        // Check comp1 (fixed)
        assertTrue(result.containsKey(comp1));
        Rectangle rect1 = result.get(comp1);
        assertEquals(10, rect1.x);
        assertEquals(20, rect1.y);
        assertEquals(100, rect1.width);
        assertEquals(50, rect1.height);

        // Check comp3 (fixed)
        assertTrue(result.containsKey(comp3));
        Rectangle rect3 = result.get(comp3);
        assertEquals(30, rect3.x);
        assertEquals(40, rect3.y);
        assertEquals(80, rect3.width);
        assertEquals(60, rect3.height);

        // comp2 should not be in result (not fixed)
        assertFalse(result.containsKey(comp2));
    }

    @Test
    public void testNoFixedSizeComponents() {
        Component comp1 = new Component() {};
        List<Component> components = Arrays.asList(comp1);

        List<EnhancedLayoutManager.LayoutConstraint> constraints = Arrays.asList(
            new EnhancedLayoutManager.LayoutConstraint(0, 0, 100, 100, 1.0, false)
        );

        EnhancedLayoutManager manager = new EnhancedLayoutManager(components, constraints, false, 1.0);
        Map<Component, Rectangle> result = manager.calculateLayout(300, 200);

        // No fixed components, result should be empty
        assertTrue(result.isEmpty());
    }

    @Test
    public void testAllFixedSizeComponents() {
        Component comp1 = new Component() {};
        Component comp2 = new Component() {};
        List<Component> components = Arrays.asList(comp1, comp2);

        List<EnhancedLayoutManager.LayoutConstraint> constraints = Arrays.asList(
