import java.awt.*;
import java.util.List;
import javax.swing.*;

public class LayoutExample {
    public static void main(String[] args) {
        // Create components
        JButton button1 = new JButton("Button 1");
        JButton button2 = new JButton("Button 2");
        JLabel fixedLabel = new JLabel("Fixed Size");

        // Create constraints
        List<EnhancedLayoutManager.LayoutConstraint> constraints = List.of(
            new EnhancedLayoutManager.LayoutConstraint(0, 0, 0, 0, 2.0, false), // Flexible button1
            new EnhancedLayoutManager.LayoutConstraint(0, 0, 0, 0, 1.0, false), // Flexible button2
            new EnhancedLayoutManager.LayoutConstraint(10, 10, 100, 50, 0, true) // Fixed label
        );

        // Create layout manager
