import org.junit.jupiter.api.Test;
import java.awt.*;
import java.util.*;
import java.util.List;

class TestEnhancedLayoutManager {

    @Test
    public void testFlexibleComponentsProportionalDistribution() {
        // Create components
        Component comp1 = new Component() {};
        Component comp2 = new Component() {};
        Component comp3 = new Component() {};
        List<Component> components = Arrays.asList(comp1, comp2, comp3);

        // Create constraints: all flexible with different weights
        List<EnhancedLayoutManager.LayoutConstraint> constraints = Arrays.asList(
            new EnhancedLayoutManager.LayoutConstraint(10, 20, 0, 0, 2.0, false), // weight 2
            new EnhancedLayoutManager.LayoutConstraint(30, 40, 0, 0, 3.0, false), // weight 3
            new EnhancedLayoutManager.LayoutConstraint(50, 60, 0, 0, 1.0, false)  // weight 1
        );

        EnhancedLayoutManager manager = new EnhancedLayoutManager(components, constraints, false, 1.0);
        Map<Component, Rectangle> layout = manager.calculateLayout(600, 400);

        // Total weight = 2 + 3 + 1 = 6
        // Remaining width = 600, remaining height = 400
        // comp1: width = 600 * 2/6 = 200, height = 400 * 2/6 = 133
        // comp2: width = 600 * 3/6 = 300, height = 400 * 3/6 = 200
        // comp3: width = 600 * 1/6 = 100, height = 400 * 1/6 = 66

        Rectangle rect1 = layout.get(comp1);
        assertEquals(10, rect1.x);
        assertEquals(20, rect1.y);
        assertEquals(200, rect1.width);
        assertEquals(133, rect1.height);

        Rectangle rect2 = layout.get(comp2);
        assertEquals(30, rect2.x);
        assertEquals(40, rect2.y);
        assertEquals(300, rect2.width);
        assertEquals(200, rect2.height);

        Rectangle rect3 = layout.get(comp3);
        assertEquals(50, rect3.x);
        assertEquals(60, rect3.y);
        assertEquals(100, rect3.width);
        assertEquals(66, rect3.height);
    }

    @Test
    public void testMixedFixedAndFlexibleComponents() {
        Component comp1 = new Component() {};
        Component comp2 = new Component() {};
        List<Component> components = Arrays.asList(comp1, comp2);

        // One fixed, one flexible
        List<EnhancedLayoutManager.LayoutConstraint> constraints = Arrays.asList(
            new EnhancedLayoutManager.LayoutConstraint(0, 0, 100, 50, 0.0, true),  // fixed
            new EnhancedLayoutManager.LayoutConstraint(10, 10, 0, 0, 1.0, false)   // flexible
        );

        EnhancedLayoutManager manager = new EnhancedLayoutManager(components, constraints, false, 1.0);
        Map<Component, Rectangle> layout = manager.calculateLayout(300, 200);

        // Fixed component takes 100x50, remaining is 200x150
        // Flexible component gets all remaining space
        Rectangle flexRect = layout.get(comp2);
        assertEquals(10, flexRect.x);
        assertEquals(10, flexRect.y);
        assertEquals(200, flexRect.width);
        assertEquals(150, flexRect.height);
    }
}

