    void testGetValidIndices() {
        LinkedList<Integer> list = new LinkedList<>();
        list.add(10);
        list.add(20);
        list.add(30);
        list.add(40);

        assertEquals(10, list.get(0));
        assertEquals(20, list.get(1));
        assertEquals(30, list.get(2));
        assertEquals(40, list.get(3));
    }

    @Test
    void testGetFromHeadHalf() {
        LinkedList<Integer> list = new LinkedList<>();
        for (int i = 0; i < 10; i++) {
            list.add(i * 10);
        }
        // Test accessing first half - should traverse from head
        assertEquals(20, list.get(2));
    }

    @Test
    void testGetFromTailHalf() {
        LinkedList<Integer> list = new LinkedList<>();
        for (int i = 0; i < 10; i++) {
            list.add(i * 10);
        }
        // Test accessing second half - should traverse from tail
        assertEquals(70, list.get(7));
    }

    @Test
    void testGetInvalidIndexNegative() {
        LinkedList<Integer> list = new LinkedList<>();
        list.add(10);
        assertThrows(IndexOutOfBoundsException.class, () -> list.get(-1));
    }

    @Test
    void testGetInvalidIndexTooLarge() {
        LinkedList<Integer> list = new LinkedList<>();
        list.add(10);
        assertThrows(IndexOutOfBoundsException.class, () -> list.get(1));
    }

    @Test
    void testGetInvalidIndexEmptyList() {
        LinkedList<Integer> list = new LinkedList<>();
        assertThrows(IndexOutOfBoundsException.class, () -> list.get(0));
    }
}

