import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;
import java.util.*;

class TestCases extends LinkedList<Integer> {

    @Test
    void testAddAtIndexBeginning() {
        LinkedList<Integer> list = new LinkedList<>();
        list.add(1);
        list.add(2);
        list.add(0, 0); // Add at beginning
        assertEquals(3, list.size());
        assertEquals(0, (int) list.get(0));
        assertEquals(1, (int) list.get(1));
        assertEquals(2, (int) list.get(2));
    }

    @Test
    void testAddAtIndexMiddle() {
        LinkedList<Integer> list = new LinkedList<>();
        list.add(1);
        list.add(3);
        list.add(1, 2); // Add in middle
        assertEquals(3, list.size());
        assertEquals(1, (int) list.get(0));
        assertEquals(2, (int) list.get(1));
        assertEquals(3, (int) list.get(2));
    }

    @Test
    void testAddAtIndexEnd() {
        LinkedList<Integer> list = new LinkedList<>();
        list.add(1);
        list.add(2);
        list.add(2, 3); // Add at end (equivalent to append)
        assertEquals(3, list.size());
        assertEquals(1, (int) list.get(0));
        assertEquals(2, (int) list.get(1));
        assertEquals(3, (int) list.get(2));
    }

    @Test
    void testAddAtIndexEmptyList() {
        LinkedList<Integer> list = new LinkedList<>();
        list.add(0, 1); // Add to empty list
        assertEquals(1, list.size());
        assertEquals(1, (int) list.get(0));
    }

    @Test
    void testAddAtIndexInvalidIndexNegative() {
        LinkedList<Integer> list = new LinkedList<>();
        assertThrows(IndexOutOfBoundsException.class, () -> {
            list.add(-1, 1);
        });
    }

    @Test
    void testAddAtIndexInvalidIndexTooLarge() {
        LinkedList<Integer> list = new LinkedList<>();
        list.add(1);
        assertThrows(IndexOutOfBoundsException.class, () -> {
            list.add(2, 2);
        });
    }

    @Test
    void testAddAtIndexValidBoundary() {
        LinkedList<Integer> list = new LinkedList<>();
        list.add(1);
        list.add(0, 0); // Insert at index 0
        list.add(2, 2); // Insert at index 2 (end)
        assertEquals(3, list.size());
        assertEquals(0, (int) list.get(0));
        assertEquals(1, (int) list.get(1));
        assertEquals(2, (int) list.get(2));
    }
}

