    void testRemoveAtIndex() {
        LinkedList<Integer> list = new LinkedList<>();
        list.add(1);
        list.add(2);
        list.add(3);
        list.add(4);

        // Remove from middle
        assertEquals(2, list.remove(1));
        assertEquals(3, list.size());
        assertEquals("[1, 3, 4]", list.toString());

        // Remove from beginning
        assertEquals(1, list.remove(0));
        assertEquals(2, list.size());
        assertEquals("[3, 4]", list.toString());

        // Remove from end
        assertEquals(4, list.remove(1));
        assertEquals(1, list.size());
        assertEquals("[3]", list.toString());

        // Remove last element
        assertEquals(3, list.remove(0));
        assertEquals(0, list.size());
        assertEquals("[]", list.toString());
    }

    @Test
    void testIsEmpty() {
        LinkedList<Integer> list = new LinkedList<>();
        assertTrue(list.isEmpty());

        list.add(1);
        assertFalse(list.isEmpty());

        list.remove();
        assertTrue(list.isEmpty());
    }

    @Test
    void testClear() {
        LinkedList<Integer> list = new LinkedList<>();
        list.add(1);
        list.add(2);
        list.add(3);

        assertFalse(list.isEmpty());
        assertEquals(3, list.size());

        list.clear();

        assertTrue(list.isEmpty());
        assertEquals(0, list.size());
        assertEquals("[]", list.toString());
    }

    @Test
    void testContains() {
        LinkedList<String> list = new LinkedList<>();
        list.add("apple");
        list.add("banana");
        list.add("cherry");

        assertTrue(list.contains("apple"));
        assertTrue(list.contains("banana"));
        assertTrue(list.contains("cherry"));
        assertFalse(list.contains("grape"));

        // Test with null values
        list.add(null);
        assertTrue(list.contains(null));
    }

    @Test
    void testToString() {
        LinkedList<Integer> list = new LinkedList<>();

        // Empty list
        assertEquals("[]", list.toString());

        // Single element
        list.add(42);
        assertEquals("[42]", list.toString());

        // Multiple elements
        list.add(10);
        list.add(20);
        assertEquals("[42, 10, 20]", list.toString());
    }
}

