        assertEquals("i = 0", code.get(0));
        assertEquals("L1001:", code.get(1));
        assertEquals("if i > 10 goto L1002", code.get(2));
        assertEquals("// Loop body goes here", code.get(3));
        assertEquals("i = i + 1", code.get(4));
        assertEquals("goto L1001", code.get(5));
        assertEquals("L1002:", code.get(6));
    }

    @Test
    public void testLoopCounterIncrement() {
        LoopAnalyzer analyzer = new LoopAnalyzer();

        List<String> firstLoop = analyzer.generateForLoop("i", 0, "i", 5, 1);
        List<String> secondLoop = analyzer.generateForLoop("j", 1, "j", 20, 2);

        // First loop should use labels 1001 and 1002
        assertEquals("L1001:", firstLoop.get(1));
        assertEquals("if i > 5 goto L1002", firstLoop.get(2));
        assertEquals("goto L1001", firstLoop.get(5));
        assertEquals("L1002:", firstLoop.get(6));

