        assertEquals("L2001:", secondLoop.get(1));
        assertEquals("if j > 20 goto L2002", secondLoop.get(2));
        assertEquals("goto L2001", secondLoop.get(5));
        assertEquals("L2002:", secondLoop.get(6));
    }

