import java.util.ArrayList;
import java.util.List;

class LoopAnalyzer {
    private int loopCounter;
    private List<Integer> breakLabels;
    private List<Integer> continueLabels;

    public LoopAnalyzer() {
        this.loopCounter = 0;
        this.breakLabels = new ArrayList<>();
        this.continueLabels = new ArrayList<>();
    }

    public List<String> generateForLoop(String initVar, int initValue, 
                                      String conditionVar, int conditionValue,
                                      int stepValue) {
        List<String> intermediateCode = new ArrayList<>();
        loopCounter++;

        int headLabel = loopCounter * 1000 + 1;
        int tailLabel = loopCounter * 1000 + 2;
        int continueLabel = loopCounter * 1000 + 3;

        // Add labels to tracking lists
        breakLabels.add(tailLabel);
        continueLabels.add(continueLabel);

        intermediateCode.add(initVar + " = " + initValue);
        intermediateCode.add("L" + headLabel + ":");
        intermediateCode.add("if " + conditionVar + " > " + conditionValue + " goto L" + tailLabel);
        intermediateCode.add("// Loop body goes here");
        intermediateCode.add(initVar + " = " + initVar + " + " + stepValue);
        intermediateCode.add("goto L" + headLabel);
        intermediateCode.add("L" + tailLabel + ":");

        return intermediateCode;
    }

    public List<Integer> getBreakLabels() {
        return new ArrayList<>(breakLabels);
    }

    public List<Integer> getContinueLabels() {
        return new ArrayList<>(continueLabels);
    }
}

