import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;
import java.lang.reflect.Method;
import java.lang.reflect.Modifier;

class TestCases {

    @Test
    public void testIsParameterizedRouteMethodExists() throws Exception {
        Method method = UrlRouter.class.getDeclaredMethod("isParameterizedRoute", String.class);
        assertTrue(Modifier.isPrivate(method.getModifiers()), "Method should be private");
        assertEquals(boolean.class, method.getReturnType(), "Method should return boolean");
    }

    @Test
    public void testIsParameterizedRouteWithValidParameter() throws Exception {
        UrlRouter router = new UrlRouter(new HashMap<>(), "default");
        Method method = UrlRouter.class.getDeclaredMethod("isParameterizedRoute", String.class);
        method.setAccessible(true);

        assertTrue((Boolean) method.invoke(router, "/users/{id}"));
        assertTrue((Boolean) method.invoke(router, "/{param}"));
        assertTrue((Boolean) method.invoke(router, "/api/{version}/users/{id}"));
    }

    @Test
    public void testIsParameterizedRouteWithStaticRoute() throws Exception {
        UrlRouter router = new UrlRouter(new HashMap<>(), "default");
        Method method = UrlRouter.class.getDeclaredMethod("isParameterizedRoute", String.class);
        method.setAccessible(true);

        assertFalse((Boolean) method.invoke(router, "/users"));
        assertFalse((Boolean) method.invoke(router, "/api/users"));
        assertFalse((Boolean) method.invoke(router, "users"));
    }

    @Test
    public void testIsParameterizedRouteWithInvalidFormat() throws Exception {
        UrlRouter router = new UrlRouter(new HashMap<>(), "default");
        Method method = UrlRouter.class.getDeclaredMethod("isParameterizedRoute", String.class);
        method.setAccessible(true);

        assertFalse((Boolean) method.invoke(router, "/users/}id{"));
        assertFalse((Boolean) method.invoke(router, "/users/id}"));
        assertFalse((Boolean) method.invoke(router, "/users/{id"));
        assertFalse((Boolean) method.invoke(router, (Object) null));
        assertFalse((Boolean) method.invoke(router, ""));
    }
}

