        producer.sendMessages("Test", 3);

        LinkedBlockingQueue<String> queue = producer.getMessageQueue();

        // Check that all messages are in the queue
        assertEquals(3, queue.size());

        // Extract messages from queue to verify content
        List<String> messagesInQueue = new ArrayList<>();
        while (!queue.isEmpty()) {
            messagesInQueue.add(queue.take());
        }

        assertTrue(messagesInQueue.contains("Test 1"));
        assertTrue(messagesInQueue.contains("Test 2"));
        assertTrue(messagesInQueue.contains("Test 3"));

        // Send messages again to verify they're also tracked
        producer.sendMessages("Another", 2);

        // Check that queue now has 2 more messages
        assertEquals(2, queue.size());

        String msg1 = queue.take();
        String msg2 = queue.take();

        assertEquals("Another 1", msg1);
        assertEquals("Another 2", msg2);
    }

