import java.util.*;

public class ApiDocumentationGenerator {
    private String title;
    private String description;
    private String version;
    private String basePackage;
    private List<Map<String, String>> securitySchemes;
    private List<String> modelSubstitutes;
    private Map<String, String> modelSubstituteMap;
    private boolean useDefaultResponseMessages;

    public ApiDocumentationGenerator(String title, String description, String version) {
        this.title = title;
        this.description = description;
        this.version = version;
        this.securitySchemes = new ArrayList<>();
        this.modelSubstitutes = new ArrayList<>();
        this.modelSubstituteMap = new HashMap<>();
    }

    public ApiDocumentationGenerator withBasePackage(String basePackage) {
        this.basePackage = basePackage;
        return this;
    }

    public ApiDocumentationGenerator addSecurityScheme(String name, String keyName, String location) {
        Map<String, String> scheme = new HashMap<>();
        scheme.put("name", name);
        scheme.put("keyName", keyName);
        scheme.put("location", location);
        this.securitySchemes.add(scheme);
        return this;
    }

    public ApiDocumentationGenerator addModelSubstitute(String originalClass, String substituteClass) {
        this.modelSubstituteMap.put(originalClass, substituteClass);
        return this;
    }

    public ApiDocumentationGenerator withDefaultResponseMessages(boolean useDefaultResponseMessages) {
        this.useDefaultResponseMessages = useDefaultResponseMessages;
        return this;
    }

    public void validateConfiguration() {
        if (title == null || title.isEmpty()) {
            throw new IllegalStateException();
        }
        if (basePackage == null || basePackage.isEmpty()) {
            throw new IllegalStateException();
        }
    }

    public Map<String, Object> generateConfiguration() {
        validateConfiguration();
        Map<String, Object> config = new HashMap<>();
        config.put("title", this.title);
        config.put("description", this.description);
        config.put("version", this.version);
        config.put("basePackage", this.basePackage);
        config.put("securitySchemes", this.securitySchemes);
        config.put("modelSubstitutes", this.modelSubstituteMap);
        config.put("useDefaultResponseMessages", this.useDefaultResponseMessages);
        return config;
    }
}

