import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;
import java.util.*;

class TestSecurePaymentProcessor {

    @Test
    public void testGenerateSecurePaymentUrlWithHmacSha256Hash() {
        SecurePaymentProcessor processor = new SecurePaymentProcessor();
        Map<String, String> params = new HashMap<>();
        params.put("amount", "100");
        params.put("currency", "USD");

        String result = processor.generateSecurePaymentUrl("https://example.com", params, "secret123");

        // Should contain vpc_SecureHash parameter
        assertTrue(result.contains("vpc_SecureHash="));
        // Should contain original parameters
        assertTrue(result.contains("amount=100"));
        assertTrue(result.contains("currency=USD"));
    }

    @Test
    public void testSecretValidation() {
        SecurePaymentProcessor processor = new SecurePaymentProcessor();
        Map<String, String> params = new HashMap<>();
        params.put("amount", "100");

        // Test null secret
        IllegalArgumentException exception1 = assertThrows(IllegalArgumentException.class, () -> {
            processor.generateSecurePaymentUrl("https://example.com", params, null);
        });
        assertEquals("Secret key must not be null or empty", exception1.getMessage());

        // Test empty secret
        IllegalArgumentException exception2 = assertThrows(IllegalArgumentException.class, () -> {
            processor.generateSecurePaymentUrl("https://example.com", params, "");
        });
        assertEquals("Secret key must not be null or empty", exception2.getMessage());
    }

    @Test
    public void testHashCalculationOverSortedQueryString() {
        SecurePaymentProcessor processor = new SecurePaymentProcessor();
        Map<String, String> params1 = new LinkedHashMap<>();
        params1.put("z_param", "value1");
        params1.put("a_param", "value2");

        Map<String, String> params2 = new LinkedHashMap<>();
        params2.put("a_param", "value2");
        params2.put("z_param", "value1");

        String result1 = processor.generateSecurePaymentUrl("https://example.com", params1, "secret");
        String result2 = processor.generateSecurePaymentUrl("https://example.com", params2, "secret");

        // Should produce same hash regardless of input order
        String hash1 = extractHashFromUrl(result1);
        String hash2 = extractHashFromUrl(result2);
        assertEquals(hash1, hash2);
    }

    @Test
    public void testDifferentSecretsProduceDifferentHashes() {
        SecurePaymentProcessor processor = new SecurePaymentProcessor();
        Map<String, String> params = new HashMap<>();
        params.put("amount", "100");

        String result1 = processor.generateSecurePaymentUrl("https://example.com", params, "secret1");
        String result2 = processor.generateSecurePaymentUrl("https://example.com", params, "secret2");

        String hash1 = extractHashFromUrl(result1);
        String hash2 = extractHashFromUrl(result2);
        assertNotEquals(hash1, hash2);
    }

    @Test
    public void testHashIncludedInFinalUrl() {
        SecurePaymentProcessor processor = new SecurePaymentProcessor();
        Map<String, String> params = new HashMap<>();
        params.put("amount", "100");

        String result = processor.generateSecurePaymentUrl("https://example.com", params, "secret");

        // vpc_SecureHash should be included and URL-encoded
        assertTrue(result.contains("vpc_SecureHash="));
        // Should be properly sorted (amount comes before vpc_SecureHash alphabetically)
        int amountIndex = result.indexOf("amount=");
        int hashIndex = result.indexOf("vpc_SecureHash=");
        assertTrue(amountIndex < hashIndex);
    }

    private String extractHashFromUrl(String url) {
        String[] parts = url.split("vpc_SecureHash=");
        if (parts.length > 1) {
            String hashPart = parts[1];
            int ampIndex = hashPart.indexOf("&");
            return ampIndex > 0 ? hashPart.substring(0, ampIndex) : hashPart;
        }
        return "";
    }
}

