    public void testFindChannelWithMaxBandwidthWithSingleChannel() {
        Plan plan = new Plan();
        Channel channel = new Channel(5.0, "SingleChannel");
        plan.addChannel(channel);

        Channel result = plan.findChannelWithMaxBandwidth();
        assertEquals(channel, result);
        assertEquals(5.0, result.getBandwidth());
    }

