        Channel channel1 = new Channel(10.0, "Channel1");
        Channel channel2 = new Channel(10.0, "Channel2");

        plan.addChannel(channel1);
        plan.addChannel(channel2);

        Channel result = plan.findChannelWithMaxBandwidth();
        assertEquals(channel1, result); // Should return the first one encountered
    }
