    public EnhancedSpotLight(PointLight light, Vector3 direction, double cutoff, double exponent) {
        this.light = light;
        this.direction = direction;
        this.cutoff = cutoff;
        this.exponent = exponent;
    }

    public double calculateIntensity(Vector3 point) {
        return 1.0;
    }

    // Getters and setters
