import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;

class TestCases {
    @Test
    public void testEnhancedSpotLightDefaultConstructor() {
        EnhancedSpotLight esl = new EnhancedSpotLight();
        assertNull(esl.getLight());
        assertNull(esl.getDirection());
        assertEquals(0.0, esl.getCutoff());
        assertEquals(0.0, esl.getExponent());
    }

    @Test
    public void testEnhancedSpotLightParameterizedConstructor() {
        PointLight light = new PointLight();
        Vector3 direction = new Vector3(1, 0, 0);
        EnhancedSpotLight esl = new EnhancedSpotLight(light, direction, 30.0, 2.0);
        assertSame(light, esl.getLight());
        assertSame(direction, esl.getDirection());
        assertEquals(30.0, esl.getCutoff());
        assertEquals(2.0, esl.getExponent());
    }

    @Test
    public void testCalculateIntensity() {
        EnhancedSpotLight esl = new EnhancedSpotLight();
        Vector3 point = new Vector3(1, 2, 3);
        assertEquals(1.0, esl.calculateIntensity(point));
    }

    @Test
    public void testPointLightDefaultConstructor() {
        PointLight pl = new PointLight();
        assertNull(pl.getPosition());
        assertEquals(0.0, pl.getIntensity());
    }

    @Test
    public void testPointLightParameterizedConstructor() {
        Vector3 position = new Vector3(1, 2, 3);
        PointLight pl = new PointLight(position, 10.0);
        assertSame(position, pl.getPosition());
        assertEquals(10.0, pl.getIntensity());
    }

    @Test
    public void testVector3DefaultConstructor() {
        Vector3 v = new Vector3();
        assertEquals(0.0, v.getX());
        assertEquals(0.0, v.getY());
        assertEquals(0.0, v.getZ());
    }

    @Test
    public void testVector3ParameterizedConstructor() {
        Vector3 v = new Vector3(1.0, 2.0, 3.0);
        assertEquals(1.0, v.getX());
        assertEquals(2.0, v.getY());
        assertEquals(3.0, v.getZ());
    }

    @Test
    public void testGettersSetters() {
        EnhancedSpotLight esl = new EnhancedSpotLight();
        PointLight light = new PointLight();
        Vector3 direction = new Vector3();

        esl.setLight(light);
        esl.setDirection(direction);
        esl.setCutoff(45.0);
        esl.setExponent(1.5);

        assertSame(light, esl.getLight());
        assertSame(direction, esl.getDirection());
        assertEquals(45.0, esl.getCutoff());
        assertEquals(1.5, esl.getExponent());

        PointLight pl = new PointLight();
        Vector3 pos = new Vector3();

        pl.setPosition(pos);
        pl.setIntensity(5.0);

        assertSame(pos, pl.getPosition());
        assertEquals(5.0, pl.getIntensity());

        Vector3 v = new Vector3();
        v.setX(1.0);
        v.setY(2.0);
        v.setZ(3.0);

        assertEquals(1.0, v.getX());
        assertEquals(2.0, v.getY());
        assertEquals(3.0, v.getZ());
    }
}

