        assertEquals(5.0, v.length(), 0.001);

        Vector3 v2 = new Vector3(1, 1, 1);
        assertEquals(Math.sqrt(3), v2.length(), 0.001);
    }

    @Test
    void testNormalized() {
        Vector3 v = new Vector3(3, 4, 0);
        Vector3 normalized = v.normalized();
        assertEquals(0.6, normalized.getX(), 0.001);
        assertEquals(0.8, normalized.getY(), 0.001);
        assertEquals(0.0, normalized.getZ(), 0.001);

        // Test zero vector
        Vector3 zero = new Vector3(0, 0, 0);
        Vector3 normalizedZero = zero.normalized();
        assertEquals(0.0, normalizedZero.getX(), 0.001);
        assertEquals(0.0, normalizedZero.getY(), 0.001);
        assertEquals(0.0, normalizedZero.getZ(), 0.001);
    }

    @Test
    void testDotProduct() {
        Vector3 v1 = new Vector3(1, 2, 3);
        Vector3 v2 = new Vector3(4, 5, 6);
        assertEquals(32.0, v1.dot(v2), 0.001);

        Vector3 v3 = new Vector3(1, 0, 0);
        Vector3 v4 = new Vector3(0, 1, 0);
        assertEquals(0.0, v3.dot(v4), 0.001);
    }

