import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;
import java.util.*;

class TestCases {

    @Test
    public void testCalculateIntensityWithinInnerCutoff() {
        PointLight pointLight = new PointLight(new Vector3(0, 0, 0), 1.0);
        Vector3 direction = new Vector3(0, 0, -1);
        EnhancedSpotLight spotLight = new EnhancedSpotLight(pointLight, direction, 30, 45, 2.0);

        // Point directly in the spotlight direction
        Vector3 point = new Vector3(0, 0, -1);
        double intensity = spotLight.calculateIntensity(point);
        assertEquals(1.0, intensity, 0.001);
    }

    @Test
    public void testCalculateIntensityOutsideOuterCutoff() {
        PointLight pointLight = new PointLight(new Vector3(0, 0, 0), 1.0);
        Vector3 direction = new Vector3(0, 0, -1);
        EnhancedSpotLight spotLight = new EnhancedSpotLight(pointLight, direction, 30, 45, 2.0);

        // Point outside the outer cutoff
        Vector3 point = new Vector3(1, 0, -1); // ~45 degrees, at the edge
        double intensity = spotLight.calculateIntensity(point);
        assertEquals(0.0, intensity, 0.001);
    }

    @Test
    public void testCalculateIntensityAtLightPosition() {
        PointLight pointLight = new PointLight(new Vector3(0, 0, 0), 1.0);
        Vector3 direction = new Vector3(0, 0, -1);
        EnhancedSpotLight spotLight = new EnhancedSpotLight(pointLight, direction, 30, 45, 2.0);

        // Point at the same position as the light
        Vector3 point = new Vector3(0, 0, 0);
        double intensity = spotLight.calculateIntensity(point);
        assertEquals(1.0, intensity, 0.001);
    }

    @Test
    public void testCalculateIntensityWithFalloff() {
        PointLight pointLight = new PointLight(new Vector3(0, 0, 0), 1.0);
        Vector3 direction = new Vector3(0, 0, -1);
        EnhancedSpotLight spotLight = new EnhancedSpotLight(pointLight, direction, 30, 60, 2.0);

        // Point between inner and outer cutoff with falloff
        Vector3 point = new Vector3(0, 1, -1.732); // ~30 degrees from z-axis
        double intensity = spotLight.calculateIntensity(point);
        // Should be between 0 and 1, with falloff applied
        assertTrue(intensity > 0.0 && intensity < 1.0);
    }

    @Test
    public void testCalculateIntensityWithDifferentFalloffExponent() {
        PointLight pointLight = new PointLight(new Vector3(0, 0, 0), 1.0);
        Vector3 direction = new Vector3(0, 0, -1);
        EnhancedSpotLight spotLight1 = new EnhancedSpotLight(pointLight, direction, 20, 50, 1.0);
        EnhancedSpotLight spotLight2 = new EnhancedSpotLight(pointLight, direction, 20, 50, 4.0);

        // Point between inner and outer cutoff
        Vector3 point = new Vector3(0, 1, -1); // ~45 degrees from z-axis

        double intensity1 = spotLight1.calculateIntensity(point);
        double intensity2 = spotLight2.calculateIntensity(point);

        // Both should be between 0 and 1, but with different values due to falloff
        assertTrue(intensity1 > 0.0 && intensity1 < 1.0);
        assertTrue(intensity2 > 0.0 && intensity2 < 1.0);
        // Higher falloff exponent should result in lower intensity
        assertTrue(intensity2 < intensity1);
    }
}

