class TestTreePathAnalyzer {

    @Test
    public void testEmptyTree() {
        TreePathAnalyzer analyzer = new TreePathAnalyzer();
        TreeAnalysisResult result = analyzer.analyzeTreePaths(null, null);

        assertTrue(result.paths.isEmpty());
    }

    @Test
    public void testSingleNodeTree() {
        TreePathAnalyzer analyzer = new TreePathAnalyzer();
        TreeNode root = new TreeNode(5);
        TreeAnalysisResult result = analyzer.analyzeTreePaths(root, null);

        assertEquals(1, result.paths.size());
        assertEquals(Arrays.asList(5), result.paths.get(0));
    }

    @Test
    public void testSimpleTree() {
        TreePathAnalyzer analyzer = new TreePathAnalyzer();
        TreeNode root = new TreeNode(1);
        root.left = new TreeNode(2);
        root.right = new TreeNode(3);

        TreeAnalysisResult result = analyzer.analyzeTreePaths(root, null);

        assertEquals(2, result.paths.size());
        assertTrue(result.paths.contains(Arrays.asList(1, 2)));
        assertTrue(result.paths.contains(Arrays.asList(1, 3)));
    }

    @Test
    public void testComplexTree() {
        TreePathAnalyzer analyzer = new TreePathAnalyzer();
        TreeNode root = new TreeNode(1);
        root.left = new TreeNode(2);
        root.right = new TreeNode(3);
        root.left.left = new TreeNode(4);
        root.left.right = new TreeNode(5);

        TreeAnalysisResult result = analyzer.analyzeTreePaths(root, null);

        assertEquals(3, result.paths.size());
        assertTrue(result.paths.contains(Arrays.asList(1, 2, 4)));
        assertTrue(result.paths.contains(Arrays.asList(1, 2, 5)));
        assertTrue(result.paths.contains(Arrays.asList(1, 3)));
    }
}

