        emailStats.put("type", "VARCHAR");
        emailStats.put("size", 255);
        emailStats.put("nullable", true);
        columnStats.put("email", emailStats);

        Map<String, Object> createdAtStats = new HashMap<>();
        createdAtStats.put("type", "TIMESTAMP");
        createdAtStats.put("size", 0);
        createdAtStats.put("nullable", false);
        columnStats.put("created_at", createdAtStats);

        Map<String, Object> updatedAtStats = new HashMap<>();
        updatedAtStats.put("type", "TIMESTAMP");
        updatedAtStats.put("size", 0);
        updatedAtStats.put("nullable", true);
        columnStats.put("updated_at", updatedAtStats);

        result.put("columnStats", columnStats);

        return result;
    }
}

