import static org.junit.jupiter.api.Assertions.*;
import java.util.function.Consumer;

class TestAsyncResponseHandler {
    @Test
    void testRegisterCallbackStoresMapping() {
        AsyncResponseHandler handler = new AsyncResponseHandler();
        Consumer<Object> dummyCallback = obj -> {};

        handler.registerCallback("testType", dummyCallback);

        // Use reflection to verify the callback was stored
        try {
            java.lang.reflect.Field callbacksField = AsyncResponseHandler.class.getDeclaredField("callbacks");
            callbacksField.setAccessible(true);
            @SuppressWarnings("unchecked")
            java.util.HashMap<String, Consumer<Object>> callbacks = 
                (java.util.HashMap<String, Consumer<Object>>) callbacksField.get(handler);

            assertTrue(callbacks.containsKey("testType"));
            assertSame(dummyCallback, callbacks.get("testType"));
        } catch (Exception e) {
            fail("Failed to verify callback registration: " + e.getMessage());
        }
    }
}

