import java.util.concurrent.*;

class TestCases {
    @Test
    void testAtomicIntegerType() {
        TestExecutor executor = new TestExecutor();
        // Use reflection to verify the field type is AtomicInteger
        try {
            java.lang.reflect.Field field = TestExecutor.class.getDeclaredField("testCounter");
            field.setAccessible(true);
            assertEquals(AtomicInteger.class, field.getType(), "testCounter should be of type AtomicInteger");
        } catch (NoSuchFieldException e) {
            fail("testCounter field not found");
        }
    }

    @Test
    void testIncrementAndGetUsage() {
        TestExecutor executor = new TestExecutor();
        executor.initTest();

        // Execute multiple tests to verify atomic increment behavior
        executor.executeTest(1, "group1", () -> {});
        executor.executeTest(2, "group2", () -> {});

        assertEquals(2, executor.getTestCounter(), "Counter should be incremented atomically to 2");
    }

    @Test
    void testThreadSafety() throws InterruptedException {
        TestExecutor executor = new TestExecutor();
        executor.initTest();

        int numThreads = 10;
        CountDownLatch latch = new CountDownLatch(numThreads);

        // Create multiple threads that increment the counter concurrently
        for (int i = 0; i < numThreads; i++) {
            new Thread(() -> {
                executor.executeTest(1, "concurrent", () -> {});
                latch.countDown();
            }).start();
        }

        latch.await();
        assertEquals(numThreads, executor.getTestCounter(), "All concurrent increments should be captured atomically");
    }

    @Test
    void testBackwardCompatibility() {
        TestExecutor executor = new TestExecutor();
        executor.initTest();

        // Test that existing functionality still works
        boolean result = executor.executeTest(5, "test", () -> {
            assertTrue(true);
        });

