records.current_solution:
import java.util.concurrent.atomic.AtomicInteger;

class TestExecutor {
    private AtomicInteger testCounter;
    private boolean isInitialized;

    public TestExecutor() {
        this.testCounter = new AtomicInteger(0);
        this.isInitialized = false;
    }

    public void initTest() {
        this.isInitialized = true;
        System.out.println("Test init..");
    }

    public void afterTest() {
        this.isInitialized = false;
        System.out.println("Test closed..");
    }

    public boolean executeTest(int priority, String group, Runnable testLogic) {
        if (!isInitialized) {
            throw new IllegalStateException("Executor not initialized");
        }

        System.out.println("Executing test with priority " + priority + " in group '" + group + "'");
        testCounter.incrementAndGet();

        try {
            testLogic.run();
            System.out.println("Test passed");
            return true;
        } catch (AssertionError e) {
            System.out.println("Test failed: " + e.getMessage());
            return false;
        }
    }

    public boolean isInitialized() {
        return isInitialized;
    }

    public int getTestCount() {
        return testCounter.get();
    }
}

