        settings.put("invalid3", new HashMap<>());

        manager.updateUserSettings(settings, "user2");

        Map<String, Map<String, Object>> allSettings = manager.getUserSettings();
        Map<String, Object> userSettings = allSettings.get("user2");

        // The user entry should exist but be empty since no valid settings were provided
        assertNotNull(userSettings);
        assertTrue(userSettings.isEmpty());
    }

    @Test
    public void testUpdateUserSettingsPreservesExistingSettings() {
        UserSettingsManager manager = new UserSettingsManager();

        // First set some existing settings
        manager.saveUserSetting("existingKey", "existingValue", "user3");

        // Now update with new settings
        Map<String, Object> newSettings = new HashMap<>();
        newSettings.put("newKey", "newValue");
        newSettings.put("invalidKey", new Object());

        manager.updateUserSettings(newSettings, "user3");

        // Both old and new valid settings should exist
        assertEquals("existingValue", manager.getUserSetting("existingKey", "user3", String.class));
        assertEquals("newValue", manager.getUserSetting("newKey", "user3", String.class));
        assertNull(manager.getUserSetting("invalidKey", "user3", Object.class));
    }
}

