import java.util.*;

// Basic implementation of EnhancedPositionDao with only createPosition
class EnhancedPositionDao {
    private PositionMapper mapper;
    private PositionValidator validator;

    public EnhancedPositionDao(PositionMapper mapper, PositionValidator validator) {
        this.mapper = mapper;
        this.validator = validator;
    }

    public void createPosition(Position position) {
        validator.validate(position);
        mapper.insert(position);
    }

    public void updatePosition(Position position) {
        // Validate the position
        try {
            validator.validate(position);
        } catch (Exception e) {
            throw new IllegalArgumentException("Invalid position", e);
        }

        // Check if position exists
        Position existingPosition = mapper.selectOne(position);
        if (existingPosition == null) {
            throw new IllegalArgumentException("Position does not exist");
        }

        // Update the position
        mapper.update(position);
    }

    public int deletePosition(Position position) {
        // Check if position exists
        Position existingPosition = mapper.selectOne(position);
        if (existingPosition == null) {
            throw new IllegalArgumentException("Position does not exist");
        }

        // Delete the position and return affected rows
        return mapper.delete(position);
    }

    public List<Position> findPositions(int pageNumber, int pageSize) {
        if (pageNumber < 1 || pageSize < 1) {
            throw new IllegalArgumentException();
        }

        int offset = (pageNumber - 1) * pageSize;
        return mapper.selectWithPagination(offset, pageSize);
    }

    public int countPositions(Position criteria) {
        return mapper.selectCount(criteria);
    }
}

