import java.util.*;

class FactorySimulation {
    public static int[] taskFunc(int inputStock, int itemsToProcess) {
        int processed = Math.min(inputStock, itemsToProcess);
        int remaining = inputStock - processed;
        return new int[]{processed, remaining};
    }
}

