import java.util.*;
import java.util.stream.Collectors;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class TestCases {

    @Test
    public void testUserFrequencyWithMultipleUsers() {
        LogAnalyzer analyzer = new LogAnalyzer();
        List<LogAnalyzer.SysLog> logs = Arrays.asList(
            new LogAnalyzer.SysLog("alice", "login", 1000, "INFO"),
            new LogAnalyzer.SysLog("bob", "file access", 1001, "INFO"),
            new LogAnalyzer.SysLog("alice", "data update", 1002, "INFO"),
            new LogAnalyzer.SysLog("charlie", "logout", 1003, "INFO"),
            new LogAnalyzer.SysLog("alice", "query", 1004, "INFO")
        );

        Map<String, Object> result = analyzer.analyzeLogs(logs);

        // Check that userFrequency exists and is of correct type
        assertTrue(result.containsKey("userFrequency"));
        assertTrue(result.get("userFrequency") instanceof Map);

        @SuppressWarnings("unchecked")
        Map<String, Long> userFrequency = (Map<String, Long>) result.get("userFrequency");

        // Check specific counts
        assertEquals(3L, userFrequency.get("alice"));
        assertEquals(1L, userFrequency.get("bob"));
        assertEquals(1L, userFrequency.get("charlie"));

        // Check total logs
        assertEquals(5, result.get("totalLogs"));
    }

    @Test
    public void testUserFrequencyWithSingleUser() {
        LogAnalyzer analyzer = new LogAnalyzer();
        List<LogAnalyzer.SysLog> logs = Arrays.asList(
            new LogAnalyzer.SysLog("alice", "login", 1000, "INFO"),
            new LogAnalyzer.SysLog("alice", "data update", 1002, "INFO")
        );

        Map<String, Object> result = analyzer.analyzeLogs(logs);

        @SuppressWarnings("unchecked")
        Map<String, Long> userFrequency = (Map<String, Long>) result.get("userFrequency");

        assertEquals(1, userFrequency.size());
        assertEquals(2L, userFrequency.get("alice"));
        assertEquals(2, result.get("totalLogs"));
    }

    @Test
    public void testUserFrequencyWithEmptyLogs() {
        LogAnalyzer analyzer = new LogAnalyzer();
        List<LogAnalyzer.SysLog> logs = new ArrayList<>();

        Map<String, Object> result = analyzer.analyzeLogs(logs);

        // Should contain error message and not userFrequency
        assertTrue(result.containsKey("error"));
        assertFalse(result.containsKey("userFrequency"));
    }

    @Test
    public void testUserFrequencyWithNullLogs() {
        LogAnalyzer analyzer = new LogAnalyzer();

        Map<String, Object> result = analyzer.analyzeLogs(null);

        // Should contain error message and not userFrequency
        assertTrue(result.containsKey("error"));
        assertFalse(result.containsKey("userFrequency"));
    }
}

