        userManager.registerUser(new User("john_doe", "password123", "john@example.com"));
        userManager.registerUser(new User("jane_smith", "password456", "jane@test.com"));
        userManager.registerUser(new User("bob_jones", "password789", "bob@example.org"));
        userManager.registerUser(new User("alice_brown", "passwordabc", "alice@sample.net"));
        userManager.registerUser(new User("charlie_wilson", "passworddef", "charlie@example.com"));
    }

    @Test
    void testSearchUsersWithUsernameFilter() {
        List<User> result = userManager.searchUsers("john", null, 1, 10);
        assertEquals(1, result.size());
        assertEquals("john_doe", result.get(0).getUsername());
    }

    @Test
    void testSearchUsersWithEmailFilter() {
        List<User> result = userManager.searchUsers(null, "example.com", 1, 10);
        assertEquals(2, result.size());
        assertTrue(result.stream().anyMatch(u -> u.getUsername().equals("john_doe")));
        assertTrue(result.stream().anyMatch(u -> u.getUsername().equals("charlie_wilson")));
    }

    @Test
    void testSearchUsersWithBothFilters() {
        List<User> result = userManager.searchUsers("bob", "example", 1, 10);
        assertEquals(1, result.size());
        assertEquals("bob_jones", result.get(0).getUsername());
    }

    @Test
    void testSearchUsersWithPagination() {
        List<User> page1 = userManager.searchUsers(null, null, 1, 2);
        List<User> page2 = userManager.searchUsers(null, null, 2, 2);
        List<User> page3 = userManager.searchUsers(null, null, 3, 2);

        assertEquals(2, page1.size());
        assertEquals(2, page2.size());
        assertEquals(1, page3.size());

        // Ensure no duplicates across pages
        Set<String> allUsernames = new HashSet<>();
        page1.forEach(u -> allUsernames.add(u.getUsername()));
        page2.forEach(u -> allUsernames.add(u.getUsername()));
        page3.forEach(u -> allUsernames.add(u.getUsername()));
        assertEquals(5, allUsernames.size());
    }

    @Test
    void testSearchUsersPageExceedsData() {
        List<User> result = userManager.searchUsers(null, null, 10, 10);
        assertTrue(result.isEmpty());
    }

    @Test
    void testSearchUsersPartialMatching() {
        List<User> result = userManager.searchUsers("o", null, 1, 10);
        assertEquals(4, result.size());
        assertTrue(result.stream().anyMatch(u -> u.getUsername().equals("john_doe")));
        assertTrue(result.stream().anyMatch(u -> u.getUsername().equals("bob_jones")));
        assertTrue(result.stream().anyMatch(u -> u.getUsername().equals("alice_brown")));
        assertTrue(result.stream().anyMatch(u -> u.getUsername().equals("charlie_wilson")));
    }

    @Test
    void testSearchUsersCaseInsensitive() {
        List<User> result = userManager.searchUsers("JOHN", "EXAMPLE.COM", 1, 10);
        assertEquals(1, result.size());
        assertEquals("john_doe", result.get(0).getUsername());
    }

    @Test
    void testSearchUsersNoMatches() {
        List<User> result = userManager.searchUsers("nonexistent", null, 1, 10);
        assertTrue(result.isEmpty());
    }
}

