import java.util.*;

class LinkedListNode {
    int val;
    LinkedListNode next;

    LinkedListNode(int val) {
        this.val = val;
        this.next = null;
    }
}

class LinkedListSwapper {
    public static LinkedListNode swapNodes(LinkedListNode head, int i, int j) {
        // Calculate the length of the linked list
        int length = 0;
        LinkedListNode current = head;
        while (current != null) {
            length++;
            current = current.next;
        }

        // Bounds checking: if either index is out of bounds, return original head
        if (i >= length || j >= length) {
            return head;
        }

        // Handle the case where indices are equal - no swap needed
        if (i == j) {
            return head;
        }

        // Handle edge case where one of the indices is 0
        if (i == 0 || j == 0) {
            // Ensure i is the smaller index for consistency
            if (i > j) {
                int temp = i;
                i = j;
                j = temp;
            }

            // i is 0, j is some other position
            LinkedListNode prevJ = null;
            LinkedListNode nodeJ = head;

            // Find node at position j and its predecessor
            for (int k = 0; k < j; k++) {
                prevJ = nodeJ;
                nodeJ = nodeJ.next;
            }

            LinkedListNode nodeI = head; // Node at position 0

            // Perform the swap
            prevJ.next = nodeI;
            LinkedListNode temp = nodeI.next;
            nodeI.next = nodeJ.next;
            nodeJ.next = temp;

            return nodeJ; // New head
        }

        // Neither index is 0 - general case
        // Ensure i < j for consistency
        if (i > j) {
            int temp = i;
            i = j;
            j = temp;
        }

        LinkedListNode prevI = null, nodeI = head;
        LinkedListNode prevJ = null, nodeJ = head;

        // Find node at position i and its predecessor
        for (int k = 0; k < i; k++) {
            prevI = nodeI;
            nodeI = nodeI.next;
        }

        // Find node at position j and its predecessor
        for (int k = 0; k < j; k++) {
            prevJ = nodeJ;
            nodeJ = nodeJ.next;
        }

        // Perform the swap
        prevI.next = nodeJ;
        prevJ.next = nodeI;

        LinkedListNode temp = nodeI.next;
        nodeI.next = nodeJ.next;
        nodeJ.next = temp;

        return head;
    }

    public static LinkedListNode createLinkedList(List<Integer> values) {
        if (values.isEmpty()) {
            return null;
        }

        LinkedListNode head = new LinkedListNode(values.get(0));
        LinkedListNode current = head;

        for (int i = 1; i < values.size(); i++) {
            current.next = new LinkedListNode(values.get(i));
            current = current.next;
        }

        return head;
    }

    public static List<Integer> linkedListToList(LinkedListNode head) {
        List<Integer> result = new ArrayList<>();
        LinkedListNode current = head;

        while (current != null) {
            result.add(current.val);
            current = current.next;
        }

        return result;
    }
}

