            assertTrue(java.lang.reflect.Modifier.isStatic(loggerField.getModifiers()));
            assertTrue(java.lang.reflect.Modifier.isFinal(loggerField.getModifiers()));
            assertEquals(Logger.class, loggerField.getType());
