            .findFirst()
            .orElse(null);

        assertNotNull(severeRecord, "No SEVERE level log record found");

        String logMessage = severeRecord.getMessage();
        assertTrue(logMessage.contains("RuntimeException"), "Log message should contain exception type");
        assertTrue(logMessage.contains("Test error message"), "Log message should contain exception message");
        assertTrue(logMessage.contains("userId=12345"), "Log message should contain context information");
        assertTrue(logMessage.contains("operation=testOperation"), "Log message should contain context information");

        logger.removeHandler(testHandler);
    }

