        assertTrue(logMessage.contains("IllegalArgumentException"), "Log message should contain exception type");
        assertTrue(logMessage.contains("Null context test"), "Log message should contain exception message");
        assertFalse(logMessage.contains("Context:"), "Log message should not contain context section when context is null");

        logger.removeHandler(testHandler);
    }
}

