        assertEquals(2, result.get("maxDepth")); // map -> values
        assertEquals(1, (int) typeCounts.get("JSONObject"));
        assertEquals(1, (int) typeCounts.get("String"));
        assertEquals(1, (int) typeCounts.get("Number"));
        assertEquals(1, (int) typeCounts.get("Boolean"));
        assertEquals(1, (int) typeCounts.get("byte[]"));
        assertEquals(true, result.get("containsBinary"));
    }
}

