import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;
import java.util.Map;
import org.json.JSONObject;
import org.json.JSONArray;

class TestDataStructureAnalyzer {

    @Test
    public void testJSONObjectHandling() {
        JSONObject jsonObj = new JSONObject();
        jsonObj.put("name", "John");
        jsonObj.put("age", 30);

        Map<String, Object> result = DataStructureAnalyzer.analyzeDataStructure(jsonObj);

        @SuppressWarnings("unchecked")
        Map<String, Integer> typeCounts = (Map<String, Integer>) result.get("typeCounts");

        assertEquals(1, (int) typeCounts.get("JSONObject"));
        assertEquals(1, (int) typeCounts.get("String"));
        assertEquals(1, (int) typeCounts.get("Number"));
        assertEquals(3, (int) result.get("totalElements"));
        assertEquals(2, (int) result.get("maxDepth"));
    }

    @Test
    public void testJSONArrayHandling() {
        JSONArray jsonArr = new JSONArray();
        jsonArr.put("hello");
        jsonArr.put(42);
        jsonArr.put(true);

        Map<String, Object> result = DataStructureAnalyzer.analyzeDataStructure(jsonArr);

        @SuppressWarnings("unchecked")
        Map<String, Integer> typeCounts = (Map<String, Integer>) result.get("typeCounts");

        assertEquals(1, (int) typeCounts.get("JSONArray"));
        assertEquals(1, (int) typeCounts.get("String"));
        assertEquals(1, (int) typeCounts.get("Number"));
        assertEquals(1, (int) typeCounts.get("Boolean"));
        assertEquals(4, (int) result.get("totalElements"));
        assertEquals(2, (int) result.get("maxDepth"));
    }

    @Test
    public void testNestedJSONObjectAndArray() {
        JSONObject innerObj = new JSONObject();
        innerObj.put("value", "test");

        JSONArray jsonArr = new JSONArray();
        jsonArr.put(innerObj);
        jsonArr.put(123);

        JSONObject outerObj = new JSONObject();
        outerObj.put("data", jsonArr);

        Map<String, Object> result = DataStructureAnalyzer.analyzeDataStructure(outerObj);

        @SuppressWarnings("unchecked")
        Map<String, Integer> typeCounts = (Map<String, Integer>) result.get("typeCounts");

        assertEquals(2, (int) typeCounts.get("JSONObject"));
        assertEquals(1, (int) typeCounts.get("JSONArray"));
        assertEquals(1, (int) typeCounts.get("String"));
        assertEquals(1, (int) typeCounts.get("Number"));
        assertEquals(5, (int) result.get("totalElements"));
        assertEquals(4, (int) result.get("maxDepth"));
    }

    @Test
    public void testJSONObjectWithNullValues() {
        JSONObject jsonObj = new JSONObject();
        jsonObj.put("name", "John");
        jsonObj.put("age", JSONObject.NULL);

        Map<String, Object> result = DataStructureAnalyzer.analyzeDataStructure(jsonObj);

        @SuppressWarnings("unchecked")
        Map<String, Integer> typeCounts = (Map<String, Integer>) result.get("typeCounts");

        assertEquals(1, (int) typeCounts.get("JSONObject"));
        assertEquals(1, (int) typeCounts.get("String"));
        assertEquals(0, (int) typeCounts.get("Number"));
        assertEquals(2, (int) result.get("totalElements"));
    }

    @Test
    public void testJSONArrayWithNullValues() {
        JSONArray jsonArr = new JSONArray();
        jsonArr.put("hello");
        jsonArr.put(JSONObject.NULL);
        jsonArr.put(42);

        Map<String, Object> result = DataStructureAnalyzer.analyzeDataStructure(jsonArr);

        @SuppressWarnings("unchecked")
        Map<String, Integer> typeCounts = (Map<String, Integer>) result.get("typeCounts");

        assertEquals(1, (int) typeCounts.get("JSONArray"));
        assertEquals(1, (int) typeCounts.get("String"));
        assertEquals(1, (int) typeCounts.get("Number"));
        assertEquals(3, (int) result.get("totalElements"));
    }
}

