        dataset1.add(new String[]{"1", "Alice", "25"});
        dataset1.add(new String[]{"2", "Bob", "30"});
        dataset1.add(new String[]{"3", "Charlie", "35"});

        List<String[]> dataset2 = new ArrayList<>();
        dataset2.add(new String[]{"1", "Alice Smith", "Engineer"});
        dataset2.add(new String[]{"2", "Bob Jones", "Manager"});
        dataset2.add(new String[]{"4", "David", "40"});

