        Map<String, List<String[]>> result = matcher.enhancedMatch(dataset1, dataset2, 1, keyIndices);

        // Check matched records
        List<String[]> matched = result.get("matched");
        assertEquals(2, matched.size());
        assertArrayEquals(new String[]{"1", "Alice", "25", "1", "Alice Smith", "Engineer"}, matched.get(0));
