class TestDataMatcher {

    @Test
    void testSkipOutOfBoundsRecordsInExactMatching() {
        DataMatcher matcher = new DataMatcher();

        // Dataset1 has a record with only 1 column (index 0), but we're trying to match on index 1
        List<String[]> dataset1 = Arrays.asList(
            new String[]{"A"},  // This record should be skipped (no index 1)
            new String[]{"B", "key1"}
        );

        // Dataset2 has a record with only 1 column (index 0), but we're trying to match on index 1
        List<String[]> dataset2 = Arrays.asList(
            new String[]{"X"},  // This record should be skipped (no index 1)
            new String[]{"Y", "key1"}
        );

        Map<String, List<String[]>> result = matcher.enhancedMatch(dataset1, dataset2, 1, new int[]{1, 1});

        // Only the valid records should be matched
        assertEquals(1, result.get("matched").size());

        // No records should remain in unmatched lists (both valid records were matched, 
        // and out-of-bounds records were removed)
        assertEquals(0, result.get("unmatched1").size());
        assertEquals(0, result.get("unmatched2").size());
    }

    @Test
    void testSkipOutOfBoundsRecordsInContainsMatching() {
        DataMatcher matcher = new DataMatcher();

        List<String[]> dataset1 = Arrays.asList(
            new String[]{"A"},  // This record should be skipped (no index 1)
            new String[]{"B", "key1"}
        );

        List<String[]> dataset2 = Arrays.asList(
            new String[]{"X"},  // This record should be skipped (no index 1)
            new String[]{"Y", "key"}
        );

        Map<String, List<String[]>> result = matcher.enhancedMatch(dataset1, dataset2, 2, new int[]{1, 1});

        // Only the valid records should be matched ("key1" contains "key")
        assertEquals(1, result.get("matched").size());

        // No records should remain in unmatched lists
        assertEquals(0, result.get("unmatched1").size());
        assertEquals(0, result.get("unmatched2").size());
    }

    @Test
    void testSkipOutOfBoundsRecordsInFuzzyMatching() {
        DataMatcher matcher = new DataMatcher();

        List<String[]> dataset1 = Arrays.asList(
            new String[]{"A"},  // This record should be skipped (no index 1)
            new String[]{"B", "KEY1"}
        );

        List<String[]> dataset2 = Arrays.asList(
            new String[]{"X"},  // This record should be skipped (no index 1)
            new String[]{"Y", "key"}
        );

        Map<String, List<String[]>> result = matcher.enhancedMatch(dataset1, dataset2, 3, new int[]{1, 1});

        // Only the valid records should be matched ("key1" contains "key" case-insensitive)
        assertEquals(1, result.get("matched").size());

        // No records should remain in unmatched lists
        assertEquals(0, result.get("unmatched1").size());
        assertEquals(0, result.get("unmatched2").size());
    }

    @Test
    void testNoMatchingWhenAllRecordsAreOutOfBounds() {
        DataMatcher matcher = new DataMatcher();

        List<String[]> dataset1 = Arrays.asList(
            new String[]{"A"},  // This record should be skipped (no index 1)
            new String[]{"B"}   // This record should be skipped (no index 1)
        );

        List<String[]> dataset2 = Arrays.asList(
            new String[]{"X"},  // This record should be skipped (no index 1)
            new String[]{"Y"}   // This record should be skipped (no index 1)
        );

        Map<String, List<String[]>> result = matcher.enhancedMatch(dataset1, dataset2, 1, new int[]{1, 1});

        // No records should be matched
        assertEquals(0, result.get("matched").size());

        // No records should remain in unmatched lists (all were out-of-bounds)
        assertEquals(0, result.get("unmatched1").size());
        assertEquals(0, result.get("unmatched2").size());
    }
}

