import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;
import java.util.*;

class TestGraphAnalyzer {

    @Test
    public void testDijkstraSpecificBehaviorWithComplexGraph() {
        // This graph specifically tests Dijkstra's greedy choice property
        // A naive BFS or incorrect priority queue would fail this
        int[][] graph = {
            {0, 7, 9, 0, 0, 14},
            {7, 0, 10, 15, 0, 0},
            {9, 10, 0, 11, 0, 2},
            {0, 15, 11, 0, 6, 0},
            {0, 0, 0, 6, 0, 9},
            {14, 0, 2, 0, 9, 0}
        };

        Map<String, Object> result = GraphAnalyzer.analyzeGraph(graph, 0);
        int[] distances = (int[]) result.get("distances");

        // These exact distances can only be achieved with proper Dijkstra implementation
        assertEquals(0, distances[0]);
        assertEquals(7, distances[1]);  // Direct path 0->1
        assertEquals(9, distances[2]);  // Direct path 0->2
        assertEquals(20, distances[3]); // Path 0->2->3 (9+11=20)
        assertEquals(20, distances[4]); // Path 0->5->2->4 would be longer, so 0->2->3->4 (9+11+6=26) vs 0->5->4 (14+9=23) vs 0->2->5->4 (9+2+9=20)
        assertEquals(11, distances[5]); // Path 0->2->5 (9+2=11)
    }

    @Test
    public void testPriorityQueueOrderingCritical() {
        // This test would fail if vertices aren't processed by minimum distance
        int[][] graph = {
            {0, 10, 3, 0, 0},
            {10, 0, 1, 2, 0},
            {3, 1, 0, 8, 2},
            {0, 2, 8, 0, 7},
            {0, 0, 2, 7, 0}
        };

        Map<String, Object> result = GraphAnalyzer.analyzeGraph(graph, 0);
        int[] distances = (int[]) result.get("distances");

        assertEquals(0, distances[0]);
        assertEquals(4, distances[1]); // 0->2->1 (3+1=4) not direct 0->1 (10)
        assertEquals(3, distances[2]); // direct 0->2
        assertEquals(6, distances[3]); // 0->2->1->3 (3+1+2=6)
        assertEquals(5, distances[4]); // 0->2->4 (3+2=5)
    }

    @Test
    public void testInitializationRequirements() {
        // Test that distances array is properly initialized with Integer.MAX_VALUE
        int[][] graph = {
            {0, 5, 0},
            {5, 0, 0},
            {0, 0, 0}  // Vertex 2 is isolated
        };

        Map<String, Object> result = GraphAnalyzer.analyzeGraph(graph, 0);
        int[] distances = (int[]) result.get("distances");

        assertEquals(0, distances[0]);  // Source must be 0
        assertEquals(5, distances[1]);  // Reachable vertex
        assertEquals(Integer.MAX_VALUE, distances[2]); // Unreachable must be MAX_VALUE
    }

    @Test
    public void testVertexClassUsageInPriorityQueue() {
        // This test ensures the Vertex class is actually used correctly
        // A simple array-based approach without proper Vertex objects would fail
        int[][] graph = {
            {0, 1, 4, 0},
            {1, 0, 2, 5},
            {4, 2, 0, 1},
            {0, 5, 1, 0}
        };

        Map<String, Object> result = GraphAnalyzer.analyzeGraph(graph, 0);
        int[] distances = (int[]) result.get("distances");

        assertEquals(0, distances[0]);
        assertEquals(1, distances[1]); // Direct 0->1
        assertEquals(3, distances[2]); // 0->1->2 (1+2=3) not direct 0->2 (4)
        assertEquals(4, distances[3]); // 0->1->2->3 (1+2+1=4) not 0->1->3 (1+5=6)
    }

    @Test
    public void testDistanceUpdateLogicSpecific() {
        // Test that distances are updated only when shorter path is found
        int[][] graph = {
            {0, 2, 6, 0},
            {2, 0, 3, 1},
            {6, 3, 0, 1},
            {0, 1, 1, 0}
        };

        Map<String, Object> result = GraphAnalyzer.analyzeGraph(graph, 0);
        int[] distances = (int[]) result.get("distances");

        assertEquals(0, distances[0]);
        assertEquals(2, distances[1]); // Direct 0->1
        assertEquals(4, distances[2]); // 0->1->3->2 (2+1+1=4) not direct 0->2 (6) or 0->1->2 (2+3=5)
        assertEquals(3, distances[3]); // 0->1->3 (2+1=3)
    }
}

