            {1, 0, 0},
            {0, 0, 0}
        };

        Map<String, Object> result = GraphAnalyzer.analyzeGraph(graph, 0);

        // Should only visit 2 vertices (0 and 1), vertex 2 is unreachable
        assertEquals(2, result.get("visitedCount"));
    }

