        // Single vertex graph
        int[][] graph = {{0}};

        Map<String, Object> result = GraphAnalyzer.analyzeGraph(graph, 0);

        // Should visit only 1 vertex (the source itself)
        assertEquals(1, result.get("visitedCount"));
