        Map<String, String> result = FileUploadUtil.parseContentDisposition(header);

        assertEquals("form-data", result.get("type"));
        assertEquals("file", result.get("name"));
        assertEquals("test.txt", result.get("filename"));
        assertEquals(3, result.size());
    }

    @Test
    void testParseContentDispositionWithSingleQuotes() {
        String header = "attachment; filename='document.pdf'";
        Map<String, String> result = FileUploadUtil.parseContentDisposition(header);

        assertEquals("attachment", result.get("type"));
        assertEquals("document.pdf", result.get("filename"));
        assertEquals(2, result.size());
    }

    @Test
    void testParseContentDispositionNoQuotes() {
        String header = "inline; name=test";
        Map<String, String> result = FileUploadUtil.parseContentDisposition(header);

        assertEquals("inline", result.get("type"));
        assertEquals("test", result.get("name"));
        assertEquals(2, result.size());
    }

    @Test
    void testParseContentDispositionEmpty() {
        Map<String, String> result = FileUploadUtil.parseContentDisposition("");
        assertTrue(result.isEmpty());

        result = FileUploadUtil.parseContentDisposition(null);
        assertTrue(result.isEmpty());
    }

    @Test
    void testParseContentDispositionOnlyType() {
        String header = "form-data";
        Map<String, String> result = FileUploadUtil.parseContentDisposition(header);

        assertEquals("form-data", result.get("type"));
        assertEquals(1, result.size());
    }

    @Test
    void testParseContentDispositionKeyToLowercase() {
        String header = "attachment; FILENAME=\"test.txt\"; Name=\"file\"";
        Map<String, String> result = FileUploadUtil.parseContentDisposition(header);

        assertEquals("attachment", result.get("type"));
        assertEquals("test.txt", result.get("filename"));
        assertEquals("file", result.get("name"));
        assertEquals(3, result.size());
    }
}

