    void testCurrentPageCappedAtTotalPages() {
        PaginationManager manager = new PaginationManager();

        // Test case where currentPage exceeds totalPages
        PaginationResult result = manager.calculatePagination(10, 5, 5); // totalPages = 2, currentPage = 5
        assertEquals(2, result.getCurrentPage()); // Should be capped at totalPages (2)
        assertEquals(2, result.getTotalPages());
        assertEquals(6, result.getStartItem()); // Page 2 starts at item 6
        assertEquals(10, result.getEndItem()); // Page 2 ends at item 10
    }

    @org.junit.jupiter.api.Test
    void testZeroTotalItemsHandling() {
        PaginationManager manager = new PaginationManager();

        // Test zero totalItems case
        PaginationResult result = manager.calculatePagination(0, 10, 1);
        assertEquals(0, result.getTotalItems());
        assertEquals(0, result.getTotalPages());
        assertEquals(0, result.getStartItem()); // No items to display
        assertEquals(0, result.getEndItem()); // No items to display
        assertTrue(result.getVisiblePages().isEmpty()); // No pages to show
    }

    @org.junit.jupiter.api.Test
    void testCurrentPageNotCappedWhenWithinRange() {
        PaginationManager manager = new PaginationManager();

        // Test case where currentPage is within valid range
        PaginationResult result = manager.calculatePagination(10, 5, 1); // totalPages = 2, currentPage = 1
