        hashMethod.setAccessible(true);

        String password = "test123";
        String result1 = (String) hashMethod.invoke(service, password);
        String result2 = (String) hashMethod.invoke(service, password);

        assertEquals(result1, result2, "Hashing the same password should produce the same result");

        // Verify the result is a valid Base64 string by attempting to decode it
        assertDoesNotThrow(() -> java.util.Base64.getDecoder().decode(result1), "Result should be valid Base64");

        // Verify the decoded bytes are 32 bytes (SHA-256 output)
        byte[] decoded = java.util.Base64.getDecoder().decode(result1);
        assertEquals(32, decoded.length, "SHA-256 should produce 32 bytes");
    }

