    public void testUpdateUserValid() {
        UserManager manager = new UserManager();
        manager.addUser("12345678901234567", "originalUser", "https://steamcommunity.com/id/original", "medium.jpg", "full.jpg");

        manager.updateUser("12345678901234567", "updatedUser", "https://steamcommunity.com/id/updated");

        User user = manager.getUserBySteamId("12345678901234567");
        assertEquals("updatedUser", user.getUsername());
        assertEquals("https://steamcommunity.com/id/updated", user.getProfileURL());
    }

    @Test
    public void testUpdateUserNotFound() {
        UserManager manager = new UserManager();

        Exception exception = assertThrows(IllegalArgumentException.class, () -> {
            manager.updateUser("12345678901234567", "newUser", "https://steamcommunity.com/id/new");
        });

        assertEquals("User not found", exception.getMessage());
    }

    @Test
    public void testUpdateUserInvalidUsernameTooShort() {
        UserManager manager = new UserManager();
        manager.addUser("12345678901234567", "originalUser", "https://steamcommunity.com/id/original", "medium.jpg", "full.jpg");

        Exception exception = assertThrows(IllegalArgumentException.class, () -> {
            manager.updateUser("12345678901234567", "a", "https://steamcommunity.com/id/new");
        });

        assertEquals("Username must be 2-32 characters", exception.getMessage());
    }

    @Test
    public void testUpdateUserInvalidUsernameTooLong() {
        UserManager manager = new UserManager();
        manager.addUser("12345678901234567", "originalUser", "https://steamcommunity.com/id/original", "medium.jpg", "full.jpg");

        String longUsername = "a".repeat(33); // 33 characters
        Exception exception = assertThrows(IllegalArgumentException.class, () -> {
            manager.updateUser("12345678901234567", longUsername, "https://steamcommunity.com/id/new");
        });

        assertEquals("Username must be 2-32 characters", exception.getMessage());
    }

    @Test
    public void testUpdateUserInvalidProfileURL() {
        UserManager manager = new UserManager();
        manager.addUser("12345678901234567", "originalUser", "https://steamcommunity.com/id/original", "medium.jpg", "full.jpg");

        Exception exception = assertThrows(IllegalArgumentException.class, () -> {
            manager.updateUser("12345678901234567", "newUser", "https://example.com/invalid");
        });

        assertEquals("Invalid Steam profile URL", exception.getMessage());
    }

    @Test
    public void testAddUserDuplicateSteamId() {
        UserManager manager = new UserManager();
        manager.addUser("12345678901234567", "user1", "https://steamcommunity.com/id/user1", "medium.jpg", "full.jpg");

        Exception exception = assertThrows(IllegalArgumentException.class, () -> {
            manager.addUser("12345678901234567", "user2", "https://steamcommunity.com/id/user2", "medium.jpg", "full.jpg");
        });

        assertEquals("User with this Steam ID already exists", exception.getMessage());
    }
}

