        outContent = new ByteArrayOutputStream();
        System.setOut(new PrintStream(outContent));
        logger = new LoggerService();
        manager = new EnhancedProductManager(logger);
    }

    @Test
    void testLoggerIsUsedWhenAddingProduct() {
        Product product = new Product(1, "Test Product", 5);
        manager.addProduct(product);
        assertTrue(outContent.toString().contains("Product added: Test Product"));
    }

    @Test
    void testNoLogWhenProductIsNull() {
        manager.addProduct(null);
        assertEquals("", outContent.toString());
    }
}

