import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;

class TestCases {
    @Test
    void testRestrictedCategoryRejection() {
        LoggerService logger = new LoggerService();
        List<Integer> restricted = Arrays.asList(5, 10, 15);
        EnhancedProductManager manager = new EnhancedProductManager(logger, restricted);

        Product product = new Product(1, "Test Product", 5);
        Map<String, String> result = manager.addProduct(product);

        assertEquals("error", result.get("status"));
        assertEquals("Products in category 5 are not allowed", result.get("message"));
    }

    @Test
    void testNonRestrictedCategoryAccepted() {
        LoggerService logger = new LoggerService();
        List<Integer> restricted = Arrays.asList(5, 10, 15);
        EnhancedProductManager manager = new EnhancedProductManager(logger, restricted);

        Product product = new Product(1, "Test Product", 3);
        Map<String, String> result = manager.addProduct(product);

        assertEquals("success", result.get("status"));
        assertEquals("Product added successfully", result.get("message"));

        List<Product> products = manager.getAllProducts();
        assertEquals(1, products.size());
        assertEquals(product.getId(), products.get(0).getId());
    }

    @Test
    void testEmptyRestrictedList() {
        LoggerService logger = new LoggerService();
