        @SuppressWarnings("unchecked")
        Map<String, Object> updatedContext = (Map<String, Object>) result.get("updatedContext");

        // Verify extension data is stored under extensionType key
        assertTrue(updatedContext.containsKey("EARLY_DATA"));
        assertEquals(extensionData, updatedContext.get("EARLY_DATA"));

        // Verify maxEarlyDataSize is stored directly in context
        assertTrue(updatedContext.containsKey("maxEarlyDataSize"));
        assertEquals(1024, updatedContext.get("maxEarlyDataSize"));

        // Verify negotiatedExtensions is set for SERVER connectionEnd
        assertTrue(updatedContext.containsKey("negotiatedExtensions"));
        assertEquals("EARLY_DATA", updatedContext.get("negotiatedExtensions"));

        // Verify existing context data is preserved
        assertTrue(updatedContext.containsKey("existingKey"));
        assertEquals("existingValue", updatedContext.get("existingKey"));
    }

    @org.junit.jupiter.api.Test
    void testUpdateTlsContextWithEarlyDataClientConnection() {
        TLSExtensionProcessor processor = new TLSExtensionProcessor();
        Map<String, Object> context = new HashMap<>();

        Map<String, Object> extensionData = new HashMap<>();
        extensionData.put("maxEarlyDataSize", 512);
        extensionData.put("connectionEnd", "CLIENT");

        Map<String, Object> result = processor.processExtension("EARLY_DATA", extensionData, context);

        @SuppressWarnings("unchecked")
        Map<String, Object> updatedContext = (Map<String, Object>) result.get("updatedContext");

        // Verify extension data is stored
        assertEquals(extensionData, updatedContext.get("EARLY_DATA"));

        // Verify maxEarlyDataSize is stored directly
        assertEquals(512, updatedContext.get("maxEarlyDataSize"));

        // Verify negotiatedExtensions is NOT set for CLIENT connectionEnd
        assertFalse(updatedContext.containsKey("negotiatedExtensions"));
    }

    @org.junit.jupiter.api.Test
    void testUpdateTlsContextWithServerNameExtension() {
        TLSExtensionProcessor processor = new TLSExtensionProcessor();
        Map<String, Object> context = new HashMap<>();

        Map<String, Object> extensionData = new HashMap<>();
        extensionData.put("serverName", "example.com");

        Map<String, Object> result = processor.processExtension("SERVER_NAME", extensionData, context);

        // Verify the result contains updatedContext
        assertTrue(result.containsKey("updatedContext"));

        @SuppressWarnings("unchecked")
