        // Verify no updatedContext is included for error status
        assertFalse(result.containsKey("updatedContext"));
        assertEquals("error", result.get("status"));
    }

    @org.junit.jupiter.api.Test
    void testNoContextUpdateForWarningStatus() {
        TLSExtensionProcessor processor = new TLSExtensionProcessor();
        Map<String, Object> context = new HashMap<>();

        Map<String, Object> extensionData = new HashMap<>();
        extensionData.put("someData", "value");

        // This should result in warning status for unsupported extension
        Map<String, Object> result = processor.processExtension("UNSUPPORTED_TYPE", extensionData, context);

        // Verify no updatedContext is included for warning status
        assertFalse(result.containsKey("updatedContext"));
        assertEquals("warning", result.get("status"));
    }
}

