import java.util.*;
import java.util.regex.Pattern;

class ServerApprovalHandler {
    private String serverName;
    private String serverIp;
    private String realmId;
    private String imageId;
    private String hardwareProfileId;
    private Map<String, String> approvalStatus;

    public ServerApprovalHandler(String serverName, String serverIp, String realmId, 
                               String imageId, String hardwareProfileId) {
        this.serverName = serverName;
        this.serverIp = serverIp;
        this.realmId = realmId;
        this.imageId = imageId;
        this.hardwareProfileId = hardwareProfileId;
        this.approvalStatus = new HashMap<>();
    }

    private String validateServerName() {
        if (serverName == null || serverName.isEmpty()) {
            return "Server name cannot be null or empty";
        }
        if (serverName.length() > 64) {
            return "Server name cannot exceed 64 characters";
        }
        return "Valid";
    }

    private String validateIpAddress() {
        if (serverIp == null) {
            return "IP address cannot be null";
        }

        // IPv4 regex pattern: 4 groups of 1-3 digits (0-255) separated by dots
        String ipv4Pattern = "^((25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$";

        if (Pattern.matches(ipv4Pattern, serverIp)) {
            return "Valid";
        } else {
            return "Invalid IPv4 address format";
        }
    }

    private String validateRealmId() {
        if (realmId == null) {
            return "Realm ID cannot be null";
        }

        // Realm ID pattern: 1 to 36 alphanumeric characters or hyphens
        String realmPattern = "^[a-zA-Z0-9-]{1,36}$";

        if (Pattern.matches(realmPattern, realmId)) {
            return "Valid";
        } else {
            return "Realm ID must be 1-36 characters containing only alphanumeric characters and hyphens";
        }
    }

    private String validateImageId() {
        if (imageId == null) {
            return "Image ID cannot be null";
        }

        // Image ID pattern: 'img-' followed by exactly 8 alphanumeric characters
        String imagePattern = "^img-[a-zA-Z0-9]{8}$";

        if (Pattern.matches(imagePattern, imageId)) {
            return "Valid";
        } else {
            return "Image ID must be in format 'img-' followed by exactly 8 alphanumeric characters";
        }
    }

    private String validateHardwareProfile() {
        if (hardwareProfileId == null) {
            return "Hardware profile ID cannot be null";
        }

        // Hardware profile pattern: 'hw-' followed by 4 alphanumerics, a hyphen, and another 4 alphanumerics
        String hardwarePattern = "^hw-[a-zA-Z0-9]{4}-[a-zA-Z0-9]{4}$";

        if (Pattern.matches(hardwarePattern, hardwareProfileId)) {
            return "Valid";
        } else {
            return "Hardware profile ID must be in format 'hw-' followed by 4 alphanumerics, a hyphen, and another 4 alphanumerics";
        }
    }

    public Map<String, Object> validateConfiguration() {
        Map<String, Object> validationResults = new HashMap<>();
        return validationResults;
    }

    public Map<String, Object> processApproval() {
        Map<String, Object> result = new HashMap<>();
        result.put("approvalStatus", approvalStatus);
        result.put("message", "");
        result.put("validationResults", validateConfiguration());
        return result;
    }
}

