import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;
import java.util.*;

class TestCourseScheduler {

    @Test
    void testGraphBuildingAndInDegreeCalculation() {
        CourseScheduler scheduler = new CourseScheduler();

        // Test case: 3 courses, 2 prerequisites
        // Course 1 requires course 0
        // Course 2 requires course 1
        int[][] prerequisites = {{1, 0}, {2, 1}};
        CourseScheduler.Result result = scheduler.scheduleCourses(3, prerequisites);

        // Should identify course 0 as the only starting point (in-degree 0)
        assertEquals(1, result.order.length);
        assertEquals(0, result.order[0]);
        assertTrue(result.canFinish);
    }

    @Test
    void testMultipleStartingPoints() {
        CourseScheduler scheduler = new CourseScheduler();

        // Test case: 4 courses, 2 prerequisites
        // Course 2 requires course 0
        // Course 3 requires course 1
        int[][] prerequisites = {{2, 0}, {3, 1}};
        CourseScheduler.Result result = scheduler.scheduleCourses(4, prerequisites);

        // Should identify courses 0 and 1 as starting points (in-degree 0)
        assertEquals(2, result.order.length);
        // Order could be [0, 1] or [1, 0], so we check if both are present
        List<Integer> orderList = new ArrayList<>();
        for (int course : result.order) {
            orderList.add(course);
        }
        assertTrue(orderList.contains(0));
        assertTrue(orderList.contains(1));
        assertTrue(result.canFinish);
    }

    @Test
    void testNoPrerequisites() {
        CourseScheduler scheduler = new CourseScheduler();

        // Test case: 3 courses, no prerequisites
        int[][] prerequisites = {};
        CourseScheduler.Result result = scheduler.scheduleCourses(3, prerequisites);

        // All courses should be starting points
        assertEquals(3, result.order.length);
        assertTrue(result.canFinish);
    }
}

