import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;
import java.util.*;

class TestCourseScheduler {

    @Test
    void testSimpleLinearSchedule() {
        CourseScheduler scheduler = new CourseScheduler();
        int[][] prerequisites = {{1, 0}, {2, 1}};
        CourseScheduler.Result result = scheduler.scheduleCourses(3, prerequisites);

        assertTrue(result.canFinish);
        assertArrayEquals(new int[]{0, 1, 2}, result.order);
    }

    @Test
    void testScheduleWithCycle() {
        CourseScheduler scheduler = new CourseScheduler();
        int[][] prerequisites = {{1, 0}, {0, 1}}; // Cycle between course 0 and 1
        CourseScheduler.Result result = scheduler.scheduleCourses(2, prerequisites);

        assertFalse(result.canFinish);
        assertEquals(0, result.order.length);
    }

    @Test
    void testComplexGraphWithCycle() {
        CourseScheduler scheduler = new CourseScheduler();
        // Create a cycle: 0->1->2->0 and a separate node 3
        int[][] prerequisites = {{1, 0}, {2, 1}, {0, 2}};
        CourseScheduler.Result result = scheduler.scheduleCourses(4, prerequisites);

        assertFalse(result.canFinish);
        assertEquals(0, result.order.length);
    }

    @Test
    void testNoPrerequisites() {
        CourseScheduler scheduler = new CourseScheduler();
        int[][] prerequisites = {};
        CourseScheduler.Result result = scheduler.scheduleCourses(3, prerequisites);

        assertTrue(result.canFinish);
        assertEquals(3, result.order.length);
        // All courses should be in the result in some valid order
        Set<Integer> courses = new HashSet<>();
        for (int course : result.order) {
            courses.add(course);
        }
        assertEquals(Set.of(0, 1, 2), courses);
    }
}

