import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.Supplier;

class TestAsyncOperationManager {

    @Test
    public void testTimeoutWithFallbackValue() throws Exception {
        AsyncOperationManager manager = new AsyncOperationManager();

        // Create a task that takes longer than the timeout
        Supplier<String> slowTask = () -> {
            try {
                Thread.sleep(200); // Sleep for 200ms
                return "actual result";
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                return "interrupted";
            }
        };

        // Execute with 100ms timeout
        CompletableFuture<String> result = manager.executeWithTimeoutAndRetry(
                slowTask, 100, TimeUnit.MILLISECONDS, "fallback", 3);

        // Should complete with fallback value due to timeout
        assertEquals("fallback", result.get());
    }

    @Test
    public void testNoTimeoutReturnsActualResult() throws Exception {
        AsyncOperationManager manager = new AsyncOperationManager();

        // Create a fast task
        Supplier<String> fastTask = () -> "actual result";

        // Execute with generous timeout
        CompletableFuture<String> result = manager.executeWithTimeoutAndRetry(
                fastTask, 1000, TimeUnit.MILLISECONDS, "fallback", 3);

        // Should complete with actual result (no timeout)
        assertEquals("actual result", result.get());
    }
}

