import static org.junit.jupiter.api.Assertions.*;
import java.io.*;
import java.util.*;

class TestSolution {

    @org.junit.jupiter.api.Test
    public void testDivisionByZero() {
        // Capture System.out to verify the error message
        ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
        PrintStream originalOut = System.out;
        System.setOut(new PrintStream(outputStream));

        try {
            List<Integer> list1 = Arrays.asList(10, 20, 30);
            List<Integer> list2 = Arrays.asList(2, 0, 5);
            List<Integer> result = Solution.task_func(list1, list2);

            // Verify the result contains -1 at index 1
            assertEquals(Arrays.asList(5, -1, 6), result);

            // Verify the error message was printed
            String output = outputStream.toString().trim();
            assertEquals("ArithmeticException at index 1: Division by zero", output);
        } finally {
            System.setOut(originalOut);
        }
    }

    @org.junit.jupiter.api.Test
    public void testMultipleDivisionByZero() {
        ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
        PrintStream originalOut = System.out;
        System.setOut(new PrintStream(outputStream));

        try {
            List<Integer> list1 = Arrays.asList(8, 12, 15);
            List<Integer> list2 = Arrays.asList(0, 0, 3);
            List<Integer> result = Solution.task_func(list1, list2);

            assertEquals(Arrays.asList(-1, -1, 5), result);

            String output = outputStream.toString().trim();
            String[] lines = output.split("\n");
            assertEquals(2, lines.length);
            assertEquals("ArithmeticException at index 0: Division by zero", lines[0]);
            assertEquals("ArithmeticException at index 1: Division by zero", lines[1]);
        } finally {
            System.setOut(originalOut);
        }
    }

    @org.junit.jupiter.api.Test
    public void testNormalDivisionStillWorks() {
        List<Integer> list1 = Arrays.asList(10, 20, 30);
        List<Integer> list2 = Arrays.asList(2, 4, 5);
        List<Integer> result = Solution.task_func(list1, list2);

        assertEquals(Arrays.asList(5, 5, 6), result);
    }
}

