import java.util.*;

class Solution {
    public static List<Integer> task_func(List<Integer> list1, List<Integer> list2) {
        List<Integer> result = new ArrayList<>();

        for (int i = 0; i < list1.size(); i++) {
            try {
                Integer numerator = list1.get(i);
                Integer denominator = list2.get(i);

                if (numerator == null || denominator == null) {
                    throw new NullPointerException();
                }

                result.add(numerator / denominator);
            } catch (ArithmeticException e) {
                System.out.println("ArithmeticException at index " + i + ": Division by zero");
                result.add(-1);
            } catch (NullPointerException e) {
                System.out.println("NullPointerException at index " + i);
                result.add(-2);
            } catch (IndexOutOfBoundsException e) {
                System.out.println("ArrayIndexOutOfBoundsException at index " + i);
                result.add(-3);
                return result;
            }
        }

        return result;
    }
}

