import java.util.*;

public class FinancialReportAnalyzer {
    public static class PolicyData {
        private String previousRiskCode;
        private String currentRiskCode;
        private String previousRiskName;
        private String currentRiskName;
        private double premium;

        // Constructor
        public PolicyData(String previousRiskCode, String currentRiskCode, 
                         String previousRiskName, String currentRiskName, double premium) {
            this.previousRiskCode = previousRiskCode;
            this.currentRiskCode = currentRiskCode;
            this.previousRiskName = previousRiskName;
            this.currentRiskName = currentRiskName;
            this.premium = premium;
        }

        // Getters
        public String getPreviousRiskCode() { return previousRiskCode; }
        public String getCurrentRiskCode() { return currentRiskCode; }
        public String getPreviousRiskName() { return previousRiskName; }
        public String getCurrentRiskName() { return currentRiskName; }
        public double getPremium() { return premium; }
    }

    public static class RiskSummary {
        private String riskCode;
        private String riskName;
        private double totalPremium;
        private int policyCount;

        public RiskSummary(String riskCode, String riskName) {
            this.riskCode = riskCode;
            this.riskName = riskName;
            this.totalPremium = 0.0;
            this.policyCount = 0;
        }

        public void addPolicy(double premium) {
            this.totalPremium += premium;
            this.policyCount++;
        }

        // Getters
        public String getRiskCode() { return riskCode; }
        public String getRiskName() { return riskName; }
        public double getTotalPremium() { return totalPremium; }
        public int getPolicyCount() { return policyCount; }
    }

    public Map<String, Object> analyzeFinancialData(List<PolicyData> policies) {
        Map<String, Object> result = new HashMap<>();

        double totalPremiums = 0.0;
        int policyCount = 0;

        // Maps to hold risk summaries
        Map<String, RiskSummary> previousRiskMap = new HashMap<>();
        Map<String, RiskSummary> currentRiskMap = new HashMap<>();

        if (policies != null) {
            for (PolicyData policy : policies) {
                totalPremiums += policy.getPremium();
                policyCount++;

                // Handle previous risk
                String prevKey = policy.getPreviousRiskCode() + "|" + policy.getPreviousRiskName();
                RiskSummary prevSummary = previousRiskMap.get(prevKey);
                if (prevSummary == null) {
                    prevSummary = new RiskSummary(policy.getPreviousRiskCode(), policy.getPreviousRiskName());
                    previousRiskMap.put(prevKey, prevSummary);
                }
                prevSummary.addPolicy(policy.getPremium());

                // Handle current risk
                String curKey = policy.getCurrentRiskCode() + "|" + policy.getCurrentRiskName();
                RiskSummary curSummary = currentRiskMap.get(curKey);
                if (curSummary == null) {
                    curSummary = new RiskSummary(policy.getCurrentRiskCode(), policy.getCurrentRiskName());
                    currentRiskMap.put(curKey, curSummary);
                }
                curSummary.addPolicy(policy.getPremium());
            }
        }

        result.put("totalPremiums", totalPremiums);
        result.put("policyCount", policyCount);

        // Convert maps to lists of maps
        List<Map<String, Object>> preRiskSummary = new ArrayList<>();
        for (RiskSummary summary : previousRiskMap.values()) {
            Map<String, Object> entry = new HashMap<>();
            entry.put("riskCode", summary.getRiskCode());
            entry.put("riskName", summary.getRiskName());
            entry.put("premium", String.format("%.2f", summary.getTotalPremium()));
            entry.put("policyCount", summary.getPolicyCount());
            preRiskSummary.add(entry);
        }

        List<Map<String, Object>> curRiskSummary = new ArrayList<>();
        for (RiskSummary summary : currentRiskMap.values()) {
            Map<String, Object> entry = new HashMap<>();
            entry.put("riskCode", summary.getRiskCode());
            entry.put("riskName", summary.getRiskName());
            entry.put("premium", String.format("%.2f", summary.getTotalPremium()));
            entry.put("policyCount", summary.getPolicyCount());
            curRiskSummary.add(entry);
        }

        result.put("preRiskSummary", preRiskSummary);
        result.put("curRiskSummary", curRiskSummary);

        return result;
    }
}

