        assertTrue(result.containsKey("maxDiff"));
        assertTrue(result.containsKey("minDiff"));
        assertTrue(result.containsKey("nodeCount"));
        assertTrue(result.containsKey("avgDiff"));

        // Verify avgDiff is floor of (sum / nodeCount)
        int nodeCount = result.get("nodeCount");
        assertEquals(9, nodeCount);

        // The avgDiff should be a reasonable value (not 0 for this tree)
