import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;

class TestEnhancedBlockingQueue {
    @Test
    void testPeekReturnsNullWhenEmpty() {
        EnhancedBlockingQueue<Integer> q = new EnhancedBlockingQueue<>(2);
        assertNull(q.peek());
    }

    @Test
    void testPeekReturnsHeadWithoutRemoving() {
        EnhancedBlockingQueue<String> q = new EnhancedBlockingQueue<>(2);
        try {
            q.offer("A", 0, java.util.concurrent.TimeUnit.NANOSECONDS);
        } catch (InterruptedException e) {
            throw new RuntimeException(e);
        }
        assertEquals("A", q.peek());
        assertEquals("A", q.peek()); // still there
    }

    @Test
    void testSizeReflectsCurrentCount() {
        EnhancedBlockingQueue<Integer> q = new EnhancedBlockingQueue<>(3);
        assertEquals(0, q.size());
        try {
            q.offer(1, 0, java.util.concurrent.TimeUnit.NANOSECONDS);
            assertEquals(1, q.size());
            q.offer(2, 0, java.util.concurrent.TimeUnit.NANOSECONDS);
            assertEquals(2, q.size());
        } catch (InterruptedException e) {
            throw new RuntimeException(e);
        }
    }

    @Test
    void testRemainingCapacity() {
        EnhancedBlockingQueue<Integer> q = new EnhancedBlockingQueue<>(3);
        assertEquals(3, q.remainingCapacity());
        try {
            q.offer(1, 0, java.util.concurrent.TimeUnit.NANOSECONDS);
            assertEquals(2, q.remainingCapacity());
            q.offer(2, 0, java.util.concurrent.TimeUnit.NANOSECONDS);
            assertEquals(1, q.remainingCapacity());
        } catch (InterruptedException e) {
            throw new RuntimeException(e);
        }
    }

    @Test
    void testClearReturnsRemovedCount() {
        EnhancedBlockingQueue<Integer> q = new EnhancedBlockingQueue<>(5);
        try {
            q.offer(1, 0, java.util.concurrent.TimeUnit.NANOSECONDS);
            q.offer(2, 0, java.util.concurrent.TimeUnit.NANOSECONDS);
        } catch (InterruptedException e) {
            throw new RuntimeException(e);
        }
        assertEquals(2, q.clear());
    }

    @Test
    void testClearEmptiesQueue() {
        EnhancedBlockingQueue<Integer> q = new EnhancedBlockingQueue<>(5);
        try {
            q.offer(1, 0, java.util.concurrent.TimeUnit.NANOSECONDS);
        } catch (InterruptedException e) {
            throw new RuntimeException(e);
        }
        q.clear();
        assertEquals(0, q.size());
        assertNull(q.peek());
    }
}

