import java.util.*;
import java.util.concurrent.*;

class AdvancedDotProductCalculator {
    public static int calculateDotProduct(int[] array1, int[] array2) {
        if (array1 == null) {
            throw new IllegalArgumentException("First array cannot be null");
        }
        if (array2 == null) {
            throw new IllegalArgumentException("Second array cannot be null");
        }
        if (array1.length != array2.length) {
            throw new IllegalArgumentException("Arrays must have the same length");
        }

        int dotProduct = 0;
        for (int i = 0; i < array1.length; i++) {
            dotProduct += array1[i] * array2[i];
        }

        return dotProduct;
    }

    public static int calculateDotProduct(int[] array1, int[] array2, int threadCount) {
        if (array1 == null) {
            throw new IllegalArgumentException("First array cannot be null");
        }
        if (array2 == null) {
            throw new IllegalArgumentException("Second array cannot be null");
        }
        if (array1.length != array2.length) {
            throw new IllegalArgumentException("Arrays must have the same length");
        }
        if (threadCount <= 0) {
            throw new IllegalArgumentException("Thread count must be greater than zero");
        }

        // Limit threads to minimum of threadCount and array length
        int actualThreadCount = Math.min(threadCount, array1.length);

        ExecutorService executor = Executors.newFixedThreadPool(actualThreadCount);
        List<Future<Integer>> futures = new ArrayList<>();

        try {
            int chunkSize = array1.length / actualThreadCount;
            int remainder = array1.length % actualThreadCount;

            int startIndex = 0;
            for (int i = 0; i < actualThreadCount; i++) {
                int currentChunkSize = chunkSize + (i < remainder ? 1 : 0);
                int endIndex = startIndex + currentChunkSize;

                final int start = startIndex;
                final int end = endIndex;
                final int taskIndex = i;

                Callable<Integer> task = () -> {
                    int partialSum = 0;
                    for (int j = start; j < end; j++) {
                        partialSum += array1[j] * array2[j];
                    }
                    return partialSum;
                };

                futures.add(executor.submit(task));
                startIndex = endIndex;
            }

            int totalSum = 0;
            for (int i = 0; i < futures.size(); i++) {
                try {
                    totalSum += futures.get(i).get();
                } catch (InterruptedException | ExecutionException e) {
                    throw new RuntimeException("Error computing dot product in task " + i, e);
                }
            }

            return totalSum;
        } finally {
            executor.shutdown();
        }
    }
}

