import static org.junit.jupiter.api.Assertions.*;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.zip.*;
class TestFileHandler {
    @org.junit.jupiter.api.Test
    public void testZipOperation() throws IOException {
        // Create temporary test files
        Path tempDir = Files.createTempDirectory("test_zip");
        Path file1 = tempDir.resolve("file1.txt");
        Path file2 = tempDir.resolve("file2.txt");

        Files.write(file1, "Content of file 1".getBytes());
        Files.write(file2, "Content of file 2".getBytes());

        List<String> files = Arrays.asList(file1.toString(), file2.toString());

        Object result = FileHandler.handleFileOperation("zip", files, "");

        assertTrue(result instanceof byte[], "Result should be a byte array");

        byte[] zipData = (byte[]) result;
        assertTrue(zipData.length > 0, "Zip data should not be empty");

        // Verify the zip content
        ByteArrayInputStream bais = new ByteArrayInputStream(zipData);
        ZipInputStream zis = new ZipInputStream(bais);

        ZipEntry entry1 = zis.getNextEntry();
        assertNotNull(entry1, "First entry should exist");
        assertEquals("file1.txt", entry1.getName(), "First entry name should match");

        ByteArrayOutputStream baos1 = new ByteArrayOutputStream();
        byte[] buffer = new byte[1024];
        int len;
        while ((len = zis.read(buffer)) > 0) {
            baos1.write(buffer, 0, len);
        }
        assertEquals("Content of file 1", baos1.toString(), "First file content should match");

        ZipEntry entry2 = zis.getNextEntry();
        assertNotNull(entry2, "Second entry should exist");
        assertEquals("file2.txt", entry2.getName(), "Second entry name should match");

        ByteArrayOutputStream baos2 = new ByteArrayOutputStream();
        while ((len = zis.read(buffer)) > 0) {
            baos2.write(buffer, 0, len);
        }
        assertEquals("Content of file 2", baos2.toString(), "Second file content should match");

        assertNull(zis.getNextEntry(), "There should be no more entries");

        zis.close();

        // Clean up
        Files.delete(file1);
        Files.delete(file2);
        Files.delete(tempDir);
    }

    @org.junit.jupiter.api.Test
    public void testZipOperationWithNonExistentFile() {
        List<String> files = Arrays.asList("nonexistent.txt");
        Object result = FileHandler.handleFileOperation("zip", files, "");

        assertTrue(result instanceof String, "Result should be a string error message");
        String message = (String) result;
        assertTrue(message.startsWith("Zip failed:"), "Should return a zip failure message");
    }
}

