        return score;
    }
}

class PlayerManager {
    private final Map<String, PlayerInfo> players = new HashMap<>();

    public boolean registerPlayer(String playerId) {
        if (players.containsKey(playerId)) {
            return false; // Duplicate registration rejected
        }
        players.put(playerId, new PlayerInfo(playerId));
        return true;
    }

    public Map<String, PlayerInfo> getPlayers() {
        return players;
    }
}

