    public void testValidBSTWithLeftChild() {
        BSTNode root = new BSTNode(5);
        root.left = new BSTNode(3);
        assertTrue(BSTValidator.isValidBST(root));
    }

    @Test
    public void testValidBSTWithRightChild() {
        BSTNode root = new BSTNode(5);
        root.right = new BSTNode(7);
        assertTrue(BSTValidator.isValidBST(root));
    }

    @Test
    public void testValidBSTWithBothChildren() {
        BSTNode root = new BSTNode(5);
        root.left = new BSTNode(3);
        root.right = new BSTNode(7);
        assertTrue(BSTValidator.isValidBST(root));
    }

