    public void testInvalidBSTLeftChildTooLarge() {
        BSTNode root = new BSTNode(5);
        root.left = new BSTNode(6); // Invalid: left child > parent
        assertFalse(BSTValidator.isValidBST(root));
    }

    @Test
    public void testInvalidBSTRightChildTooSmall() {
