    public void testInvalidBSTWithEqualRightValue() {
        BSTNode root = new BSTNode(5);
        root.right = new BSTNode(5); // Invalid: right child = parent
        assertFalse(BSTValidator.isValidBST(root));
    }

    @Test
    public void testComplexValidBST() {
        BSTNode root = new BSTNode(10);
        root.left = new BSTNode(5);
        root.right = new BSTNode(15);
        root.left.left = new BSTNode(2);
        root.left.right = new BSTNode(7);
        root.right.right = new BSTNode(20);
        assertTrue(BSTValidator.isValidBST(root));
    }

    @Test
    public void testComplexInvalidBST() {
        BSTNode root = new BSTNode(10);
        root.left = new BSTNode(5);
        root.right = new BSTNode(15);
        root.left.right = new BSTNode(12); // Invalid: 12 > 10 but in left subtree
        assertFalse(BSTValidator.isValidBST(root));
    }
}

