class TestBSTValidator {

    @Test
    public void testIsValidBSTInOrderWithValidBST() {
        // Create a valid BST: 2 -> 1, 3
        BSTNode root = new BSTNode(2);
        root.left = new BSTNode(1);
        root.right = new BSTNode(3);

        assertTrue(BSTValidator.isValidBSTInOrder(root));
    }

    @Test
    public void testIsValidBSTInOrderWithInvalidBST() {
        // Create an invalid BST: 1 -> 2, 3 (left child > parent)
        BSTNode root = new BSTNode(1);
        root.left = new BSTNode(2);
        root.right = new BSTNode(3);

        assertFalse(BSTValidator.isValidBSTInOrder(root));
    }

    @Test
    public void testIsValidBSTInOrderWithDuplicates() {
        // Create a BST with duplicates: 2 -> 1, 2
        BSTNode root = new BSTNode(2);
        root.left = new BSTNode(1);
        root.right = new BSTNode(2);

        assertFalse(BSTValidator.isValidBSTInOrder(root));
    }

