    public void testIsValidBSTInOrderWithComplexValidBST() {
        // Create a valid BST: 4 -> (2 -> 1, 3), (6 -> 5, 7)
        BSTNode root = new BSTNode(4);
        root.left = new BSTNode(2);
        root.right = new BSTNode(6);
        root.left.left = new BSTNode(1);
        root.left.right = new BSTNode(3);
        root.right.left = new BSTNode(5);
        root.right.right = new BSTNode(7);

        assertTrue(BSTValidator.isValidBSTInOrder(root));
    }

    @Test
    public void testIsValidBSTInOrderWithComplexInvalidBST() {
        // Create an invalid BST: 4 -> (2 -> 1, 5), (6 -> 3, 7)
        // Node 5 is in left subtree but > root (4)
        BSTNode root = new BSTNode(4);
        root.left = new BSTNode(2);
        root.right = new BSTNode(6);
