class P2PAddressServer {
    private final java.util.concurrent.ConcurrentHashMap<String, PeerInfo> peerRegistry;
    private final int maxPeers;
    private int currentPeers;

    public P2PAddressServer() {
        this.peerRegistry = new java.util.concurrent.ConcurrentHashMap<>();
        this.maxPeers = 100;
        this.currentPeers = 0;
    }

    public P2PAddressServer(int maxPeers) {
        if (maxPeers < 1 || maxPeers > 10000) {
            throw new IllegalArgumentException("maxPeers must be between 1 and 10000 (inclusive)");
        }
        this.peerRegistry = new java.util.concurrent.ConcurrentHashMap<>();
        this.maxPeers = maxPeers;
        this.currentPeers = 0;
    }

    public boolean registerPeer(String peerId, String address, int port) {
        // Input validation for peerId
        if (peerId == null || peerId.isEmpty()) {
