import java.util.*;

class AuthService {
    public Map<String, Object> processOAuth2User(String provider, 
                                               Map<String, Object> userAttributes,
                                               Map<String, User> existingUsers,
                                               Set<Role> availableRoles) {
        String email = (String) userAttributes.get("email");
        User user;
        String status;

        if (existingUsers.containsKey(email)) {
            user = existingUsers.get(email);
            status = "authenticated";
        } else {
            String username = email.split("@")[0] + "_" + provider;
            user = new User(email, username);
            existingUsers.put(email, user);
            status = "registered";
        }

        Map<String, Object> result = new HashMap<>();
        result.put("status", status);
        result.put("user", user);
        result.put("provider", provider);

        return result;
    }
}

class User {
    private String email;
    private String username;

    public User(String email, String username) {
        this.email = email;
        this.username = username;
    }

    public String getEmail() {
        return email;
    }

    public void setEmail(String email) {
        this.email = email;
    }

    public String getUsername() {
        return username;
    }

    public void setUsername(String username) {
        this.username = username;
    }

    @Override
    public String toString() {
        return "User{email='" + email + "', username='" + username + "'}";
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        User user = (User) o;
        return Objects.equals(email, user.email) && Objects.equals(username, user.username);
    }

    @Override
    public int hashCode() {
        return Objects.hash(email, username);
    }
}

