import java.util.*;

class EnhancedBinaryHeap {
    private List<Comparable> heap;
    private List<int[]> vertices; // List to store vertex pairs
    private boolean isMinHeap;

    public EnhancedBinaryHeap() {
        this(true); // Default to min-heap
    }

    public EnhancedBinaryHeap(boolean isMinHeap) {
        this.heap = new ArrayList<>();
        this.vertices = new ArrayList<>();
        this.isMinHeap = isMinHeap;
    }

    // New constructor that accepts an array of Comparable items and heap type
    public EnhancedBinaryHeap(Comparable[] items, boolean isMinHeap) {
        this.isMinHeap = isMinHeap;
        this.heap = new ArrayList<>();
        this.vertices = new ArrayList<>();

        // Initialize heap with items (using dummy vertices)
        for (int i = 0; i < items.length; i++) {
            heap.add(items[i]);
            vertices.add(new int[]{0, 0}); // Dummy vertices
        }

        // Build heap in O(n) time
        buildHeap();
    }

    public void insert(Comparable element, int v1, int v2) throws NoSuchElementException {
        if (element == null) {
            throw new NoSuchElementException("Cannot insert null element");
        }
        heap.add(element);
        vertices.add(new int[]{v1, v2});
        heapifyUp(heap.size() - 1);
    }

    // Overloaded method for backward compatibility
    public void insert(Comparable element) throws NoSuchElementException {
        insert(element, 0, 0);
    }

    public Comparable deleteRoot() throws NoSuchElementException {
        if (isEmpty()) {
            throw new NoSuchElementException("Heap is empty");
        }
        Comparable root = heap.get(0);
        Comparable lastElement = heap.remove(heap.size() - 1);
        int[] lastVertices = vertices.remove(vertices.size() - 1); // Remove the vertex pair for the last element
        if (!isEmpty()) {
            heap.set(0, lastElement);
            vertices.set(0, lastVertices); // Move the last vertex pair to root
            heapifyDown(0);
        }
        return root;
    }

    public Comparable peekRoot() throws NoSuchElementException {
        if (isEmpty()) {
            throw new NoSuchElementException("Heap is empty");
        }
        return heap.get(0);
    }

    public int[] peekRootVertices() throws NoSuchElementException {
        if (isEmpty()) {
            throw new NoSuchElementException("Heap is empty");
        }
        return vertices.get(0);
    }

    public boolean isEmpty() {
        return heap.isEmpty();
    }

    public int size() {
        return heap.size();
    }

    public void makeEmpty() {
        heap.clear();
        vertices.clear();
    }

    // New heapSort method
    public Comparable[] heapSort() throws NoSuchElementException {
        if (isEmpty()) {
            throw new NoSuchElementException("Cannot sort empty heap");
        }
        List<Comparable> sortedList = new ArrayList<>();
        while (!isEmpty()) {
            sortedList.add(deleteRoot());
        }
        return sortedList.toArray(new Comparable[0]);
    }

    private void buildHeap() {
        // Start from the last non-leaf node and heapify down
        for (int i = (heap.size() / 2) - 1; i >= 0; i--) {
            heapifyDown(i);
        }
    }

    private boolean compare(Comparable parent, Comparable child) {
        if (isMinHeap) {
            return parent.compareTo(child) > 0; // For min-heap, parent should be <= child
        } else {
            return parent.compareTo(child) < 0; // For max-heap, parent should be >= child
        }
    }

    private void heapifyUp(int index) {
        if (index == 0) return;
        int parentIndex = (index - 1) / 2;
        if (compare(heap.get(parentIndex), heap.get(index))) {
            Collections.swap(heap, parentIndex, index);
            Collections.swap(vertices, parentIndex, index);
            heapifyUp(parentIndex);
        }
    }

    private void heapifyDown(int index) {
        int leftChildIndex = 2 * index + 1;
        int rightChildIndex = 2 * index + 2;
        int extreme = index; // Index of smallest (for min-heap) or largest (for max-heap)

        if (leftChildIndex < heap.size() && compare(heap.get(extreme), heap.get(leftChildIndex))) {
            extreme = leftChildIndex;
        }

        if (rightChildIndex < heap.size() && compare(heap.get(extreme), heap.get(rightChildIndex))) {
            extreme = rightChildIndex;
        }

        if (extreme != index) {
            Collections.swap(heap, index, extreme);
            Collections.swap(vertices, index, extreme);
            heapifyDown(extreme);
        }
    }

    // New validateHeap method
    public boolean validateHeap() throws NoSuchElementException {
        if (isEmpty()) {
            throw new NoSuchElementException("Cannot validate empty heap");
        }
        return validateHeapHelper(0);
    }

    private boolean validateHeapHelper(int index) {
        // Base case: if it's a leaf node, it's valid
        if (index >= heap.size()) {
            return true;
        }

        int leftChildIndex = 2 * index + 1;
        int rightChildIndex = 2 * index + 2;

        // Check left child
        if (leftChildIndex < heap.size()) {
            if (compare(heap.get(index), heap.get(leftChildIndex))) {
                return false; // Heap property violated
            }
            if (!validateHeapHelper(leftChildIndex)) {
                return false; // Recursively check subtree
            }
        }

        // Check right child
        if (rightChildIndex < heap.size()) {
            if (compare(heap.get(index), heap.get(rightChildIndex))) {
                return false; // Heap property violated
            }
            if (!validateHeapHelper(rightChildIndex)) {
                return false; // Recursively check subtree
            }
        }

        return true; // All checks passed
    }
}

