import java.util.Comparator;

class EnhancedMergeSort {

    public Integer[] sortIntegers(Integer[] array) {
        // Use the generic sort method with natural ordering and ascending=true
        return sort(array, Comparator.naturalOrder(), true);
    }

    public String[] sortStrings(String[] array) {
        // Use the generic sort method with natural ordering and ascending=true
        return sort(array, Comparator.naturalOrder(), true);
    }

    public <T> T[] sort(T[] array, Comparator<? super T> comparator, boolean ascending) {
        // Check for null array
        if (array == null) {
            throw new IllegalArgumentException("Array must not be null");
        }

        // Check for null comparator
        if (comparator == null) {
            throw new IllegalArgumentException("Comparator must not be null");
        }

        // Handle arrays with 0 or 1 element
        if (array.length <= 1) {
            return array;
        }

        // Use the generic merge sort
        return genericMergeSort(array, comparator, ascending);
    }

    private Integer[] mergeSort(Integer[] array) {
        if (array.length <= 1) {
            return array;
        }

        // Split the array into two halves
        int mid = array.length / 2;
        Integer[] left = new Integer[mid];
        Integer[] right = new Integer[array.length - mid];

        System.arraycopy(array, 0, left, 0, mid);
        System.arraycopy(array, mid, right, 0, array.length - mid);

        // Recursively sort both halves
        left = mergeSort(left);
        right = mergeSort(right);

        // Create target array and use the generic merge helper
        Integer[] target = new Integer[left.length + right.length];
        merge(left, right, target, Integer::compareTo, true);
        return target;
    }

    @SuppressWarnings("unchecked")
    private <T> T[] genericMergeSort(T[] array, Comparator<? super T> comparator, boolean ascending) {
        if (array.length <= 1) {
            return array;
        }

        // Split the array into two halves
        int mid = array.length / 2;
        T[] left = (T[]) java.lang.reflect.Array.newInstance(array.getClass().getComponentType(), mid);
        T[] right = (T[]) java.lang.reflect.Array.newInstance(array.getClass().getComponentType(), array.length - mid);

        System.arraycopy(array, 0, left, 0, mid);
        System.arraycopy(array, mid, right, 0, array.length - mid);

        // Recursively sort both halves
        left = genericMergeSort(left, comparator, ascending);
        right = genericMergeSort(right, comparator, ascending);

        // Create target array and use the generic merge helper
        T[] target = (T[]) java.lang.reflect.Array.newInstance(array.getClass().getComponentType(), left.length + right.length);
        merge(left, right, target, comparator, ascending);
        return target;
    }

    private <T> void merge(T[] left, T[] right, T[] target, Comparator<? super T> comparator, boolean ascending) {
        int i = 0, j = 0, k = 0;

        // Merge elements based on comparator and ascending flag
        // Use <= for stable sorting (preserves relative order of equal elements)
        while (i < left.length && j < right.length) {
            int comparison = comparator.compare(left[i], right[j]);
            if (ascending ? comparison <= 0 : comparison >= 0) {
                target[k++] = left[i++];
            } else {
                target[k++] = right[j++];
            }
        }

        // Copy remaining elements from left array
        while (i < left.length) {
            target[k++] = left[i++];
        }

        // Copy remaining elements from right array
        while (j < right.length) {
            target[k++] = right[j++];
        }
    }
}

