        assertTrue(result.contains("Public Methods:"), "Report should contain Public Methods section");

        // Test that Declared Methods section is present
        assertTrue(result.contains("Declared Methods:"), "Report should contain Declared Methods section");

        // Test that some common String methods are listed in Public Methods
        assertTrue(result.contains("public int java.lang.String.length()"), "Should contain String.length() method");
        assertTrue(result.contains("public java.lang.String java.lang.String.substring("), "Should contain String.substring() method");

        // Test that methods appear after constructors in the report
        int constructorsIndex = result.indexOf("Declared Constructors:");
        int methodsIndex = result.indexOf("Public Methods:");
        assertTrue(methodsIndex > constructorsIndex, "Methods sections should appear after constructors sections");
    }

    @Test
