import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;
import java.util.*;

class TestClassAnalyzer {

    @Test
    public void testImplementedInterfacesSection() {
        String result = ClassAnalyzer.analyzeClass("java.util.ArrayList");
        assertTrue(result.contains("Implemented Interfaces:"), "Report should contain 'Implemented Interfaces:' section");
        assertTrue(result.contains("java.util.List"), "ArrayList should implement List interface");
        assertTrue(result.contains("java.util.RandomAccess"), "ArrayList should implement RandomAccess interface");
    }

    @Test
    public void testSuperclassHierarchySection() {
        String result = ClassAnalyzer.analyzeClass("java.util.ArrayList");
        assertTrue(result.contains("Superclass Hierarchy:"), "Report should contain 'Superclass Hierarchy:' section");
        assertTrue(result.contains("java.util.AbstractList"), "ArrayList should have AbstractList as superclass");
        assertTrue(result.contains("java.util.AbstractCollection"), "ArrayList should have AbstractCollection in hierarchy");
        assertTrue(result.contains("java.lang.Object"), "ArrayList should have Object as root superclass");
    }

    @Test
    public void testInterfaceWithNoDirectInterfaces() {
        String result = ClassAnalyzer.analyzeClass("java.lang.Object");
        assertTrue(result.contains("Implemented Interfaces:"), "Report should contain 'Implemented Interfaces:' section");
        assertTrue(result.contains("  None"), "Object should have no implemented interfaces");
    }

    @Test
    public void testObjectClassHierarchy() {
        String result = ClassAnalyzer.analyzeClass("java.lang.Object");
        assertTrue(result.contains("Superclass Hierarchy:"), "Report should contain 'Superclass Hierarchy:' section");
        assertTrue(result.contains("  None"), "Object should have no superclass");
    }

    @Test
    public void testSectionOrder() {
        String result = ClassAnalyzer.analyzeClass("java.util.ArrayList");
        int interfacesIndex = result.indexOf("Implemented Interfaces:");
        int hierarchyIndex = result.indexOf("Superclass Hierarchy:");
        assertTrue(interfacesIndex > 0, "Implemented Interfaces section should be present");
        assertTrue(hierarchyIndex > 0, "Superclass Hierarchy section should be present");
        assertTrue(interfacesIndex < hierarchyIndex, "Implemented Interfaces should come before Superclass Hierarchy");
    }
}

