    void setUp() {
        userManager = new UserManager();
    }

    @Test
    void testRegisterUserSuccess() {
        boolean result = userManager.registerUser("john_doe", "password123", "john@example.com");
        assertTrue(result);
    }

    @Test
    void testRegisterUserAlreadyExists() {
        userManager.registerUser("john_doe", "password123", "john@example.com");
        boolean result = userManager.registerUser("john_doe", "different_password", "john2@example.com");
        assertFalse(result);
    }

    @Test
    void testLoginSuccess() {
        userManager.registerUser("john_doe", "password123", "john@example.com");
        String sessionId = userManager.login("john_doe", "password123");
        assertNotNull(sessionId);
        assertFalse(sessionId.isEmpty());
    }

    @Test
    void testLoginInvalidUsername() {
        String sessionId = userManager.login("nonexistent_user", "password123");
        assertNull(sessionId);
    }

    @Test
    void testLoginInvalidPassword() {
        userManager.registerUser("john_doe", "password123", "john@example.com");
        String sessionId = userManager.login("john_doe", "wrong_password");
        assertNull(sessionId);
    }

    @Test
    void testLogoutSuccess() {
        userManager.registerUser("john_doe", "password123", "john@example.com");
        String sessionId = userManager.login("john_doe", "password123");
        boolean result = userManager.logout(sessionId);
        assertTrue(result);
    }

    @Test
    void testLogoutInvalidSession() {
        boolean result = userManager.logout("invalid_session_id");
        assertFalse(result);
    }
}

