class TestUserManager {

    @Test
    void testLoginUserSuccess() {
        UserManager userManager = new UserManager();
        userManager.registerUser("testuser", "password123", "test@example.com");

        Map<String, Object> result = userManager.loginUser("testuser", "password123");

        assertTrue((Boolean) result.get("success"));
        assertNotNull(result.get("sessionToken"));
        assertTrue(result.get("sessionToken") instanceof String);
        assertNotNull(result.get("user"));
        assertTrue(result.get("user") instanceof User);

        User user = (User) result.get("user");
        assertEquals("testuser", user.getUsername());
        assertEquals("test@example.com", user.getEmail());

        // Verify session was stored
        String sessionToken = (String) result.get("sessionToken");
        // We can't directly access activeSessions, but we can verify the token format is UUID
        assertDoesNotThrow(() -> UUID.fromString(sessionToken));
    }

    @Test
    void testLoginUserInvalidUsername() {
        UserManager userManager = new UserManager();

        Map<String, Object> result = userManager.loginUser("nonexistent", "password123");

        assertFalse((Boolean) result.get("success"));
        assertEquals("Invalid username or password", result.get("message"));
        assertNull(result.get("sessionToken"));
        assertNull(result.get("user"));
    }

    @Test
    void testLoginUserInvalidPassword() {
        UserManager userManager = new UserManager();
        userManager.registerUser("testuser", "password123", "test@example.com");

        Map<String, Object> result = userManager.loginUser("testuser", "wrongpassword");

        assertFalse((Boolean) result.get("success"));
        assertEquals("Invalid username or password", result.get("message"));
        assertNull(result.get("sessionToken"));
        assertNull(result.get("user"));
    }

    @Test
    void testLoginUserEmptyUsername() {
        UserManager userManager = new UserManager();

        Map<String, Object> result = userManager.loginUser("", "password123");

        assertFalse((Boolean) result.get("success"));
        assertEquals("Invalid username or password", result.get("message"));
    }

    @Test
    void testLoginUserEmptyPassword() {
        UserManager userManager = new UserManager();
        userManager.registerUser("testuser", "password123", "test@example.com");

        Map<String, Object> result = userManager.loginUser("testuser", "");

        assertFalse((Boolean) result.get("success"));
        assertEquals("Invalid username or password", result.get("message"));
    }
}

