import java.util.*;

class BookmarkAnalyzer {

    public BookmarkAnalysisResult analyzeBookmarks(List<String> bookmarks, int minLength) {
        if (bookmarks == null) {
            throw new IllegalArgumentException("Bookmarks list cannot be null");
        }

        int count = 0;
        int totalLength = 0;
        String longestBookmark = null;
        String shortestBookmark = null;

        for (String bookmark : bookmarks) {
            if (bookmark != null && bookmark.length() >= minLength) {
                count++;
                totalLength += bookmark.length();

                if (longestBookmark == null || bookmark.length() > longestBookmark.length()) {
                    longestBookmark = bookmark;
                }

                if (shortestBookmark == null || bookmark.length() < shortestBookmark.length()) {
                    shortestBookmark = bookmark;
                }
            }
        }

        double averageLength = 0.0;
        if (count > 0) {
            averageLength = (double) totalLength / count;
        }

        return new BookmarkAnalysisResult(bookmarks.size(), count, 0, 0, averageLength, longestBookmark, shortestBookmark);
    }

    public static class BookmarkAnalysisResult {
        public int totalCount;
        public int validCount;
        public int shortCount;
        public int longCount;
        public double averageLength;
        public String longestBookmark;
        public String shortestBookmark;

        public BookmarkAnalysisResult(int totalCount, int validCount, int shortCount, int longCount, double averageLength, String longestBookmark, String shortestBookmark) {
            this.totalCount = totalCount;
            this.validCount = validCount;
            this.shortCount = shortCount;
            this.longCount = longCount;
            this.averageLength = averageLength;
            this.longestBookmark = longestBookmark;
            this.shortestBookmark = shortestBookmark;
        }

        @Override
        public String toString() {
            return "BookmarkAnalysisResult{totalCount=" + totalCount + 
                   ", validCount=" + validCount + 
                   ", shortCount=" + shortCount + 
                   ", longCount=" + longCount + 
                   ", averageLength=" + averageLength + 
                   ", longestBookmark='" + longestBookmark + "'" + 
                   ", shortestBookmark='" + shortestBookmark + "'" + 
                   '}';
