import java.lang.management.ManagementFactory;
import java.lang.management.MemoryMXBean;
import java.lang.management.OperatingSystemMXBean;
import java.lang.management.RuntimeMXBean;
import java.util.*;

public class SystemHealthMonitor {
    public Map<String, Object> getSystemHealth() {
        Map<String, Object> healthMetrics = new HashMap<>();
        healthMetrics.put("status", "HEALTHY");

        MemoryMXBean memoryBean = ManagementFactory.getMemoryMXBean();
        healthMetrics.put("heapMemoryUsage", memoryBean.getHeapMemoryUsage().getUsed());
        healthMetrics.put("nonHeapMemoryUsage", memoryBean.getNonHeapMemoryUsage().getUsed());

        OperatingSystemMXBean osBean = ManagementFactory.getOperatingSystemMXBean();
        double systemLoadAverage = osBean.getSystemLoadAverage();
        healthMetrics.put("systemLoadAverage", systemLoadAverage);

        int availableProcessors = osBean.getAvailableProcessors();
        healthMetrics.put("availableProcessors", availableProcessors);

        RuntimeMXBean runtimeBean = ManagementFactory.getRuntimeMXBean();
        healthMetrics.put("uptime", runtimeBean.getUptime());

        Runtime runtime = Runtime.getRuntime();
        healthMetrics.put("totalMemory", runtime.totalMemory());
        healthMetrics.put("freeMemory", runtime.freeMemory());

        int threadCount = Math.max(1, Thread.activeCount());
        healthMetrics.put("threadCount", threadCount);

        return healthMetrics;
    }
}

