        assertNotNull(analysis.samplePath);
        assertEquals(3, analysis.samplePath.size()); // rows + cols - 2 = 2 + 3 - 2 = 3

        // Count the moves - should have 2 Rights and 1 Down
        long rightCount = analysis.samplePath.stream().filter(move -> "Right".equals(move)).count();
        long downCount = analysis.samplePath.stream().filter(move -> "Down".equals(move)).count();

