import static org.junit.jupiter.api.Assertions.*;
import java.util.*;

class TestPathFinder {

    @org.junit.jupiter.api.Test
    public void testGridWithObstacles() {
        PathFinder pathFinder = new PathFinder();

        // Grid with obstacles (1s)
        int[][] gridWithObstacles = {
            {0, 0, 1},
            {0, 1, 0},
            {0, 0, 0}
        };

        PathFinder.PathAnalysis result = pathFinder.findUniquePathsWithAnalysis(gridWithObstacles);

        // Only 1 valid path: (0,0)->(1,0)->(2,0)->(2,1)->(2,2)
        // The path (0,0)->(0,1) is blocked by obstacle at (0,2)
        assertEquals(1, result.totalPaths);

        // Verify sample path only contains cells with value 0
        for (String coord : result.samplePath) {
            String[] parts = coord.substring(1, coord.length()-1).split(",");
            int row = Integer.parseInt(parts[0]);
            int col = Integer.parseInt(parts[1]);
            assertEquals(0, gridWithObstacles[row][col], "Sample path should only traverse cells with value 0");
        }
    }

    @org.junit.jupiter.api.Test
    public void testGridWithStartObstacle() {
        PathFinder pathFinder = new PathFinder();

        // Grid where start cell is an obstacle
        int[][] gridWithStartObstacle = {
            {1, 0},
            {0, 0}
        };

        PathFinder.PathAnalysis result = pathFinder.findUniquePathsWithAnalysis(gridWithStartObstacle);

        assertEquals(0, result.totalPaths);
        assertTrue(result.samplePath.isEmpty());
    }

    @org.junit.jupiter.api.Test
    public void testGridWithEndObstacle() {
        PathFinder pathFinder = new PathFinder();

        // Grid where end cell is an obstacle
        int[][] gridWithEndObstacle = {
            {0, 0},
            {0, 1}
        };

        PathFinder.PathAnalysis result = pathFinder.findUniquePathsWithAnalysis(gridWithEndObstacle);

        assertEquals(0, result.totalPaths);
        assertTrue(result.samplePath.isEmpty());
    }

    @org.junit.jupiter.api.Test
    public void testGridBlockedPath() {
        PathFinder pathFinder = new PathFinder();

        // Grid where all paths are blocked
        int[][] blockedGrid = {
            {0, 1, 0},
            {1, 1, 0},
            {0, 0, 0}
        };

        PathFinder.PathAnalysis result = pathFinder.findUniquePathsWithAnalysis(blockedGrid);

        assertEquals(0, result.totalPaths);
        assertTrue(result.samplePath.isEmpty());
    }
}

