import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;

class TestEnhancedBinarySearchTree {

    @Test
    void testAddSingleElement() {
        EnhancedBinarySearchTree<Integer> bst = new EnhancedBinarySearchTree<>();
        assertTrue(bst.add(5));
        assertTrue(bst.contains(5));
    }

    @Test
    void testAddMultipleElements() {
        EnhancedBinarySearchTree<Integer> bst = new EnhancedBinarySearchTree<>();
        assertTrue(bst.add(5));
        assertTrue(bst.add(3));
        assertTrue(bst.add(7));
        assertTrue(bst.add(1));
        assertTrue(bst.add(9));

        assertTrue(bst.contains(5));
        assertTrue(bst.contains(3));
        assertTrue(bst.contains(7));
        assertTrue(bst.contains(1));
        assertTrue(bst.contains(9));
    }

    @Test
    void testAddDuplicateElement() {
        EnhancedBinarySearchTree<Integer> bst = new EnhancedBinarySearchTree<>();
        assertTrue(bst.add(5));
        assertFalse(bst.add(5)); // Should return false for duplicate
        assertTrue(bst.contains(5));
    }

    @Test
    void testContainsNonExistentElement() {
        EnhancedBinarySearchTree<Integer> bst = new EnhancedBinarySearchTree<>();
        bst.add(5);
        bst.add(3);
        bst.add(7);

        assertFalse(bst.contains(10));
        assertFalse(bst.contains(1));
        assertFalse(bst.contains(4));
    }

    @Test
    void testAddNullElement() {
        EnhancedBinarySearchTree<Integer> bst = new EnhancedBinarySearchTree<>();
        assertThrows(NullPointerException.class, () -> bst.add(null));
    }

    @Test
    void testContainsOnEmptyTree() {
        EnhancedBinarySearchTree<Integer> bst = new EnhancedBinarySearchTree<>();
        assertFalse(bst.contains(5));
    }

    @Test
    void testBSTOrderingWithStrings() {
        EnhancedBinarySearchTree<String> bst = new EnhancedBinarySearchTree<>();
        bst.add("dog");
        bst.add("cat");
        bst.add("elephant");
        bst.add("ant");

        assertTrue(bst.contains("dog"));
        assertTrue(bst.contains("cat"));
        assertTrue(bst.contains("elephant"));
        assertTrue(bst.contains("ant"));
        assertFalse(bst.contains("zebra"));
    }
}

