import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;
import java.util.NoSuchElementException;

class TestEnhancedBinarySearchTree {

    @Test
    void testRemoveNullElement() {
        EnhancedBinarySearchTree<Integer> tree = new EnhancedBinarySearchTree<>();
        assertThrows(NullPointerException.class, () -> tree.remove(null));
    }

    @Test
    void testRemoveFromEmptyTree() {
        EnhancedBinarySearchTree<Integer> tree = new EnhancedBinarySearchTree<>();
        assertFalse(tree.remove(5));
    }

    @Test
    void testRemoveNonExistentElement() {
        EnhancedBinarySearchTree<Integer> tree = new EnhancedBinarySearchTree<>();
        tree.add(10);
        tree.add(5);
        tree.add(15);
        assertFalse(tree.remove(20));
        assertTrue(tree.contains(10));
        assertTrue(tree.contains(5));
        assertTrue(tree.contains(15));
    }

    @Test
    void testRemoveLeafNode() {
        EnhancedBinarySearchTree<Integer> tree = new EnhancedBinarySearchTree<>();
        tree.add(10);
        tree.add(5);
        tree.add(15);

        assertTrue(tree.remove(5));
        assertFalse(tree.contains(5));
        assertTrue(tree.contains(10));
        assertTrue(tree.contains(15));
    }

    @Test
    void testRemoveNodeWithOneChild() {
        EnhancedBinarySearchTree<Integer> tree = new EnhancedBinarySearchTree<>();
        tree.add(10);
        tree.add(5);
        tree.add(3);

        assertTrue(tree.remove(5));
        assertFalse(tree.contains(5));
        assertTrue(tree.contains(10));
        assertTrue(tree.contains(3));
    }

    @Test
    void testRemoveNodeWithTwoChildren() {
        EnhancedBinarySearchTree<Integer> tree = new EnhancedBinarySearchTree<>();
        tree.add(10);
        tree.add(5);
        tree.add(15);
        tree.add(3);
        tree.add(7);
        tree.add(12);
        tree.add(18);

        assertTrue(tree.remove(10)); // Root with two children
        assertFalse(tree.contains(10));

        // Verify BST property is maintained
        assertEquals(Integer.valueOf(3), tree.first());
        assertEquals(Integer.valueOf(18), tree.last());

        // All other elements should still be present
        assertTrue(tree.contains(5));
        assertTrue(tree.contains(15));
        assertTrue(tree.contains(3));
        assertTrue(tree.contains(7));
        assertTrue(tree.contains(12));
        assertTrue(tree.contains(18));
    }

    @Test
    void testRemoveRoot() {
        EnhancedBinarySearchTree<Integer> tree = new EnhancedBinarySearchTree<>();
        tree.add(10);

        assertTrue(tree.remove(10));
        assertFalse(tree.contains(10));
        assertThrows(NoSuchElementException.class, () -> tree.first());
    }

    @Test
    void testRemoveInOrderSuccessor() {
        EnhancedBinarySearchTree<Integer> tree = new EnhancedBinarySearchTree<>();
        tree.add(50);
        tree.add(30);
        tree.add(70);
        tree.add(20);
        tree.add(40);
        tree.add(60);
        tree.add(80);
        tree.add(35);
        tree.add(45);

        // Remove node with two children - should use in-order successor
        assertTrue(tree.remove(30));
        assertFalse(tree.contains(30));

        // Verify BST property maintained
        assertEquals(Integer.valueOf(20), tree.first());
        assertEquals(Integer.valueOf(80), tree.last());

        // All other elements should be present
        assertTrue(tree.contains(50));
        assertTrue(tree.contains(70));
        assertTrue(tree.contains(20));
        assertTrue(tree.contains(40));
        assertTrue(tree.contains(60));
        assertTrue(tree.contains(80));
        assertTrue(tree.contains(35));
        assertTrue(tree.contains(45));
    }
}

