import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;
import java.util.HashMap;
import java.util.Map;

class TestGraphDatabaseManager {

    @Test
    void testGetNodeInfoWithValidNode() {
        GraphDatabaseManager manager = new GraphDatabaseManager();

        Map<String, Object> nodeProps = new HashMap<>();
        nodeProps.put("name", "Alice");
        nodeProps.put("age", 30);
        long nodeId = manager.createNode(nodeProps);

        String info = manager.getNodeInfo(nodeId);

        assertTrue(info.contains("Node ID: " + nodeId));
        assertTrue(info.contains("Properties: {name=Alice, age=30}") || info.contains("Properties: {age=30, name=Alice}"));
        assertTrue(info.contains("Relationships: None"));
    }

    @Test
    void testGetNodeInfoWithRelationships() {
        GraphDatabaseManager manager = new GraphDatabaseManager();

        long node1 = manager.createNode(new HashMap<>());
        long node2 = manager.createNode(new HashMap<>());

        Map<String, Object> relProps = new HashMap<>();
        relProps.put("since", 2020);
        long relId = manager.createRelationship(node1, node2, "KNOWS", relProps);

        String info = manager.getNodeInfo(node1);

        assertTrue(info.contains("Node ID: " + node1));
        assertTrue(info.contains("Properties: {}"));
        assertTrue(info.contains("[" + relId + "] KNOWS (" + node1 + ") -> (" + node2 + ") {since=2020}"));
    }

    @Test
    void testGetNodeInfoWithInvalidNode() {
        GraphDatabaseManager manager = new GraphDatabaseManager();

        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class, () -> {
            manager.getNodeInfo(999L);
        });

        assertEquals("Error: Invalid node information requested.", exception.getMessage());
    }

    @Test
    void testGetNodeInfoWithMultipleRelationships() {
        GraphDatabaseManager manager = new GraphDatabaseManager();

        long node1 = manager.createNode(new HashMap<>());
        long node2 = manager.createNode(new HashMap<>());
        long node3 = manager.createNode(new HashMap<>());

        long rel1 = manager.createRelationship(node1, node2, "FOLLOWS", new HashMap<>());
        long rel2 = manager.createRelationship(node3, node1, "LIKES", new HashMap<>());

        String info = manager.getNodeInfo(node1);

        assertTrue(info.contains("[" + rel1 + "] FOLLOWS (" + node1 + ") -> (" + node2 + ") {}"));
        assertTrue(info.contains("[" + rel2 + "] LIKES (" + node3 + ") -> (" + node1 + ") {}"));
    }
}

