        assertEquals("😂", systemEmojis.get(1).getCharacter());
        assertEquals("face with tears of joy", systemEmojis.get(1).getDescription());
        assertEquals("❤️", systemEmojis.get(2).getCharacter());
        assertEquals("red heart", systemEmojis.get(2).getDescription());
        assertEquals("👍", systemEmojis.get(3).getCharacter());
        assertEquals("thumbs up", systemEmojis.get(3).getDescription());
        assertEquals("🎉", systemEmojis.get(4).getCharacter());
        assertEquals("party popper", systemEmojis.get(4).getDescription());
    }

    @Test
    public void testSystemCategoryUsesGeneratedEmojis() {
        EmojiManager manager = new EmojiManager(false, false, true);

        // Find the System category
        EmojiManager.EmojiCategory systemCategory = null;
        for (EmojiManager.EmojiCategory category : manager.getCategories()) {
            if ("System".equals(category.getName())) {
                systemCategory = category;
                break;
            }
        }

        assertNotNull(systemCategory);
        assertEquals(5, systemCategory.getEmojiCount());
        assertEquals("😀", systemCategory.getEmojis().get(0).getCharacter());
        assertEquals("🎉", systemCategory.getEmojis().get(4).getCharacter());
    }

    @Test
    public void testAddCustomEmojiResource() {
        EmojiManager manager = new EmojiManager(false, true, false);

        manager.addCustomEmojiResource("smile", "😊");
        manager.addCustomEmojiResource("wave", "👋");

        // Find the Custom category
        EmojiManager.EmojiCategory customCategory = null;
        for (EmojiManager.EmojiCategory category : manager.getCategories()) {
            if ("Custom".equals(category.getName())) {
                customCategory = category;
                break;
            }
        }

        assertNotNull(customCategory);
        assertEquals(2, customCategory.getEmojiCount());

        // Check that emojis are added (order may vary due to HashMap)
        List<EmojiManager.Emoji> emojis = customCategory.getEmojis();
        boolean hasSmile = false, hasWave = false;
        for (EmojiManager.Emoji emoji : emojis) {
            if ("😊".equals(emoji.getCharacter()) && "smile".equals(emoji.getDescription())) {
                hasSmile = true;
            }
            if ("👋".equals(emoji.getCharacter()) && "wave".equals(emoji.getDescription())) {
                hasWave = true;
            }
        }
        assertTrue(hasSmile);
        assertTrue(hasWave);
    }

    @Test
    public void testAddCustomEmojiResourceWithoutCustomCategory() {
        EmojiManager manager = new EmojiManager(false, false, false);

        // Should not throw exception even if Custom category doesn't exist
        assertDoesNotThrow(() -> {
            manager.addCustomEmojiResource("test", "🔥");
        });
    }
}

