import java.util.HashMap;
import java.util.Map;

class AgricultureDataValidator {

    public Map<String, Object> validateAndProcessData(String ph, String humidity, String fertilizer, String temperature, String irrigation) {
        Map<String, Object> result = new HashMap<>();
        result.put("isValid", true);

        // Validate pH
        try {
            double phValue = Double.parseDouble(ph);
            if (phValue < 0 || phValue > 14) {
                result.put("isValid", false);
                result.put("error", "pH incorrecto, debe estar entre 0 y 14.");
            }
        } catch (NumberFormatException e) {
            result.put("isValid", false);
            result.put("error", "pH debe ser un número válido.");
        }

        return result;
    }
}

