import static org.junit.jupiter.api.Assertions.*;
import java.util.*;

class TestAdvancedFlagProcessor {

    @org.junit.jupiter.api.Test
    public void testMutuallyExclusiveFlagsDetected() {
        Set<String> validFlags = Set.of("a", "b", "c");
        Set<String> mutuallyExclusiveGroups = Set.of("a", "b");
        AdvancedFlagProcessor processor = new AdvancedFlagProcessor(validFlags, mutuallyExclusiveGroups);

        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class, () -> {
            processor.processFlags("ab");
        });
        assertEquals("Mutually exclusive flags detected", exception.getMessage());
    }

    @org.junit.jupiter.api.Test
    public void testSingleMutuallyExclusiveFlagAllowed() {
        Set<String> validFlags = Set.of("a", "b", "c");
        Set<String> mutuallyExclusiveGroups = Set.of("a", "b");
        AdvancedFlagProcessor processor = new AdvancedFlagProcessor(validFlags, mutuallyExclusiveGroups);

        // Should not throw exception with only one mutually exclusive flag
        assertDoesNotThrow(() -> {
            processor.processFlags("a");
        });

        assertDoesNotThrow(() -> {
            processor.processFlags("b");
        });
    }

    @org.junit.jupiter.api.Test
    public void testNonMutuallyExclusiveFlagsAllowed() {
        Set<String> validFlags = Set.of("a", "b", "c", "d");
        Set<String> mutuallyExclusiveGroups = Set.of("a", "b");
