        assertTrue(result.contains("|a"), "Should contain |a");
        assertTrue(result.contains("|b"), "Should contain |b");
        assertTrue(result.contains("|c"), "Should contain |c");
        assertEquals(3, result.size(), "Should contain exactly 3 flags");
    }
}

