@Test
public void testMergeCandidatesSimple() {
    var arr = new NodeArray(2);

    // Test normal insertion using helper methods
    int result1 = arr.insertSorted(1, 1.0f);
    assertTrue(result1 >= 0);

    // Test duplicate insertion - should call insertionPoint and return -1
    int result2 = arr.insertSorted(1, 1.0f);
    assertEquals(-1, result2);

    // Test array growth - should call growArrays() when full
    int result3 = arr.insertSorted(2, 2.0f);
    assertTrue(result3 >= 0);

    // Fill array to capacity to force growth
    arr.insertSorted(3, 3.0f);

    // This insertion should trigger growArrays() and use insertInternal
    int result4 = arr.insertSorted(4, 4.0f);
    assertTrue(result4 >= 0);

    // Verify that insertionPoint helper correctly identifies duplicates
    int result5 = arr.insertSorted(2, 2.0f);
    assertEquals(-1, result5);

    // Verify insertInternal was used for actual insertions
    assertTrue(arr.size() > 2); // Should have grown beyond initial capacity
}

