public void testMarkingAllNodesAsDeleted() {
    // Test thread safety by verifying synchronized method behavior
    // and layer coordination with entry point selection from highest available layer
    testMarkingAllNodesAsDeleted(false);
    testMarkingAllNodesAsDeleted(true);

    // Verify that the synchronized method maintains thread safety
    // by testing that concurrent access doesn't cause issues
    Thread t1 = new Thread(() -> testMarkingAllNodesAsDeleted(false));
    Thread t2 = new Thread(() -> testMarkingAllNodesAsDeleted(true));

    t1.start();
    t2.start();

    try {
        t1.join();
        t2.join();
    } catch (InterruptedException e) {
        Thread.currentThread().interrupt();
        throw new RuntimeException("Test interrupted", e);
    }
