    public GraphIndexBuilder(BuildScoreProvider scoreProvider,
                             int dimension,
                             List<Integer> maxDegrees,
                             int beamWidth,
                             float neighborOverflow,
                             float alpha,
                             boolean addHierarchy,
                             boolean refineFinalGraph,
