    arr1.addInOrder(300, 3.0f);  // tie group
    arr1.addInOrder(400, 1.0f);  // low score

    var arr2 = new NodeArray(4);
    arr2.addInOrder(200, 3.0f);  // duplicate in tie group
    arr2.addInOrder(500, 3.0f);  // new node in tie group
    arr2.addInOrder(600, 3.0f);  // new node in tie group
    arr2.addInOrder(700, 1.0f);  // low score

    var merged = NodeArray.merge(arr1, arr2);

    // Expected: deduplication within score groups using set
    // Score 5.0f: [100]
    // Score 3.0f: [200, 300, 500, 600] (200 deduplicated)
    // Score 1.0f: [400, 700]
    assertArrayEquals(new int[] {100, 200, 300, 500, 600, 400, 700}, merged.copyDenseNodes());
    assertArrayEquals(new float[] {5.0f, 3.0f, 3.0f, 3.0f, 3.0f, 1.0f, 1.0f}, merged.copyDenseScores(), 0.0f);

