    assertTrue(merged != nonEmptyArr);
    assertTrue(merged != emptyArr);
    assertArrayEquals(new int[] {5, 3}, merged.copyDenseNodes());
    assertArrayEquals(new float[] {5.0f, 3.0f}, merged.copyDenseScores(), 0.0f);

    // Empty second array - must return NEW array with non-empty array's elements
    merged = NodeArray.merge(nonEmptyArr, emptyArr);
