@Test
public void testMergeCandidatesSimple() {
    // Test the specific optimization: bulk-copy performance after duplicate handling
    // Create a scenario where one array is exhausted, leaving many elements in the other
    // with both duplicates at the last processed score AND many different-score elements
    var arr1 = new NodeArray(1);
    arr1.addInOrder(100, 10.0f);

    var arr2 = new NodeArray(10);
    arr2.addInOrder(200, 10.0f); // duplicate with last processed score
    arr2.addInOrder(300, 10.0f); // another duplicate with last processed score
    // These should be bulk-copied using System.arraycopy for performance
    arr2.addInOrder(400, 9.0f);
    arr2.addInOrder(500, 8.0f);
    arr2.addInOrder(600, 7.0f);
    arr2.addInOrder(700, 6.0f);
    arr2.addInOrder(800, 5.0f);
    arr2.addInOrder(900, 4.0f);
    arr2.addInOrder(1000, 3.0f);
    arr2.addInOrder(1100, 2.0f);

    var merged = NodeArray.merge(arr1, arr2);
    // Expected: [200, 100, 300, 400, 500, 600, 700, 800, 900, 1000, 1100]
    // The key test: duplicates (200, 300) are handled individually, 
    // but elements 400-1100 should be bulk-copied for performance
    assertArrayEquals(new int[] {200, 100, 300, 400, 500, 600, 700, 800, 900, 1000, 1100}, merged.copyDenseNodes());
    assertArrayEquals(new float[] {10.0f, 10.0f, 10.0f, 9.0f, 8.0f, 7.0f, 6.0f, 5.0f, 4.0f, 3.0f, 2.0f}, merged.copyDenseScores(), 0.0f);

    // Test bulk copy optimization when arr1 has remaining elements
    arr1 = new NodeArray(5);
    arr1.addInOrder(50, 5.0f); // will match last processed score
    arr1.addInOrder(60, 4.0f); // different score - should be bulk copied
    arr1.addInOrder(70, 3.0f); // different score - should be bulk copied
    arr1.addInOrder(80, 2.0f); // different score - should be bulk copied
    arr1.addInOrder(90, 1.0f); // different score - should be bulk copied

    arr2 = new NodeArray(1);
    arr2.addInOrder(20, 5.0f); // will be last processed score

    merged = NodeArray.merge(arr1, arr2);
    // Expected: [20, 50, 60, 70, 80, 90]
    // After main loop: [20, 50] (lastAddedScore = 5.0f, nodesWithLastScore = {20, 50})
    // Processing remaining arr1: 60,70,80,90 bulk copied
    assertArrayEquals(new int[] {20, 50, 60, 70, 80, 90}, merged.copyDenseNodes());
    assertArrayEquals(new float[] {5.0f, 5.0f, 4.0f, 3.0f, 2.0f, 1.0f}, merged.copyDenseScores(), 0.0f);
    validateSortedByScore(merged);
}

