        throw FlexExceptions.wrap("Error parsing property name '%s'.  Didn't start with 'is', 'get' or 'set'.", name);
    }
    if (!name.isEmpty()) {
        name = name.substring(0, 1).toLowerCase(Locale.ENGLISH).concat(name.substring(1));
    }
    return name;
}

