@Test
void should_load_documents_including_unknown_document_types() {
    // given
    Path resourceDirectory = resourceDirectory();
    Path nonDirectoryPath = resourceDirectory.resolve("test-file.txt");

    // when - valid directory should return empty list
    List<Document> documents = loadDocuments(resourceDirectory, new TextDocumentParser());

    // then
    assertThat(documents).isEmpty();

    // when-then - non-directory should throw IllegalArgumentException
    assertThatThrownBy(() -> loadDocuments(nonDirectoryPath, new TextDocumentParser()))
        .isInstanceOf(IllegalArgumentException.class)
        .hasMessage("Illegal directoryPath.");
}

