public float rerank(int topK, ScoreFunction.ExactScoreFunction reranker, float rerankFloor, NodeQueue reranked, NodesUnsorted unused) {
    // Map to maintain approximate scores by node ID
    var approximateScoresById = new Int2ObjectHashMap<Float>();

    // First pass: identify items above floor and find best item
    int[] nodeIds = new int[size()];
    boolean[] isAboveFloor = new boolean[size()];
    int aboveFloorCount = 0;
    int bestItemIndex = -1;
    float bestApproximateScore = Float.NEGATIVE_INFINITY;

    for (int i = 0; i < size(); i++) {
        long heapValue = heap.get(i + 1);
        int nodeId = decodeNodeId(heapValue);
        float approxScore = decodeScore(heapValue);

        nodeIds[i] = nodeId;
        approximateScoresById.put(nodeId, Float.valueOf(approxScore));

        // Track best item for fallback case
        if (approxScore > bestApproximateScore) {
            bestApproximateScore = approxScore;
            bestItemIndex = i;
        }

        if (approxScore >= rerankFloor) {
            isAboveFloor[i] = true;
            aboveFloorCount++;
        } else {
            isAboveFloor[i] = false;
        }
    }

    // Handle case where no items meet rerankFloor
    if (aboveFloorCount == 0 && bestItemIndex >= 0) {
        // Rerank the single best item
        float exactScore = reranker.similarityTo(nodeIds[bestItemIndex]);
        reranked.push(nodeIds[bestItemIndex], exactScore);

        // Add all other items to unused
        for (int i = 0; i < size(); i++) {
            if (i != bestItemIndex) {
                unused.add(nodeIds[i], approximateScoresById.get(nodeIds[i]));
            }
        }

        return bestApproximateScore;
    }

    // Normal case: process items above floor
    float[] exactScores = new float[size()];

    // Compute exact scores for items above floor
    for (int i = 0; i < size(); i++) {
        if (isAboveFloor[i]) {
            exactScores[i] = reranker.similarityTo(nodeIds[i]);
        } else {
            // Add items below floor directly to unused
            unused.add(nodeIds[i], approximateScoresById.get(nodeIds[i]));
        }
    }

    // Select topK from items above floor using their exact scores
    boolean[] selected = new boolean[size()];
    int selectedCount = 0;

    for (int k = 0; k < topK && selectedCount < aboveFloorCount; k++) {
        int bestIdx = -1;
        float bestScore = Float.NEGATIVE_INFINITY;

        for (int i = 0; i < size(); i++) {
            if (isAboveFloor[i] && !selected[i] && exactScores[i] > bestScore) {
                bestScore = exactScores[i];
                bestIdx = i;
            }
        }

        if (bestIdx >= 0) {
            selected[bestIdx] = true;
            reranked.push(nodeIds[bestIdx], exactScores[bestIdx]);
            selectedCount++;
        }
    }

    // Add remaining above-floor items to unused with their approximate scores
    for (int i = 0; i < size(); i++) {
        if (isAboveFloor[i] && !selected[i]) {
            unused.add(nodeIds[i], approximateScoresById.get(nodeIds[i]));
        }
    }

    // Return worst approximate score among selected topK using the map
    if (selectedCount < topK) {
        return Float.POSITIVE_INFINITY;
    }

    float worstApproximate = Float.POSITIVE_INFINITY;
    for (int i = 0; i < size(); i++) {
        if (selected[i]) {
            worstApproximate = Math.min(worstApproximate, approximateScoresById.get(nodeIds[i]));
        }
    }

    return worstApproximate;
}

