public static <T> @Nullable T meldProperty(@Nullable T a, @Nullable T b) {
    if (a == null && b == null) {
        return null;
    }
    if (a == null) {
        return b;
    }
    if (b == null) {
        return a;
    }
    return mergeProperty(a, b);
}

