@Test
public void copyToTarget() {
    var portableOptions = new TestPortableOptionsImpl();
    portableOptions.setName("John");
    portableOptions.setAge(30);
    portableOptions.setNonInterfaceField("NonInterfaceField");

    TestSpecificOptions target = ModelOptionsUtils.copyToTarget(portableOptions, TestPortableOptions.class,
            TestSpecificOptions.class);

    // Only interface-defined fields should be copied
    assertThat(target.getAge()).isEqualTo(30);
    assertThat(target.getName()).isEqualTo("John");
    assertThat(target.getSpecificField()).isNull();

    // Verify that non-interface field is NOT copied
    try {
        java.lang.reflect.Field nonInterfaceField = target.getClass().getDeclaredField("nonInterfaceField");
        nonInterfaceField.setAccessible(true);
        Object nonInterfaceValue = nonInterfaceField.get(target);
        assertThat(nonInterfaceValue).isNull(); // Should be null because it's not in the interface
    } catch (NoSuchFieldException e) {
        // Field doesn't exist in target class, which is fine
    } catch (IllegalAccessException e) {
        // Handle reflection access exception
        throw new RuntimeException("Failed to access field via reflection", e);
    }
}

