public static String camelToUnderline(String string) {
    if (string == null || string.isEmpty()) {
        return "";
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < string.length(); i++) {
        char c = string.charAt(i);
        if (Character.isUpperCase(c) && i > 0) {
            sb.append('_');
        }
        sb.append(Character.toLowerCase(c));
    }
    return sb.toString();
}

records.current_test:
@Test
public void underlineToCamel() {
    // Test basic camelCase conversion
    String camelCase = "aaBb";
    String result = StringUtil.camelToUnderline(camelCase);
    Assert.assertEquals("aa_bb", result);

    // Test null input
    Assert.assertEquals("", StringUtil.camelToUnderline(null));

    // Test empty input
    Assert.assertEquals("", StringUtil.camelToUnderline(""));

    // Test single character
    Assert.assertEquals("a", StringUtil.camelToUnderline("a"));
    Assert.assertEquals("a", StringUtil.camelToUnderline("A"));
}

