public void testIncrementalWrites() throws IOException {
    // generate small graph for precise position testing
    var graph = new TestUtil.RandomlyConnectedGraphIndex(100, 32, getRandom());
    var vectors = TestUtil.createRandomVectors(100, 256);
    var ravv = new ListRandomAccessVectorValues(vectors, 256);

