    var incrementalPath = testDirectory.resolve("incremental_graph");
    try (var writer = new OnDiskGraphIndexWriter.Builder(graph, incrementalPath)
            .with(new InlineVectors(ravv.dimension()))
            .build())
    {
        // write vectors in non-sequential order: 5, 2, 8, 1
        // This tests that featureOffsetForOrdinal is used for exact positioning
        int[] ordinals = {5, 2, 8, 1};
        for (int ordinal : ordinals) {
            var state = Feature.singleState(FeatureId.INLINE_VECTORS, new InlineVectors.State(ravv.getVector(ordinal)));
            writer.writeInline(ordinal, state);
        }

        // write graph structure
        writer.write(Map.of());
    }

    // verify that data was written at correct positions by reading back in original order
    try (var readerSupplier = new SimpleMappedReader.Supplier(incrementalPath.toAbsolutePath());
         var graph2 = OnDiskGraphIndex.load(readerSupplier);
         var view = graph2.getView())
    {
        // verify that vectors written out of order can be read back in correct positions
        for (int ordinal : new int[]{1, 2, 5, 8}) {
            var vector = view.getVector(ordinal);
            assertNotNull(vector);
            assertEquals(256, vector.length());
            // verify the vector is not zero (indicating data was written)
            assertTrue(vector.length() > 0);
        }
    }
}

